import { useEffect, useRef, useCallback, useState, useMemo } from 'react'
import { AppProvider, useAppContext, loadVaults, importFile, importFolder, exportVault, reloadVaultTree } from './state'
import { ApiClient } from './api'
import { AuthProvider, useAuthContext, getStoredAuthToken, getStoredCsrfToken } from './state/authContext'
import { TabProvider, useTabContext } from './state/tabContext'
import { FeatureProvider, useFeatureContext } from './state/featureContext'
import { SearchProvider } from './state/searchContext'
import { createDailyNoteService, loadDailyNotesConfigFromServer } from './state/dailyNoteService'
import { openTab } from './state/tabActions'
import { initialize as initializeRecentFiles, disconnect as disconnectRecentFiles } from './state/recentFilesStore'
import { initialize as initializeFavorites, disconnect as disconnectFavorites } from './state/favoritesStore'
import { initialize as initializeKeybindings, disconnect as disconnectKeybindings } from './state/keybindingsStore'
import { I18nProvider, useTranslation } from './i18n'
import { RealtimeProvider, type RealtimeEventHandlers } from './components/RealtimeProvider'
import { ToastNotification, showToast } from './components/ToastNotification'
import { GlobalTooltip } from './components/GlobalTooltip'
import { HoverPreview } from './components/HoverPreview'
import { ConnectionIndicator } from './components/ConnectionIndicator'
import { useRealtimeContext } from './state/realtimeContext'
import {
  dispatchRealtimeChatMessage,
  dispatchRealtimeUnreadUpdate,
  dispatchRealtimeConversationPreview,
  onRealtimeUnreadUpdate,
} from './state/realtimeChatBridge'
import { dispatchRealtimeVaultChange, onRealtimeVaultChange } from './state/realtimeVaultBridge'
import type { VaultChangeEvent } from './state/realtimeVaultBridge'
import { dispatchPluginSettingsChange } from './state/pluginSettingsChangeBridge'
import { FileExplorer } from './components/FileExplorer'
import { TabContent } from './components/TabContent'
import { ErrorBoundary } from './components/ErrorBoundary'
import { UserMenu } from './components/UserMenu'
import { LoginPage } from './components/LoginPage'
import { ChangePasswordPage } from './components/ChangePasswordPage'
import { ProfilePage } from './components/ProfilePage'
import { SessionsPage } from './components/SessionsPage'
import { AdminUsersPage } from './components/AdminUsersPage'
import { AdminConfigPage } from './components/AdminConfigPage'
import { AdminAuditPage } from './components/AdminAuditPage'
import { AdminLogsPage } from './components/AdminLogsPage'
import { AdminVaultsPage } from './components/AdminVaultsPage'
import { VaultSharing } from './components/VaultSharing'
import { VaultDeletionWorkflow } from './components/VaultDeletionWorkflow'
import { ChatPage } from './components/ChatPage'
import { SlatebaseLogo } from './components/SlatebaseLogo'
import { SidebarToolbar } from './components/SidebarToolbar'
import { StatusBar } from './components/StatusBar'
import { MyVaultsPage } from './components/MyVaultsPage'
import { McpTokensPage } from './components/McpTokensPage'
import { PluginManagementPage } from './components/PluginManagementPage'
import { PluginViewPanel } from './components/PluginViewPanel'
import { TrashView } from './components/TrashView'
import { VersionBrowser } from './components/VersionBrowser'
import { useVersionInfo } from './hooks/useVersionInfo'
import { ContextPanelProvider, useContextPanelContext } from './state/contextPanelContext'
import { SidebarPanelProvider } from './state/sidebarPanelContext'
import { ContextPanel } from './components/context-panel/ContextPanel'
import { SettingsPanel } from './components/settings/SettingsPanel'
import type { SettingsCategory, SettingsSection } from './state/settingsState'
import { SidebarPanel } from './components/sidebar-panel'
import { PluginProvider } from './plugins/compat/plugin-context'
import { CommandPaletteContainer } from './components/CommandPaletteContainer'
import { TabBar, type SettingsTabDescriptor } from './components/TabBar'
import { useResize } from './hooks/useResize'
import { useStatusBar } from './hooks/useStatusBar'
import { useGlobalShortcuts } from './hooks/useGlobalShortcuts'
import { useWorkspaceRestore, LAST_VAULT_KEY } from './hooks/useWorkspaceRestore'
import { initialize as initializeWorkspace, getState as getWorkspaceState, clear as clearWorkspace } from './state/workspaceStore'
import {
  User, Settings, Shield, FileText, Clock,
  Database, Share2, Trash2, Server,
  PanelRight, PanelLeft, X, MessageCircle, Key, ScrollText, Plug,
} from 'lucide-react'
import './App.css'

/** Singleton ApiClient instance shared across the app. */
const apiClient = new ApiClient()

/** Singleton DailyNoteService instance. */
const dailyNoteService = createDailyNoteService(apiClient)

// Synchronous token restore from localStorage ÔÇö eliminates race condition
// where API calls fire before the useEffect in AuthGuard sets the token.
const _storedToken = getStoredAuthToken()
const _storedCsrf = getStoredCsrfToken()
if (_storedToken) apiClient.setToken(_storedToken)
if (_storedCsrf) apiClient.setCsrfToken(_storedCsrf)

// Synchronous workspace state restore from localStorage ÔÇö must run before
// any component reads getWorkspaceState() in their useState initializers.
initializeWorkspace()

/** Available navigation pages in the app (opened as tabs in the main content area). */
export type AppPage =
  | 'my-vaults'
  | 'profile'
  | 'sessions'
  | 'chat'
  | 'admin-users'
  | 'admin-vaults'
  | 'admin-config'
  | 'admin-audit'
  | 'admin-logs'
  | 'vault-sharing'
  | 'vault-deletion'
  | 'mcp-tokens'
  | 'plugins'
  | 'trash'

/** Translation keys for navigation pages. */
const PAGE_LABEL_KEYS: Record<AppPage, string> = {
  'my-vaults': 'pages.myVaults',
  profile: 'pages.profile',
  sessions: 'pages.sessions',
  chat: 'pages.chat',
  'admin-users': 'pages.adminUsers',
  'admin-vaults': 'pages.adminVaults',
  'admin-config': 'pages.adminConfig',
  'admin-audit': 'pages.adminAudit',
  'admin-logs': 'pages.adminLogs',
  'vault-sharing': 'pages.vaultSharing',
  'vault-deletion': 'pages.vaultDeletion',
  'mcp-tokens': 'pages.mcpTokens',
  plugins: 'pages.plugins',
  trash: 'pages.trash',
}

/** Icons for settings pages. */
const PAGE_ICONS: Partial<Record<AppPage, React.ReactNode>> = {
  'my-vaults': <Database size={13} />,
  profile: <User size={13} />,
  sessions: <Clock size={13} />,
  chat: <MessageCircle size={13} />,
  'admin-users': <Shield size={13} />,
  'admin-vaults': <Server size={13} />,
  'admin-config': <Settings size={13} />,
  'admin-audit': <FileText size={13} />,
  'admin-logs': <ScrollText size={13} />,
  'vault-sharing': <Share2 size={13} />,
  'vault-deletion': <Trash2 size={13} />,
  'mcp-tokens': <Key size={13} />,
  plugins: <Plug size={13} />,
  trash: <Trash2 size={13} />,
}

/**
 * Hint shown when navigating directly to a disabled feature page.
 */
function FeatureDisabledHint({ featureName }: { featureName: string }) {
  return (
    <div style={{ padding: 32, color: 'var(--text-muted)', textAlign: 'center' }}>
      <p>Das Feature ÔÇ×{featureName}" ist derzeit deaktiviert.</p>
    </div>
  )
}

/**
 * Small wrapper that reads RealtimeContext to render the ConnectionIndicator.
 */
function RealtimeConnectionIndicator() {
  const { state } = useRealtimeContext()

  return (
    <ConnectionIndicator
      status={state.connectionStatus}
    />
  )
}

/**
 * Inner component that uses AppContext and TabContext to render the main vault view.
 */
function AppContent() {
  const { state, dispatch } = useAppContext()
  const { authState, authDispatch } = useAuthContext()
  const { tabState, tabDispatch } = useTabContext()
  const { isEnabled } = useFeatureContext()
  const { state: contextPanelState, dispatch: contextPanelDispatch } = useContextPanelContext()
  const { t } = useTranslation()
  const prevVaultId = useRef<string | null>(null)
  // Per-vault tab memory: saves tabs when switching away, restores when switching back
  const vaultTabsCacheRef = useRef<Map<string, { tabs: Array<{ filePath: string; fileName: string }>; activeTabId: string | null }>>(new Map())
  // Navigation tabs: list of open pages + which is active
  const [openSettingsPages, setOpenSettingsPages] = useState<AppPage[]>([])
  const [activeSettingsPage, setActiveSettingsPage] = useState<AppPage | null>(() => getWorkspaceState().activeSettingsPage)
  const [showRightPanel, setShowRightPanel] = useState(() => getWorkspaceState().rightPanelVisible)
  const [showSidebar, setShowSidebar] = useState(() => getWorkspaceState().sidebarVisible)
  const fileInputRef = useRef<HTMLInputElement>(null)
  const folderInputRef = useRef<HTMLInputElement>(null)
  const createFileTriggerRef = useRef<(() => void) | null>(null)
  const createFolderTriggerRef = useRef<(() => void) | null>(null)
  const createVaultTriggerRef = useRef<(() => void) | null>(null)
  const createCanvasTriggerRef = useRef<(() => void) | null>(null)

  const handleRegisterCreateFile = useCallback((trigger: () => void) => { createFileTriggerRef.current = trigger }, [])
  const handleRegisterCreateFolder = useCallback((trigger: () => void) => { createFolderTriggerRef.current = trigger }, [])
  const handleRegisterCreateVault = useCallback((trigger: () => void) => { createVaultTriggerRef.current = trigger }, [])
  const handleRegisterCreateCanvas = useCallback((trigger: () => void) => { createCanvasTriggerRef.current = trigger }, [])

  // Version browser state: which file to show versions for
  const [versionBrowserTarget, setVersionBrowserTarget] = useState<{ vaultId: string; filePath: string } | null>(null)

  // Opens the version browser for a given file (file-recovery:open core command).
  useEffect(() => {
    function handleOpenFileRecovery(e: Event) {
      const detail = (e as CustomEvent<{ vaultId: string; filePath: string }>).detail
      if (!detail?.vaultId || !detail?.filePath) return
      setVersionBrowserTarget({ vaultId: detail.vaultId, filePath: detail.filePath })
    }
    window.addEventListener('slatebase:open-file-recovery', handleOpenFileRecovery)
    return () => window.removeEventListener('slatebase:open-file-recovery', handleOpenFileRecovery)
  }, [])

  const sidebar = useResize(260, 180, 400, 'left', 'sidebarWidth')
  const rightPanel = useResize(240, 160, 500, 'right', 'rightPanelWidth')
  const versionInfo = useVersionInfo()

  // Refresh key for sidebar panel views (favorites, recent files)
  const [sidebarRefreshKey, setSidebarRefreshKey] = useState(0)

  // Unified Settings Panel state
  const [settingsOpen, setSettingsOpen] = useState(false)
  const [settingsInitialNav, setSettingsInitialNav] = useState<{ category: SettingsCategory; section: SettingsSection } | undefined>(undefined)

  // Status bar visibility (persisted in localStorage)
  const { visible: statusBarVisible } = useStatusBar()

  // Global unread count polling (30-second interval)
  // Disabled when SSE connection is active (realtime pushes unread counts)
  const { state: realtimeState } = useRealtimeContext()
  const [globalUnreadCount, setGlobalUnreadCount] = useState(0)

  // Register the unread update callback with the realtime bridge
  useEffect(() => {
    return onRealtimeUnreadUpdate((totalUnread) => {
      setGlobalUnreadCount(totalUnread)
    })
  }, [])

  // Register the vault change callback with the realtime bridge
  // Refreshes the file explorer tree and reloads affected open tabs
  useEffect(() => {
    return onRealtimeVaultChange((event) => {
      const { vaultId, action, path } = event

      // Refresh the file explorer tree for the affected vault
      // Only refresh if the vault tree is already loaded (user has expanded it)
      if (state.vaultTrees[vaultId] !== undefined) {
        void reloadVaultTree(dispatch, apiClient, vaultId)
      }

      // Reload content of open tabs affected by this change
      const affectedTabs = tabState.tabs.filter(
        (tab) => tab.vaultId === vaultId && tab.filePath === path
      )

      for (const tab of affectedTabs) {
        if (action === 'deleted') {
          // File was deleted ÔÇö close the tab
          tabDispatch({ type: 'CLOSE_TAB', payload: { tabId: tab.id } })
        } else if (action === 'saved' || action === 'renamed') {
          // File was saved/renamed by another user ÔÇö reload content if no unsaved edits
          if (tab.editBuffer === null) {
            // No local edits ÔÇö safe to reload
            tabDispatch({ type: 'TAB_CONTENT_LOADED', payload: { tabId: tab.id, content: '', isBinary: tab.isBinary } })
            // Fetch fresh content
            apiClient.fetchFileContent(vaultId, path).then((result) => {
              tabDispatch({
                type: 'TAB_CONTENT_LOADED',
                payload: { tabId: tab.id, content: result.content, isBinary: result.isBinary },
              })
            }).catch(() => {
              // If fetch fails (e.g. file no longer exists), close tab
              tabDispatch({ type: 'CLOSE_TAB', payload: { tabId: tab.id } })
            })
          }
          // If there are unsaved local edits, don't reload ÔÇö user would lose their work
          // The toast notification already informed them about the external change
        }
      }
    })
  }, [state.vaultTrees, tabState.tabs, dispatch, tabDispatch])

  useEffect(() => {
    // Skip polling when SSE is connected ÔÇö unread updates come via realtime push
    if (realtimeState.connectionStatus === 'connected') return

    let cancelled = false

    const poll = async () => {
      try {
        const result = await apiClient.getUnreadTotal()
        if (!cancelled) {
          setGlobalUnreadCount(result.total)
        }
      } catch {
        // Silently ignore polling errors (e.g. network issues, 401)
      }
    }

    // Initial poll
    poll()

    // Set up 30-second interval
    const intervalId = setInterval(poll, 30_000)

    return () => {
      cancelled = true
      clearInterval(intervalId)
    }
  }, [realtimeState.connectionStatus])

  // Fetch vaults on mount
  useEffect(() => {
    loadVaults(dispatch, apiClient)
    // Initialize per-user server-synced stores
    initializeRecentFiles(apiClient).catch(() => { /* ignore */ })
    initializeFavorites(apiClient).catch(() => { /* ignore */ })
    initializeKeybindings(apiClient).catch(() => { /* ignore */ })
  }, [dispatch])

  useWorkspaceRestore({
    vaults: state.vaults,
    selectedVaultId: state.selectedVaultId,
    dispatch,
    tabs: tabState.tabs,
    activeTabId: tabState.activeTabId,
    tabDispatch,
    activeSettingsPage,
    showSidebar,
    showRightPanel,
    apiClient,
  })

  // When a file tab becomes active (e.g. from FileExplorer click), deactivate settings page
  useEffect(() => {
    if (tabState.activeTabId && activeSettingsPage !== null) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setActiveSettingsPage(null)
    }
  }, [tabState.activeTabId]) // eslint-disable-line react-hooks/exhaustive-deps

  // When selectedVaultId changes, update directoryTree from vaultTrees and clear old tabs
  useEffect(() => {
    const vaultId = state.selectedVaultId
    // Guards the async dispatches below: if the vault is switched again before
    // a fetch resolves, its stale result must not overwrite state for the
    // vault the user is now on (see VAULT_TREE_LOADED vs. the older
    // vault-agnostic TREE_LOADED action in state/index.ts).
    let cancelled = false
    if (vaultId !== prevVaultId.current) {
      if (prevVaultId.current !== null) {
        // Save current tabs for the previous vault before clearing
        const prevId = prevVaultId.current
        vaultTabsCacheRef.current.set(prevId, {
          tabs: tabState.tabs
            .filter((t) => t.vaultId === prevId)
            .map((t) => ({ filePath: t.filePath, fileName: t.fileName })),
          activeTabId: tabState.activeTabId,
        })

        // Vault changed or was deleted ÔÇö clear all tabs
        const graphTab = tabState.tabs.find((t) => t.filePath === '__graph__')
        tabDispatch({ type: 'CLEAR_ALL_TABS' })

        // Restore cached tabs for the new vault (if any)
        if (vaultId) {
          const cached = vaultTabsCacheRef.current.get(vaultId)
          if (cached && cached.tabs.length > 0) {
            for (const tab of cached.tabs) {
              tabDispatch({
                type: 'OPEN_TAB',
                payload: { vaultId, filePath: tab.filePath, fileName: tab.fileName },
              })
              // Fetch content for regular file tabs
              const tabId = `${vaultId}::${tab.filePath}`
              if (!tab.filePath.startsWith('__')) {
                apiClient.fetchFileContent(vaultId, tab.filePath).then(
                  (result) => {
                    if (cancelled) return
                    tabDispatch({
                      type: 'TAB_CONTENT_LOADED',
                      payload: { tabId, content: result.content, isBinary: result.isBinary },
                    })
                  },
                  () => {
                    if (cancelled) return
                    tabDispatch({ type: 'CLOSE_TAB', payload: { tabId } })
                  },
                )
              } else {
                tabDispatch({
                  type: 'TAB_CONTENT_LOADED',
                  payload: { tabId, content: '', isBinary: false },
                })
              }
            }
            // Restore active tab
            if (cached.activeTabId) {
              tabDispatch({ type: 'ACTIVATE_TAB', payload: { tabId: cached.activeTabId } })
            }
          } else if (graphTab) {
            // No cached tabs but graph was open ÔÇö re-open graph for new vault
            const vault = state.vaults.find((v) => v.id === vaultId)
            const graphTabName = vault ? `Graph ÔÇö ${vault.name}` : 'Graph'
            tabDispatch({
              type: 'OPEN_TAB',
              payload: { vaultId, filePath: '__graph__', fileName: graphTabName },
            })
            const graphTabId = `${vaultId}::__graph__`
            tabDispatch({
              type: 'TAB_CONTENT_LOADED',
              payload: { tabId: graphTabId, content: '', isBinary: false },
            })
          }
        }
      }
      if (vaultId) {
        // If the tree is already loaded in vaultTrees, use it
        const existingTree = state.vaultTrees[vaultId]
        if (existingTree) {
          dispatch({ type: 'TREE_LOADED', payload: existingTree })
        } else if (apiClient) {
          // Fetch the tree
          dispatch({ type: 'LOADING_STARTED' })
          apiClient.fetchVaultTree(vaultId).then(
            (tree) => {
              if (cancelled) return
              dispatch({ type: 'TREE_LOADED', payload: tree })
              dispatch({ type: 'VAULT_TREE_LOADED', payload: { vaultId, tree } })
            },
            (err) => {
              if (cancelled) return
              const error =
                err && typeof err === 'object' && 'code' in err && 'message' in err
                  ? { code: err.code as string, message: err.message as string }
                  : { code: 'INTERNAL_ERROR', message: t('vault.treeLoadError') }
              dispatch({ type: 'ERROR_OCCURRED', payload: error })
            },
          )
        }
      }
    }
    prevVaultId.current = vaultId
    return () => {
      cancelled = true
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [state.selectedVaultId, dispatch, tabDispatch])

  const handleLogout = useCallback(async () => {
    try { await apiClient.logout() } catch { /* ignore */ }
    apiClient.setToken(null)
    apiClient.setCsrfToken(null)
    authDispatch({ type: 'LOGOUT' })
    localStorage.removeItem(LAST_VAULT_KEY)
    clearWorkspace()
  }, [authDispatch])

  function handleImportFile() { fileInputRef.current?.click() }
  function handleImportFolder() { folderInputRef.current?.click() }

  function handleCreateVault() {
    if (createVaultTriggerRef.current) {
      createVaultTriggerRef.current()
    }
  }

  function handleCreateFile() {
    if (!state.selectedVaultId) return
    // Trigger inline file creation in the FileExplorer
    if (createFileTriggerRef.current) {
      createFileTriggerRef.current()
    }
  }

  function handleCreateFolder() {
    if (!state.selectedVaultId) return
    if (createFolderTriggerRef.current) {
      createFolderTriggerRef.current()
    }
  }

  function handleCreateCanvas() {
    if (!state.selectedVaultId) return
    if (createCanvasTriggerRef.current) {
      createCanvasTriggerRef.current()
    }
  }

  function handleExportVault() {
    if (state.selectedVaultId) {
      const vault = state.vaults.find((v) => v.id === state.selectedVaultId)
      void exportVault(dispatch, apiClient, state.selectedVaultId, vault?.name)
    }
  }

  function handleOpenGraph() {
    if (!state.selectedVaultId) return
    // Check if a graph tab already exists for the current vault
    const existingGraphTab = tabState.tabs.find((t) => t.filePath === '__graph__' && t.vaultId === state.selectedVaultId)
    if (existingGraphTab) {
      // Activate existing graph tab
      setActiveSettingsPage(null)
      tabDispatch({ type: 'ACTIVATE_TAB', payload: { tabId: existingGraphTab.id } })
    } else {
      // Open new graph tab
      setActiveSettingsPage(null)
      const vault = state.vaults.find((v) => v.id === state.selectedVaultId)
      const graphTabName = vault ? `Graph ÔÇö ${vault.name}` : 'Graph'
      tabDispatch({
        type: 'OPEN_TAB',
        payload: { vaultId: state.selectedVaultId, filePath: '__graph__', fileName: graphTabName },
      })
      // Mark as loaded immediately (no content to fetch)
      const graphTabId = `${state.selectedVaultId}::__graph__`
      tabDispatch({
        type: 'TAB_CONTENT_LOADED',
        payload: { tabId: graphTabId, content: '', isBinary: false },
      })
    }
  }

  /** Opens or creates today's daily note for the active vault. */
  const handleDailyNote = useCallback(async () => {
    if (!state.selectedVaultId) {
      showToast('error', 'Bitte zuerst einen Vault ausw├ñhlen')
      return
    }

    const vaultId = state.selectedVaultId
    // Load config from server (updates localStorage cache), falls back to cache
    const dailyDir = await loadDailyNotesConfigFromServer(apiClient, vaultId)

    try {
      const filePath = await dailyNoteService.openOrCreate(vaultId, dailyDir)
      const fileName = filePath.split('/').pop() ?? filePath
      setActiveSettingsPage(null)
      await openTab(tabDispatch, dispatch, apiClient, vaultId, filePath, fileName)
      // Refresh file explorer tree (SSE vault:change excludes the triggering user)
      void reloadVaultTree(dispatch, apiClient, vaultId)
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : 'Tagesnotiz konnte nicht erstellt werden'
      showToast('error', message)
    }
  }, [state.selectedVaultId, tabDispatch, dispatch])

  useGlobalShortcuts({
    contextPanelSections: contextPanelState.sections,
    contextPanelDispatch,
    setShowRightPanel,
    tabs: tabState.tabs,
    activeTabId: tabState.activeTabId,
    tabDispatch,
    setSettingsOpen,
    onDailyNote: handleDailyNote,
  })

  /** Open a file from the sidebar panel (favorites or recent files). */
  const handleSidebarOpenFile = useCallback((vaultId: string, path: string) => {
    const fileName = path.split('/').pop() ?? path
    setActiveSettingsPage(null)
    // Switch vault if needed
    if (vaultId !== state.selectedVaultId) {
      dispatch({ type: 'VAULT_SELECTED', payload: vaultId })
    }
    void openTab(tabDispatch, dispatch, apiClient, vaultId, path, fileName)
    setSidebarRefreshKey((v) => v + 1)
  }, [state.selectedVaultId, tabDispatch, dispatch])

  function handleFileSelected(event: React.ChangeEvent<HTMLInputElement>) {
    const file = event.target.files?.[0]
    if (file && state.selectedVaultId) importFile(dispatch, apiClient, state.selectedVaultId, file)
    event.target.value = ''
  }

  function handleFolderSelected(event: React.ChangeEvent<HTMLInputElement>) {
    const files = event.target.files
    if (files && files.length > 0 && state.selectedVaultId) importFolder(dispatch, apiClient, state.selectedVaultId, files)
    event.target.value = ''
  }

  /** Open a settings page as a tab (or activate if already open). */
  function handleNavigate(page: AppPage) {
    setOpenSettingsPages((prev) => prev.includes(page) ? prev : [...prev, page])
    setActiveSettingsPage(page)
  }

  /** Close a settings tab. */
  function handleCloseSettingsTab(page: AppPage) {
    setOpenSettingsPages((prev) => {
      const next = prev.filter((p) => p !== page)
      if (activeSettingsPage === page) {
        setActiveSettingsPage(next.length > 0 ? (next[next.length - 1] ?? null) : null)
      }
      return next
    })
  }

  function renderSettingsPage(page: AppPage) {
    switch (page) {
      case 'my-vaults': return <MyVaultsPage apiClient={apiClient} />
      case 'profile': return <ProfilePage apiClient={apiClient} />
      case 'sessions': return <SessionsPage apiClient={apiClient} />
      case 'chat':
        if (!isEnabled('chat')) return <FeatureDisabledHint featureName="Chat" />
        return <ChatPage />
      case 'admin-users': return <AdminUsersPage apiClient={apiClient} />
      case 'admin-vaults': return <AdminVaultsPage apiClient={apiClient} />
      case 'admin-config': return <AdminConfigPage apiClient={apiClient} />
      case 'admin-audit': return <AdminAuditPage apiClient={apiClient} />
      case 'admin-logs': return <AdminLogsPage apiClient={apiClient} />
      case 'vault-sharing':
        return state.selectedVaultId
          ? <VaultSharing apiClient={apiClient} vaultId={state.selectedVaultId} />
          : <div style={{ padding: 24, color: 'var(--text-muted)' }}>{t('common.noSelection')}</div>
      case 'vault-deletion':
        return state.selectedVaultId
          ? <VaultDeletionWorkflow
              apiClient={apiClient}
              vaultId={state.selectedVaultId}
              onComplete={() => {
                loadVaults(dispatch, apiClient)
                handleCloseSettingsTab('vault-deletion')
              }}
            />
          : <div style={{ padding: 24, color: 'var(--text-muted)' }}>{t('common.noSelection')}</div>
      case 'mcp-tokens':
        if (!isEnabled('mcp')) return <FeatureDisabledHint featureName="MCP" />
        return <McpTokensPage apiClient={apiClient} />
      case 'plugins':
        if (!isEnabled('obsidian-plugin-compat')) return <FeatureDisabledHint featureName="Plugin-Kompatibilit├ñt" />
        return state.selectedVaultId
          ? <PluginManagementPage apiClient={apiClient} vaultId={state.selectedVaultId} />
          : <div style={{ padding: 24, color: 'var(--text-muted)' }}>{t('common.noSelection')}</div>
      case 'trash':
        return state.selectedVaultId
          ? <TrashView vaultId={state.selectedVaultId} apiClient={apiClient} />
          : <div style={{ padding: 24, color: 'var(--text-muted)' }}>{t('common.noSelection')}</div>
      default: return null
    }
  }

  const isShowingSettings = activeSettingsPage !== null
  const user = authState.user
  const selectedVault = state.vaults.find((v) => v.id === state.selectedVaultId) ?? null
  const activeTab = tabState.tabs.find((tab) => tab.id === tabState.activeTabId) ?? null
  const selectedVaultName = selectedVault?.name ?? ''

  const settingsTabs: SettingsTabDescriptor[] = openSettingsPages.map((page) => {
    const isActive = isShowingSettings && page === activeSettingsPage
    const pageLabel = t(PAGE_LABEL_KEYS[page] as Parameters<typeof t>[0])
    return {
      key: page,
      label: pageLabel,
      icon: PAGE_ICONS[page],
      isActive,
      onActivate: () => setActiveSettingsPage(page),
      onClose: () => handleCloseSettingsTab(page),
      closeAriaLabel: t('tabs.closePageAriaLabel', { name: pageLabel }),
      closeTitle: t('common.close'),
    }
  })

  return (
    <PluginProvider
      vaultId={state.selectedVaultId}
      vaultName={selectedVaultName}
      apiClient={apiClient}
      directoryTree={state.directoryTree}
      tabState={tabState}
    >
    {/* app-container: Obsidian-parity marker class ÔÇö real Obsidian's outermost
        app div carries this class, and some plugins (e.g. Calendar's Svelte
        popovers via a `portal` action) document.querySelector for it to
        teleport floating UI to a guaranteed-visible root. No visual/behavioral
        effect in Slatebase itself ÔÇö see mod-vertical/mod-root and
        workspace-tab-container above for the same pattern. */}
    <div className="app app-container">
      <CommandPaletteContainer
        onNavigate={handleNavigate}
        onCreateVault={handleCreateVault}
        onCreateFile={handleCreateFile}
        onCreateFolder={handleCreateFolder}
        onCreateCanvas={handleCreateCanvas}
        onImportFile={handleImportFile}
        onImportFolder={handleImportFolder}
        onExportVault={handleExportVault}
        onOpenGraph={handleOpenGraph}
        onDailyNote={handleDailyNote}
        showSidebar={showSidebar}
        showRightPanel={showRightPanel}
        onToggleSidebar={() => setShowSidebar((v) => !v)}
        onToggleRightPanel={() => setShowRightPanel((v) => !v)}
        onOpenSettings={(nav) => {
          setSettingsInitialNav(nav)
          setSettingsOpen(true)
        }}
        onLogout={handleLogout}
        onToggleTheme={async () => {
          const current = authState.user?.colorScheme ?? 'system'
          const next = current === 'dark' ? 'light' : 'dark'
          try {
            const updatedUser = await apiClient.updateProfile({ colorScheme: next })
            authDispatch({ type: 'PROFILE_UPDATED', payload: { user: updatedUser } })
          } catch { /* ignore ÔÇö theme stays as-is until the next successful save */ }
        }}
      />
      {/* Unified Settings Panel (renders as fixed overlay when open) */}
      <SettingsPanel open={settingsOpen} onClose={() => setSettingsOpen(false)} initialNav={settingsInitialNav} />
      {/* Version Browser Modal */}
      {versionBrowserTarget && (
        <div className="version-browser-modal-overlay" onClick={() => setVersionBrowserTarget(null)}>
          <div className="version-browser-modal" onClick={(e) => e.stopPropagation()}>
            <div className="version-browser-modal__header">
              <span className="version-browser-modal__title">Versionen ÔÇö {versionBrowserTarget.filePath}</span>
              <button
                type="button"
                className="version-browser-modal__close"
                onClick={() => setVersionBrowserTarget(null)}
                aria-label="Schlie├ƒen"
              >
                <X size={16} />
              </button>
            </div>
            <VersionBrowser
              vaultId={versionBrowserTarget.vaultId}
              filePath={versionBrowserTarget.filePath}
              currentContent={
                activeTab && activeTab.vaultId === versionBrowserTarget.vaultId && activeTab.filePath === versionBrowserTarget.filePath
                  ? (activeTab.editBuffer ?? activeTab.content)
                  : ''
              }
              apiClient={apiClient}
              onRestore={() => {
                // Reload the tab content after restore if it matches the active tab
                if (activeTab && activeTab.vaultId === versionBrowserTarget.vaultId && activeTab.filePath === versionBrowserTarget.filePath) {
                  apiClient.fetchFileContent(versionBrowserTarget.vaultId, versionBrowserTarget.filePath).then((result) => {
                    tabDispatch({
                      type: 'TAB_CONTENT_LOADED',
                      payload: { tabId: activeTab.id, content: result.content, isBinary: result.isBinary },
                    })
                  }).catch(() => { /* ignore */ })
                }
                setVersionBrowserTarget(null)
              }}
            />
          </div>
        </div>
      )}
      <input ref={fileInputRef} type="file" style={{ display: 'none' }} onChange={handleFileSelected} aria-hidden="true" tabIndex={-1} />
      <input ref={folderInputRef} type="file"
        // @ts-expect-error webkitdirectory is non-standard
        webkitdirectory=""
        style={{ display: 'none' }} onChange={handleFolderSelected} aria-hidden="true" tabIndex={-1} />

      {state.loading && (
        <div className="app-loading" role="status" aria-live="polite">
          <span className="app-loading-spinner" aria-hidden="true" />
          <span>{t('common.loading')}</span>
        </div>
      )}
      {state.error && (
        <div className="app-error" role="alert">
          {t('common.errorWithCode', { code: state.error.code, message: state.error.message })}
        </div>
      )}

      <main className="app-main app-main--vault-view">
        {/* workspace-split/mod-vertical/mod-root: Obsidian-parity marker classes some
            community plugins (e.g. Editing Toolbar's fullscreen-focus) query for via
            document.querySelector to find the workspace root ÔÇö no visual/behavioral
            effect in Slatebase itself. Deliberately duplicates the same classes the
            WorkspaceShim stamps on its hidden off-screen container (see workspace-shim.ts
            containerEl): plugins that portal *visible* UI via `.workspace-split` need a
            real, on-screen node, not the shim's 0x0 stub. React mounts #root before the
            plugin system runs, so this element is earlier in document order and wins any
            document.querySelector('.workspace-split') lookup over the shim's hidden one. */}
        <div className="app-vault-layout mod-vertical mod-root workspace-split">

          {/* ÔöÇÔöÇ Sidebar ÔöÇÔöÇ */}
          {showSidebar && (
            <aside className="app-sidebar" style={{ width: sidebar.width }}>
              <div className="app-sidebar-header">
                <div className="app-logo">
                  <SlatebaseLogo size={26} className="app-logo-icon" />
                  <span className="app-title">Slatebase</span>
                  {!versionInfo.loading && versionInfo.installed && versionInfo.installed !== 'development' && (
                    <span className="app-version">v{versionInfo.installed}</span>
                  )}
                  {versionInfo.latest && (
                    <a
                      href={versionInfo.latestUrl ?? '#'}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="app-version-update"
                      title={`Update auf v${versionInfo.latest} verf├╝gbar`}
                    >
                      (neu: v{versionInfo.latest})
                    </a>
                  )}
                </div>
                <div className="app-sidebar-header-actions">
                  <RealtimeConnectionIndicator />
                  <UserMenu
                    onNavigate={handleNavigate}
                    onLogout={handleLogout}
                    hasVaultSelected={state.selectedVaultId !== null}
                    onImportFile={handleImportFile}
                    onImportFolder={handleImportFolder}
                    onExportVault={handleExportVault}
                  />
                </div>
              </div>

              <div className="app-sidebar-body">
                <SidebarPanel
                  width={sidebar.width}
                  vaultId={state.selectedVaultId}
                  onOpenFile={handleSidebarOpenFile}
                  renderExplorer={() => (
                    <FileExplorer
                      onRegisterCreateFile={handleRegisterCreateFile}
                      onRegisterCreateFolder={handleRegisterCreateFolder}
                      onRegisterCreateVault={handleRegisterCreateVault}
                      onRegisterCreateCanvas={handleRegisterCreateCanvas}
                      onOpenVersions={(vaultId, filePath) => setVersionBrowserTarget({ vaultId, filePath })}
                    />
                  )}
                  refreshKey={sidebarRefreshKey}
                />
              </div>
            </aside>
          )}

          {/* ÔöÇÔöÇ Sidebar Resize Handle ÔöÇÔöÇ */}
          {showSidebar && (
            <div
              className="resize-handle"
              onMouseDown={sidebar.onMouseDown}
              title={t('resize.adjustWidth')}
              role="separator"
              aria-orientation="vertical"
            />
          )}

          {/* ÔöÇÔöÇ Toolbar ÔöÇÔöÇ */}
          <SidebarToolbar
            vaultId={state.selectedVaultId}
            vaultPermission={selectedVault?.permission}
            onCreateVault={handleCreateVault}
            onCreateFile={handleCreateFile}
            onCreateCanvas={handleCreateCanvas}
            onImportFile={handleImportFile}
            onImportFolder={handleImportFolder}
            onExportVault={handleExportVault}
            onNavigate={handleNavigate}
            onOpenGraph={handleOpenGraph}
            onOpenTrash={() => handleNavigate('trash')}
            onDailyNote={handleDailyNote}
            onOpenSettings={() => setSettingsOpen(true)}
            isAdmin={user?.role === 'admin'}
            isVaultOwner={selectedVault?.permission === 'owner'}
            globalUnreadCount={globalUnreadCount}
          />

          {/* ÔöÇÔöÇ Main Content ÔöÇÔöÇ */}
          {/* workspace-tab-container: Obsidian-parity marker class ÔÇö see mod-vertical/mod-root
              note above. Some plugins requestFullscreen() this element by selector. */}
          <section className="app-content workspace-tab-container">
            {/* Unified tab bar: settings tabs + file tabs in one row */}
            <TabBar
              settingsTabs={settingsTabs}
              isShowingSettings={isShowingSettings}
              onActivateFileTab={() => setActiveSettingsPage(null)}
            />

            {/* Content: settings page or vault editor */}
            {isShowingSettings ? (
              <div className="tab-content" style={{ overflow: 'auto' }}>
                {renderSettingsPage(activeSettingsPage!)}
              </div>
            ) : (
              <ErrorBoundary>
                <TabContent />
              </ErrorBoundary>
            )}
          </section>

          {/* ÔöÇÔöÇ Right Panel + Resize ÔöÇÔöÇ */}
          {showRightPanel && (
            <>
              <div
                className="resize-handle"
                onMouseDown={rightPanel.onMouseDown}
                title={t('resize.adjustWidth')}
                role="separator"
                aria-orientation="vertical"
              />
              <aside className="app-right-panel" style={{ width: rightPanel.width }}>
                <PluginViewPanel />
                <ContextPanel
                  documentContent={activeTab && !activeTab.isBinary && activeTab.filePath !== '__graph__' ? (activeTab.editBuffer ?? activeTab.content) : null}
                  documentPath={activeTab && !activeTab.isBinary && activeTab.filePath !== '__graph__' ? activeTab.filePath : null}
                  vaultId={state.selectedVaultId}
                  width={rightPanel.width}
                />
              </aside>
            </>
          )}

          {/* Toggle right panel */}
          <button
            className={`right-panel-toggle${showRightPanel ? ' right-panel-toggle--active' : ''}`}
            onClick={() => setShowRightPanel((v) => !v)}
            title={showRightPanel ? t('rightPanel.hide') : t('rightPanel.show')}
            type="button"
            aria-pressed={showRightPanel}
          >
            <PanelRight size={15} />
          </button>

          {/* Toggle left panel (sidebar) */}
          <button
            className={`left-panel-toggle${showSidebar ? ' left-panel-toggle--active' : ''}`}
            onClick={() => setShowSidebar((v) => !v)}
            title={showSidebar ? t('rightPanel.hide') : t('rightPanel.show')}
            type="button"
            aria-pressed={showSidebar}
          >
            <PanelLeft size={15} />
          </button>
        </div>
        {statusBarVisible && <StatusBar />}
      </main>
    </div>
    </PluginProvider>
  )
}

/**
 * Connects I18nProvider to the auth state so locale follows the user's profile.
 * Also applies the user's color scheme preference to the document root.
 * Before login: browser language detection. After login: user.preferredLanguage.
 */
function I18nBridge({ children }: { children: React.ReactNode }) {
  const { authState } = useAuthContext()
  const userLocale = authState.user?.preferredLanguage ?? null
  const colorScheme = authState.user?.colorScheme ?? 'system'

  // Apply color scheme to <html> element
  useEffect(() => {
    document.documentElement.setAttribute('data-theme', colorScheme)
  }, [colorScheme])

  return (
    <I18nProvider userLocale={userLocale}>
      <ObsidianLocaleSync />
      {children}
    </I18nProvider>
  )
}

/**
 * Syncs the active i18n locale to localStorage("language") and moment.locale().
 * Obsidian plugins (e.g. Calendar) read localStorage("language") to determine
 * which moment locale to activate. This ensures the plugin locale always matches
 * the user's chosen language, not the browser default.
 */
function ObsidianLocaleSync() {
  const { locale } = useTranslation()

  useEffect(() => {
    // Sync to localStorage ÔÇö plugins read this via localStorage.getItem("language")
    localStorage.setItem('language', locale)

    // Also update the global moment locale so new moment() calls use it
    if (window.moment) {
      window.moment.locale(locale)
    }
  }, [locale])

  return null
}

/** How many times the session probe retries while the server is unreachable. */
const SESSION_PROBE_ATTEMPTS = 3

/** Base delay between session probe retries (grows linearly per attempt). */
const SESSION_PROBE_RETRY_MS = 700

/**
 * Auth guard component.
 * When a token is restored from localStorage, verifies the session is still valid
 * before rendering authenticated content ÔÇö prevents stale-token API noise (401s).
 * An unreachable server is never treated as an invalid session.
 */
function AuthGuard() {
  const { authState, authDispatch } = useAuthContext()
  const [sessionVerified, setSessionVerified] = useState(false)

  // Restore apiClient tokens from persisted auth state (after page reload)
  useEffect(() => {
    if (authState.token) {
      apiClient.setToken(authState.token)
    }
    if (authState.csrfToken) {
      apiClient.setCsrfToken(authState.csrfToken)
    }
  }, [authState.token, authState.csrfToken])

  useEffect(() => {
    apiClient.setOnSessionExpired(() => {
      // Workspace state is already persisted continuously ÔÇö no need to save explicitly
      apiClient.setToken(null)
      apiClient.setCsrfToken(null)
      // Disconnect server-synced stores
      disconnectRecentFiles()
      disconnectFavorites()
      disconnectKeybindings()
      authDispatch({ type: 'SESSION_EXPIRED' })
    })
    return () => { apiClient.setOnSessionExpired(null) }
  }, [authDispatch])

  // Verify session validity when auth state is restored from localStorage.
  // Skip when mustChangePassword is true ÔÇö the session is valid but the
  // mustChangePassword middleware blocks all other endpoints with 403.
  // The ChangePasswordPage is rendered before the sessionVerified check,
  // so skipping verification here does not cause a stuck spinner.
  useEffect(() => {
    if (!authState.isAuthenticated || authState.mustChangePassword) {
      return
    }

    let cancelled = false

    async function verify() {
      // A probe that cannot reach the server says nothing about the session, so
      // retry a few times before deciding. This matters most right after a
      // plugin toggle, which reloads the page (see plugins/compat/plugin-context.ts)
      // and re-runs this check against a backend that may still be busy or restarting.
      for (let attempt = 0; attempt < SESSION_PROBE_ATTEMPTS; attempt++) {
        const probe = await apiClient.probeSession()
        if (cancelled) return

        if (probe === 'alive') {
          setSessionVerified(true)
          return
        }

        if (probe === 'dead') {
          // Server confirmed the session is gone ÔÇö clear auth state (triggers login page).
          // Workspace state is already persisted continuously ÔÇö no explicit save needed
          apiClient.setToken(null)
          apiClient.setCsrfToken(null)
          disconnectRecentFiles()
          disconnectFavorites()
          disconnectKeybindings()
          authDispatch({ type: 'SESSION_EXPIRED' })
          return
        }

        const isLastAttempt = attempt === SESSION_PROBE_ATTEMPTS - 1
        if (!isLastAttempt) {
          await new Promise(resolve => setTimeout(resolve, SESSION_PROBE_RETRY_MS * (attempt + 1)))
          if (cancelled) return
        }
      }

      // Still unreachable. Keep the session and let the app render: individual
      // requests surface their own errors, and a confirmed 401 will tear the
      // session down through the ApiClient. Throwing the login away here would
      // punish the user for the server being briefly unavailable.
      console.warn('[AuthGuard] Could not reach the server to verify the session ÔÇö continuing with the stored session')
      setSessionVerified(true)
    }

    void verify()
    return () => { cancelled = true }
  }, [authState.isAuthenticated, authState.mustChangePassword, authDispatch])

  if (!authState.isAuthenticated) {
    return <LoginPage apiClient={apiClient} />
  }

  if (authState.mustChangePassword) {
    return <ChangePasswordPage apiClient={apiClient} />
  }

  // Wait for session verification before rendering the app tree
  if (!sessionVerified) {
    return (
      <div className="app-loading" role="status" aria-live="polite">
        <span className="app-loading-spinner" aria-hidden="true" />
      </div>
    )
  }

  return (
    <FeatureProvider>
      <FeatureLoader />
      <RealtimeBridge>
        <AppProvider apiClient={apiClient}>
          <SearchProvider>
            <TabProvider>
              <ContextPanelProvider>
                <SidebarPanelProvider>
                  <AppContent />
                  {/* Inside AppProvider: the popover reads the vault and API
                      client from AppContext to load the previewed note. */}
                  <HoverPreview />
                </SidebarPanelProvider>
              </ContextPanelProvider>
            </TabProvider>
          </SearchProvider>
        </AppProvider>
      </RealtimeBridge>
    </FeatureProvider>
  )
}

/**
 * Bridge component that connects the RealtimeProvider with auth state.
 * Sits inside AuthProvider, wrapping the app content.
 * Reads the session token from auth state.
 * Wires SSE event handlers to the module-level chat bridge for cross-provider communication.
 */
function RealtimeBridge({ children }: { children: React.ReactNode }) {
  const { authState } = useAuthContext()

  const token = authState.token ?? null

  const handlers = useMemo<RealtimeEventHandlers>(() => ({
    onChatMessage: (data: Record<string, unknown>) => {
      const message = {
        id: data.messageId as string,
        conversationId: data.conversationId as string,
        senderId: data.senderId as string,
        content: data.content as string,
        timestamp: data.timestamp as string,
      }
      dispatchRealtimeChatMessage(message)
      // Also update conversation preview for the conversation list
      dispatchRealtimeConversationPreview(
        message.conversationId,
        message.content,
        message.timestamp,
      )
    },
    onChatUnread: (totalUnread: number) => {
      dispatchRealtimeUnreadUpdate(totalUnread)
    },
    onVaultChange: (vaultId: string, data?: Record<string, unknown>) => {
      const event: VaultChangeEvent = {
        vaultId,
        action: (data?.action as 'saved' | 'deleted' | 'renamed') ?? 'saved',
        path: (data?.path as string) ?? '',
        userId: (data?.userId as string) ?? '',
        username: (data?.username as string) ?? '',
      }
      dispatchRealtimeVaultChange(event)
    },
    onPluginSettingsChange: (vaultId: string, pluginId: string) => {
      dispatchPluginSettingsChange({ vaultId, pluginId })
    },
  }), [])

  return (
    <RealtimeProvider
      token={token}
      handlers={handlers}
      getTicket={() => apiClient.getSseTicket()}
    >
      {children}
    </RealtimeProvider>
  )
}

/**
 * Loads feature toggles from the public API on mount.
 * Placed inside FeatureProvider to access dispatch, and renders nothing.
 */
function FeatureLoader() {
  const { dispatch } = useFeatureContext()

  useEffect(() => {
    dispatch({ type: 'FEATURES_LOADING' })
    apiClient.loadFeatures()
      .then(features => {
        dispatch({
          type: 'FEATURES_LOADED',
          features: features.map(f => ({
            name: f.name,
            enabled: f.enabled,
            type: 'hot' as const,
            description: '',
          })),
        })
      })
      .catch((error: unknown) => {
        const message = error instanceof Error ? error.message :
          (typeof error === 'object' && error !== null && 'message' in error) ?
            String((error as { message: unknown }).message) : 'Fehler beim Laden der Features'
        dispatch({ type: 'FEATURES_ERROR', error: message })
      })
  }, [dispatch])

  return null
}

/**
 * Root App component.
 * Provider hierarchy: AuthProvider ÔåÆ I18nBridge (reads user locale) ÔåÆ AuthGuard ÔåÆ App content.
 * ToastNotification rendered at root level (uses module-level state, independent of providers).
 */
export function App() {
  return (
    <AuthProvider>
      <I18nBridge>
        <AuthGuard />
      </I18nBridge>
      <ToastNotification />
      <GlobalTooltip />
    </AuthProvider>
  )
}

import { useState, useEffect, useRef, useCallback } from 'react'
import { Search } from 'lucide-react'
import type { Command } from '../plugins/compat/command-registry'

export interface CommandPaletteProps {
  /** All available commands from the command registry */
  commands: Command[];
  /** Whether the palette is open */
  isOpen: boolean;
  /** Called when the palette should close */
  onClose: () => void;
  /** Called when a command should be executed */
  onExecute: (commandId: string) => void;
}

/** Maximum number of results displayed */
const MAX_RESULTS = 50;

/**
 * CommandPalette ÔÇö Modal overlay for searching and executing plugin commands.
 *
 * Opens when `isOpen` is true. Provides a search input with case-insensitive
 * filtering (max 50 results), keyboard navigation (Arrow Up/Down, Enter, Escape),
 * and click-to-execute.
 *
 * The keyboard shortcut (Ctrl+P / Cmd+P) is registered at the App level,
 * not inside this component.
 */
export function CommandPalette({ commands, isOpen, onClose, onExecute }: CommandPaletteProps) {
  const [query, setQuery] = useState('')
  const [selectedIndex, setSelectedIndex] = useState(0)
  const inputRef = useRef<HTMLInputElement>(null)
  const listRef = useRef<HTMLUListElement>(null)

  // Filter commands by case-insensitive substring match on name
  const filteredCommands = filterCommands(commands, query)

  const totalItems = filteredCommands.length

  // Reset state when palette opens
  useEffect(() => {
    if (isOpen) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setQuery('')
      setSelectedIndex(0)
      // Autofocus the input after render
      requestAnimationFrame(() => {
        inputRef.current?.focus()
      })
    }
  }, [isOpen])

  // Clamp selectedIndex when filtered results change
  useEffect(() => {
    if (selectedIndex >= totalItems) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setSelectedIndex(Math.max(0, totalItems - 1))
    }
  }, [totalItems, selectedIndex])

  // Scroll selected item into view
  useEffect(() => {
    if (!listRef.current) return
    const selectedEl = listRef.current.querySelector('[aria-selected="true"]')
    if (selectedEl && typeof selectedEl.scrollIntoView === 'function') {
      selectedEl.scrollIntoView({ block: 'nearest' })
    }
  }, [selectedIndex])

  const handleExecute = useCallback((commandId: string) => {
    try {
      onExecute(commandId)
    } catch (err) {
      console.error('[CommandPalette] Exception executing command:', err)
    }
    onClose()
  }, [onExecute, onClose])

  const handleKeyDown = useCallback((e: React.KeyboardEvent) => {
    switch (e.key) {
      case 'ArrowDown':
        e.preventDefault()
        setSelectedIndex(prev =>
          prev < totalItems - 1 ? prev + 1 : prev
        )
        break
      case 'ArrowUp':
        e.preventDefault()
        setSelectedIndex(prev => (prev > 0 ? prev - 1 : prev))
        break
      case 'Enter':
        e.preventDefault()
        if (totalItems > 0) {
          const selected = filteredCommands[selectedIndex]
          if (selected) {
            handleExecute(selected.id)
          }
        }
        break
      case 'Escape':
        e.preventDefault()
        onClose()
        break
    }
  }, [filteredCommands, selectedIndex, handleExecute, onClose, totalItems])

  const handleOverlayClick = useCallback((e: React.MouseEvent) => {
    if (e.target === e.currentTarget) {
      onClose()
    }
  }, [onClose])

  if (!isOpen) return null

  const activeDescendant = totalItems > 0
    ? `command-palette-item-${selectedIndex}`
    : undefined

  return (
    <div
      className="command-palette-overlay"
      onClick={handleOverlayClick}
      role="presentation"
    >
      <div
        className="command-palette"
        role="dialog"
        aria-modal="true"
        aria-label="Command Palette"
      >
        <div className="command-palette-search">
          <Search size={14} className="command-palette-search-icon" />
          <input
            ref={inputRef}
            type="text"
            className="command-palette-input"
            placeholder="Befehl suchenÔÇª"
            value={query}
            onChange={(e) => {
              setQuery(e.target.value)
              setSelectedIndex(0)
            }}
            onKeyDown={handleKeyDown}
            role="combobox"
            aria-expanded="true"
            aria-controls="command-palette-list"
            aria-activedescendant={activeDescendant}
            aria-autocomplete="list"
          />
        </div>

        <ul
          ref={listRef}
          id="command-palette-list"
          className="command-palette-list"
          role="listbox"
          aria-label="Befehle"
        >
          {filteredCommands.length === 0 ? (
            <li className="command-palette-empty" role="option" aria-selected={false}>
              Keine Befehle gefunden
            </li>
          ) : (
            filteredCommands.map((cmd, index) => (
              <li
                key={cmd.id}
                id={`command-palette-item-${index}`}
                className={`command-palette-item${index === selectedIndex ? ' command-palette-item--selected' : ''}`}
                role="option"
                aria-selected={index === selectedIndex}
                onClick={() => handleExecute(cmd.id)}
              >
                <span className="command-palette-item-name">{cmd.name}</span>
                <span className="command-palette-item-plugin">{cmd.pluginId}</span>
              </li>
            ))
          )}
        </ul>
      </div>
    </div>
  )
}

/**
 * Filter commands by case-insensitive substring match on the command name.
 * Returns at most MAX_RESULTS items.
 */
function filterCommands(commands: Command[], query: string): Command[] {
  if (!query) {
    return commands.slice(0, MAX_RESULTS)
  }

  const lowerQuery = query.toLowerCase()
  const results: Command[] = []

  for (const cmd of commands) {
    if (cmd.name.toLowerCase().includes(lowerQuery)) {
      results.push(cmd)
      if (results.length >= MAX_RESULTS) break
    }
  }

  return results
}

import { useEffect, useRef } from 'react'
import { AlertTriangle } from 'lucide-react'
import { useTranslation } from '../i18n'

export interface ConfirmModalProps {
  /** Whether the modal is visible. */
  open: boolean
  /** Title displayed at the top of the modal. */
  title: string
  /** Main message body (supports newlines via whitespace CSS). */
  message: string
  /** Label for the confirm button. Defaults to common.confirm. */
  confirmLabel?: string
  /** Label for the cancel button. Defaults to common.cancel. */
  cancelLabel?: string
  /** Visual variant for the confirm button. */
  variant?: 'danger' | 'primary'
  /** Called when the user confirms. */
  onConfirm: () => void
  /** Called when the user cancels (or presses Escape). */
  onCancel: () => void
}

/**
 * Reusable confirmation modal that replaces window.confirm.
 * Renders as a fixed overlay with focus trap and Escape key support.
 */
export function ConfirmModal({
  open,
  title,
  message,
  confirmLabel,
  cancelLabel,
  variant = 'danger',
  onConfirm,
  onCancel,
}: ConfirmModalProps) {
  const { t } = useTranslation()
  const confirmRef = useRef<HTMLButtonElement>(null)
  const cancelRef = useRef<HTMLButtonElement>(null)

  // Focus the cancel button when modal opens (safer default)
  useEffect(() => {
    if (open) {
      cancelRef.current?.focus()
    }
  }, [open])

  // Handle Escape key
  useEffect(() => {
    if (!open) return
    function handleKeyDown(e: KeyboardEvent) {
      if (e.key === 'Escape') {
        onCancel()
      }
    }
    document.addEventListener('keydown', handleKeyDown)
    return () => document.removeEventListener('keydown', handleKeyDown)
  }, [open, onCancel])

  if (!open) return null

  return (
    <div className="confirm-modal-overlay" onClick={onCancel} role="presentation">
      <div
        className="confirm-modal"
        role="alertdialog"
        aria-modal="true"
        aria-labelledby="confirm-modal-title"
        aria-describedby="confirm-modal-message"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="confirm-modal-header">
          {variant === 'danger' && (
            <span className="confirm-modal-icon confirm-modal-icon--danger">
              <AlertTriangle size={18} />
            </span>
          )}
          <h2 id="confirm-modal-title" className="confirm-modal-title">{title}</h2>
        </div>
        <p id="confirm-modal-message" className="confirm-modal-message">{message}</p>
        <div className="confirm-modal-actions">
          <button
            ref={cancelRef}
            type="button"
            className="confirm-modal-btn confirm-modal-btn--cancel"
            onClick={onCancel}
          >
            {cancelLabel ?? t('common.cancel')}
          </button>
          <button
            ref={confirmRef}
            type="button"
            className={`confirm-modal-btn confirm-modal-btn--${variant}`}
            onClick={onConfirm}
          >
            {confirmLabel ?? t('common.confirm')}
          </button>
        </div>
      </div>
    </div>
  )
}

import React, { useState, useCallback, useEffect, useRef } from 'react'
import { useAppContext, exportVault } from '../state'
import { useTabContext } from '../state/tabContext'
import { useTranslation } from '../i18n'
import { openTab } from '../state/tabActions'
import type { DirectoryTree, VaultInfo } from '../types'
import { extractErrorMessage } from '../utils/error'
import { ChevronRight, ChevronDown, Database, Eye, Pencil, Users, FilePlus, FolderPlus, Trash2, Copy, Move, Download, Star, FileText, History, LayoutDashboard } from 'lucide-react'
import { getValidDropTargets } from '../utils/pathUtils'
import { ContextMenu } from './ContextMenu'
import type { ContextMenuItem } from './ContextMenu'
import { InlineInput } from './InlineInput'
import { ConfirmModal } from './ConfirmModal'
import { validateFileName, normalizeFileName } from '../utils/fileValidation'
import { showToast } from './ToastNotification'
import { favoritesStore } from '../state/favoritesStore'
import { TemplateSelector } from './TemplateSelector'
import { getCachedStatistics, fetchVaultStatistics, invalidateStatisticsCache, formatStatisticsTooltip } from '../state/vaultStatisticsCache'
import { onRealtimeVaultChange } from '../state/realtimeVaultBridge'
import { getState as getWorkspaceState, updateExpandedState } from '../state/workspaceStore'
import { TreeNode } from './file-explorer'
import type { DragState, ExternalDropState, ContextMenuState, InlineInputState } from './file-explorer'
import { getActiveWorkspaceShim } from '../plugins/compat/active-workspace-shim'
import { buildTFileFromPath } from '../plugins/compat/plugin-event-bridge'
import type { TFile, TFolder } from '../plugins/compat/types'

/**
 * Monotonic per-vault sequence counter used to discard out-of-order fetchVaultTree
 * responses (see refreshVaultTree). Deliberately module-scope rather than a ref: a
 * ref mutated/read from plain (non-useCallback) render-time closures ÔÇö like the
 * context-menu action switch below ÔÇö trips eslint-plugin-react-hooks' compiler-safety
 * rules for every call site that transitively reaches it.
 */
const vaultTreeRequestSeq = new Map<string, number>()

/**
 * Props for the FileExplorer component.
 */
export interface FileExplorerProps {
  /** When set, registers a callback that triggers inline new file creation at root. */
  onRegisterCreateFile?: (trigger: () => void) => void
  /** When set, registers a callback that triggers inline new folder creation at root. */
  onRegisterCreateFolder?: (trigger: () => void) => void
  /** When set, registers a callback that triggers vault creation. */
  onRegisterCreateVault?: (trigger: () => void) => void
  /** When set, registers a callback that triggers canvas creation at root. */
  onRegisterCreateCanvas?: (trigger: () => void) => void
  /** Callback to open the version browser for a specific file. */
  onOpenVersions?: (vaultId: string, filePath: string) => void
}

/**
 * FileExplorer renders all vaults as expandable root-level entries.
 * Expanding a vault lazy-loads its directory tree.
 * Clicking a file opens it in a tab and implicitly selects the vault.
 *
 * Provides context menu actions (new file, rename, delete) on each tree node.
 * Supports drag & drop for moving files and folders within a vault.
 */
export function FileExplorer({ onRegisterCreateFile, onRegisterCreateFolder, onRegisterCreateVault, onRegisterCreateCanvas, onOpenVersions }: FileExplorerProps = {}) {
  const { state, dispatch, apiClient } = useAppContext()
  const { tabState, tabDispatch } = useTabContext()
  const { t } = useTranslation()
  const [expandedPaths, setExpandedPaths] = useState<Set<string>>(() => new Set(getWorkspaceState().expandedPaths))
  const [expandedVaults, setExpandedVaults] = useState<Set<string>>(() => new Set(getWorkspaceState().expandedVaults))
  const [showCreateVaultForm, setShowCreateVaultForm] = useState(false)
  const [newVaultName, setNewVaultName] = useState('')
  const [vaultValidationError, setVaultValidationError] = useState<string | null>(null)
  const [dragState, setDragState] = useState<DragState>({
    draggedPath: null,
    draggedVaultId: null,
    validTargets: new Set(),
    isMoving: false,
  })
  const [externalDropState, setExternalDropState] = useState<ExternalDropState>({
    targetPath: null,
    targetVaultId: null,
  })
  const [contextMenuState, setContextMenuState] = useState<ContextMenuState>({
    visible: false,
    x: 0,
    y: 0,
    targetNode: null,
    vaultId: null,
  })
  const [inlineInputState, setInlineInputState] = useState<InlineInputState>({
    visible: false,
    mode: 'newFile',
    parentPath: '',
    node: null,
    vaultId: null,
  })
  const [deleteConfirm, setDeleteConfirm] = useState<{ open: boolean; node: DirectoryTree | null; vaultId: string | null }>({
    open: false,
    node: null,
    vaultId: null,
  })

  // Template selector state
  const [templateSelectorOpen, setTemplateSelectorOpen] = useState(false)
  const [templateSelectorVaultId, setTemplateSelectorVaultId] = useState<string | null>(null)

  // Vault statistics tooltip state
  const [vaultTooltips, setVaultTooltips] = useState<Record<string, string>>({})
  const tooltipFetchRef = useRef<Set<string>>(new Set())

  // Counter to force re-render when favorites change
  const [, setFavoritesVersion] = useState(0)

  // Several handlers below (delete, rename, move, create, drag/drop, lazy-load) each
  // independently fetch-then-dispatch a fresh tree. Without the sequence guard in
  // vaultTreeRequestSeq, an older request that happens to resolve after a newer one
  // (e.g. a lazy-load expand racing a delete) would overwrite current state with
  // stale data ÔÇö a deleted file reappearing in the explorer is the visible symptom.
  const refreshVaultTree = useCallback(async (vaultIdToRefresh: string): Promise<DirectoryTree> => {
    const seq = (vaultTreeRequestSeq.get(vaultIdToRefresh) ?? 0) + 1
    vaultTreeRequestSeq.set(vaultIdToRefresh, seq)
    const tree = await apiClient!.fetchVaultTree(vaultIdToRefresh)
    if (vaultTreeRequestSeq.get(vaultIdToRefresh) === seq) {
      dispatch({ type: 'VAULT_TREE_LOADED', payload: { vaultId: vaultIdToRefresh, tree } })
    }
    return tree
  }, [apiClient, dispatch])

  // Persist expanded paths/vaults to workspace store
  useEffect(() => {
    updateExpandedState([...expandedPaths], [...expandedVaults])
  }, [expandedPaths, expandedVaults])

  // On mount: lazy-load trees for vaults that were persisted as expanded
  const hasLoadedPersistedVaultsRef = useRef(false)
  useEffect(() => {
    if (hasLoadedPersistedVaultsRef.current) return
    if (expandedVaults.size === 0) return
    hasLoadedPersistedVaultsRef.current = true
    for (const vaultId of expandedVaults) {
      if (!state.vaultTrees[vaultId] && apiClient && !state.vaultTreesLoading.has(vaultId)) {
        dispatch({ type: 'VAULT_TREE_LOADING', payload: vaultId })
        refreshVaultTree(vaultId).catch(
          () => { /* silently ignore ÔÇö vault will show empty */ },
        )
      }
    }
  }, [expandedVaults, state.vaultTrees, state.vaultTreesLoading, dispatch, refreshVaultTree])

  /** Check if a file is a favorite for a given vault. */
  const checkIsFavorite = useCallback((vaultId: string, path: string): boolean => {
    return favoritesStore.isFavorite(vaultId, path)
  }, [])

  /** Toggle favorite status for a file. Triggers re-render via version counter. */
  const handleToggleFavorite = useCallback((vaultId: string, path: string) => {
    if (favoritesStore.isFavorite(vaultId, path)) {
      favoritesStore.remove(vaultId, path)
    } else {
      favoritesStore.add(vaultId, path)
    }
    setFavoritesVersion((v) => v + 1)
  }, [])

  // Determine the active file path (from the active tab)
  const activeTab = tabState.tabs.find((tab) => tab.id === tabState.activeTabId)
  const selectedFilePath = activeTab?.filePath ?? null
  const selectedFileVaultId = activeTab?.vaultId ?? null

  // Register the create file trigger for the toolbar button
  useEffect(() => {
    if (onRegisterCreateFile) {
      onRegisterCreateFile(() => {
        const vaultId = state.selectedVaultId
        if (!vaultId) return
        setInlineInputState({
          visible: true,
          mode: 'newFile',
          parentPath: '',
          node: null,
          vaultId,
        })
        // Ensure the vault is expanded
        setExpandedVaults((prev) => {
          const next = new Set(prev)
          next.add(vaultId)
          return next
        })
      })
    }
  }, [onRegisterCreateFile, state.selectedVaultId])

  // Register the create folder trigger for core commands (file-explorer:new-folder)
  useEffect(() => {
    if (onRegisterCreateFolder) {
      onRegisterCreateFolder(() => {
        const vaultId = state.selectedVaultId
        if (!vaultId) return
        setInlineInputState({
          visible: true,
          mode: 'newFolder',
          parentPath: '',
          node: null,
          vaultId,
        })
        setExpandedVaults((prev) => {
          const next = new Set(prev)
          next.add(vaultId)
          return next
        })
      })
    }
  }, [onRegisterCreateFolder, state.selectedVaultId])

  // Reveal a specific file in the tree (file-explorer:reveal-active-file core command):
  // expand its ancestor folders, then scroll it into view once it's rendered.
  const pendingRevealPathRef = useRef<string | null>(null)
  useEffect(() => {
    function handleRevealFile(e: Event) {
      const detail = (e as CustomEvent<{ path: string }>).detail
      if (!detail?.path) return
      const vaultId = state.selectedVaultId
      if (!vaultId) return

      pendingRevealPathRef.current = detail.path
      setExpandedVaults((prev) => {
        const next = new Set(prev)
        next.add(vaultId)
        return next
      })
      setExpandedPaths((prev) => {
        const next = new Set(prev)
        const segments = detail.path.split('/')
        let acc = ''
        for (let i = 0; i < segments.length - 1; i++) {
          acc = acc ? `${acc}/${segments[i]}` : segments[i]
          next.add(acc)
        }
        return next
      })
    }

    window.addEventListener('slatebase:reveal-file', handleRevealFile)
    return () => window.removeEventListener('slatebase:reveal-file', handleRevealFile)
  }, [state.selectedVaultId])

  // Runs after every render: once the revealed file's ancestors are expanded and it
  // exists in the DOM, scroll to it and clear the pending request.
  useEffect(() => {
    const path = pendingRevealPathRef.current
    if (!path) return
    const el = document.querySelector(`[data-path="${CSS.escape(path)}"].tree-node--file`)
    if (el) {
      el.scrollIntoView({ block: 'center', behavior: 'smooth' })
      pendingRevealPathRef.current = null
    }
  })

  // Register the create vault trigger for the toolbar button
  useEffect(() => {
    if (onRegisterCreateVault) {
      onRegisterCreateVault(() => {
        setShowCreateVaultForm(true)
        setNewVaultName('')
        setVaultValidationError(null)
      })
    }
  }, [onRegisterCreateVault])

  /** Creates a new .canvas file with empty content and opens it. */
  async function createCanvasFile(vaultId: string, parentPath: string) {
    if (!apiClient) return
    setInlineInputState({
      visible: true,
      mode: 'newCanvas',
      parentPath,
      node: null,
      vaultId,
    })
    // Ensure the vault is expanded so the inline input is visible
    setExpandedVaults((prev) => {
      const next = new Set(prev)
      next.add(vaultId)
      return next
    })
  }

  // Register the create canvas trigger for the toolbar button
  useEffect(() => {
    if (onRegisterCreateCanvas) {
      onRegisterCreateCanvas(() => {
        const vaultId = state.selectedVaultId
        if (!vaultId || !apiClient) return
        void createCanvasFile(vaultId, '')
      })
    }
  }, [onRegisterCreateCanvas, state.selectedVaultId]) // eslint-disable-line react-hooks/exhaustive-deps

  // Subscribe to vault:change events for statistics cache invalidation
  useEffect(() => {
    return onRealtimeVaultChange((event) => {
      invalidateStatisticsCache(event.vaultId)
      // Clear the tooltip text so it re-fetches on next hover
      setVaultTooltips((prev) => {
        const next = { ...prev }
        delete next[event.vaultId]
        return next
      })
      tooltipFetchRef.current.delete(event.vaultId)
    })
  }, [])

  /** Handle mouse entering a vault entry row ÔÇö fetch and display statistics tooltip. */
  const handleVaultMouseEnter = useCallback((vaultId: string) => {
    // If we already have a tooltip or fetch is in-flight, use cached
    const cached = getCachedStatistics(vaultId)
    if (cached) {
      setVaultTooltips((prev) => ({ ...prev, [vaultId]: formatStatisticsTooltip(cached) }))
      return
    }

    // Avoid multiple fetches for the same vault
    if (tooltipFetchRef.current.has(vaultId)) return
    tooltipFetchRef.current.add(vaultId)

    if (!apiClient) return

    fetchVaultStatistics(apiClient, vaultId).then((entry) => {
      if (entry) {
        setVaultTooltips((prev) => ({ ...prev, [vaultId]: formatStatisticsTooltip(entry) }))
      } else {
        // Show error text only if no cached value exists
        setVaultTooltips((prev) => {
          if (prev[vaultId]) return prev // Keep existing tooltip
          return { ...prev, [vaultId]: t('fileOps.statisticsUnavailable') }
        })
      }
    }).catch(() => {
      setVaultTooltips((prev) => {
        if (prev[vaultId]) return prev
        return { ...prev, [vaultId]: t('fileOps.statisticsUnavailable') }
      })
    })
  }, [apiClient])

  /** Handle vault creation form submission. */
  async function handleCreateVaultSubmit(e: React.FormEvent) {
    e.preventDefault()
    const trimmed = newVaultName.trim()
    if (trimmed.length === 0) {
      setVaultValidationError(t('vault.nameEmpty'))
      return
    }
    if (trimmed.length > 128) {
      setVaultValidationError(t('vault.nameTooLong', { max: 128 }))
      return
    }
    if (state.vaults.some((v) => v.name === trimmed)) {
      setVaultValidationError(t('vault.nameExists', { name: trimmed }))
      return
    }
    if (!apiClient) return

    try {
      const vault = await apiClient.createVault(trimmed)
      dispatch({ type: 'VAULT_CREATED', payload: vault })
      setShowCreateVaultForm(false)
      setNewVaultName('')
      setVaultValidationError(null)
      // Auto-expand the new vault
      setExpandedVaults((prev) => {
        const next = new Set(prev)
        next.add(vault.id)
        return next
      })
      // Select the new vault
      dispatch({ type: 'VAULT_SELECTED', payload: vault.id })
    } catch (err: unknown) {
      setVaultValidationError(extractErrorMessage(err, t('common.error')))
    }
  }

  /** Toggle a vault's expanded state and lazy-load its tree. */
  function handleToggleVault(vaultId: string) {
    // Select this vault on click
    if (state.selectedVaultId !== vaultId) {
      dispatch({ type: 'VAULT_SELECTED', payload: vaultId })
      // Update legacy directoryTree
      const tree = state.vaultTrees[vaultId]
      if (tree) {
        dispatch({ type: 'TREE_LOADED', payload: tree })
      }
    }

    const wasExpanded = expandedVaults.has(vaultId)

    setExpandedVaults((prev) => {
      const next = new Set(prev)
      if (next.has(vaultId)) {
        next.delete(vaultId)
      } else {
        next.add(vaultId)
      }
      return next
    })

    // Lazy-load tree outside of setState updater (avoids dispatch-during-render warning)
    if (!wasExpanded && !state.vaultTrees[vaultId] && apiClient && !state.vaultTreesLoading.has(vaultId)) {
      dispatch({ type: 'VAULT_TREE_LOADING', payload: vaultId })
      refreshVaultTree(vaultId).catch(
        () => { /* silently ignore ÔÇö vault will show empty */ },
      )
    }
  }

  function handleToggleFolder(path: string) {
    setExpandedPaths((prev) => {
      const next = new Set(prev)
      if (next.has(path)) {
        next.delete(path)
      } else {
        next.add(path)
      }
      return next
    })
  }

  function handleSelectFile(vaultId: string, filePath: string, fileName: string) {
    if (apiClient) {
      // Implicitly select this vault
      if (state.selectedVaultId !== vaultId) {
        dispatch({ type: 'VAULT_SELECTED', payload: vaultId })
        // Update the legacy directoryTree
        const tree = state.vaultTrees[vaultId]
        if (tree) {
          dispatch({ type: 'TREE_LOADED', payload: tree })
        }
      }
      openTab(tabDispatch, dispatch, apiClient, vaultId, filePath, fileName)
    }
  }

  // --- Context Menu Handlers ---

  /**
   * Build extra context menu items contributed by plugins via
   * `workspace.on('file-menu', (menu, file, source) => menu.addItem(...))`
   * (Obsidian's real event for "user right-clicked a file/folder in the
   * explorer"). Returns [] when no plugin is listening (or none are loaded
   * yet), in which case the menu looks exactly as it did before this existed.
   */
  function buildPluginMenuItems(node: DirectoryTree): ContextMenuItem[] {
    const workspaceShim = getActiveWorkspaceShim()
    const MenuCtor = (window as unknown as { obsidian?: { Menu?: new () => { items: Array<{ kind: string; title: string; icon: string; disabled: boolean; callback: (evt: MouseEvent | KeyboardEvent) => void }> } } }).obsidian?.Menu
    if (!workspaceShim || !MenuCtor) return []

    const file: TFile | TFolder = node.type === 'file'
      ? buildTFileFromPath(node.path)
      : {
          path: node.path,
          name: node.name,
          children: [],
          parent: null,
          isRoot: () => node.path === '',
        }

    const menu = new MenuCtor()
    try {
      workspaceShim.trigger('file-menu', menu, file, 'file-explorer-context-menu')
    } catch (err) {
      console.error('[FileExplorer] A plugin\'s file-menu handler threw:', err)
    }

    const items: ContextMenuItem[] = []
    menu.items.forEach((entry, index) => {
      if (entry.kind === 'separator') {
        items.push({ id: `plugin-menu-sep-${index}`, label: '', separator: true })
        return
      }
      items.push({
        id: `plugin-menu-item-${index}`,
        label: entry.title,
        disabled: entry.disabled,
        run: () => {
          try {
            entry.callback(new MouseEvent('click'))
          } catch (err) {
            console.error('[FileExplorer] A plugin\'s file-menu item threw:', err)
          }
        },
      })
    })

    if (items.length === 0) return []
    return [{ id: 'plugin-menu-sep-leading', label: '', separator: true }, ...items]
  }

  function handleContextMenu(e: React.MouseEvent, node: DirectoryTree, vaultId: string) {
    e.preventDefault()
    e.stopPropagation()
    setContextMenuState({
      visible: true,
      x: e.clientX,
      y: e.clientY,
      targetNode: node,
      vaultId,
    })
  }

  /** Handle right-click on vault row (show context menu with vault root as target). */
  function handleVaultContextMenu(e: React.MouseEvent, vault: VaultInfo) {
    e.preventDefault()
    e.stopPropagation()
    // Create a synthetic root node representing the vault root
    const rootNode: DirectoryTree = {
      name: vault.name,
      path: '',
      type: 'directory',
      children: [],
    }
    setContextMenuState({
      visible: true,
      x: e.clientX,
      y: e.clientY,
      targetNode: rootNode,
      vaultId: vault.id,
    })
  }

  /** Handle right-click on empty area of the file explorer. */
  function handleEmptyAreaContextMenu(e: React.MouseEvent) {
    // Don't override context menu if it bubbled from a child node
    // (child handlers call stopPropagation, so if we get here, it's the empty area)
    e.preventDefault()

    // Use selected vault, or fall back to first vault
    const vaultId = state.selectedVaultId ?? state.vaults[0]?.id
    if (!vaultId) return

    const vault = state.vaults.find((v) => v.id === vaultId)
    if (!vault) return

    // Create a synthetic root node for the selected vault
    const rootNode: DirectoryTree = {
      name: vault.name,
      path: '',
      type: 'directory',
      children: [],
    }
    setContextMenuState({
      visible: true,
      x: e.clientX,
      y: e.clientY,
      targetNode: rootNode,
      vaultId,
    })
  }

  function handleCloseContextMenu() {
    setContextMenuState((prev) => ({ ...prev, visible: false }))
  }

  function handleNewFile(parentPath: string) {
    const vaultId = contextMenuState.vaultId
    if (!vaultId) return
    // Expand the parent folder so the inline input is visible
    setExpandedPaths((prev) => {
      const next = new Set(prev)
      next.add(`${vaultId}::${parentPath}`)
      return next
    })
    setInlineInputState({
      visible: true,
      mode: 'newFile',
      parentPath,
      node: null,
      vaultId,
    })
  }

  function handleNewFolder(parentPath: string) {
    const vaultId = contextMenuState.vaultId
    if (!vaultId) return
    // Expand the parent folder so the inline input is visible
    setExpandedPaths((prev) => {
      const next = new Set(prev)
      next.add(`${vaultId}::${parentPath}`)
      return next
    })
    setInlineInputState({
      visible: true,
      mode: 'newFolder',
      parentPath,
      node: null,
      vaultId,
    })
  }

  async function handleCopyFile(node: DirectoryTree) {
    const vaultId = contextMenuState.vaultId
    if (!vaultId || !apiClient) return

    // Determine a target path for the copy (same directory, with suffix)
    const parentDir = node.path.lastIndexOf('/') === -1
      ? ''
      : node.path.slice(0, node.path.lastIndexOf('/'))
    const ext = node.name.lastIndexOf('.') > 0 ? node.name.slice(node.name.lastIndexOf('.')) : ''
    const baseName = ext ? node.name.slice(0, node.name.lastIndexOf('.')) : node.name
    const copyName = `${baseName}-Kopie${ext}`
    const copyPath = parentDir ? `${parentDir}/${copyName}` : copyName

    try {
      // Read the source file content and save as a copy
      const fileContent = await apiClient.fetchFileContent(vaultId, node.path)
      await apiClient.saveFile(vaultId, copyPath, fileContent.content)
      await refreshVaultTree(vaultId)
      showToast('success', `${copyName}`)
    } catch (err: unknown) {
      showToast('error', extractErrorMessage(err, t('fileOps.copyError')))
    }
  }

  async function handleMoveFile(node: DirectoryTree) {
    const vaultId = contextMenuState.vaultId
    if (!vaultId || !apiClient) return

    // Prompt for destination path using a simple approach: move to root
    // We use the existing drag/drop mechanism implicitly ÔÇö 
    // For the context menu version, we trigger inline input for a move destination
    const destination = window.prompt(t('fileOps.movePrompt'), '')
    if (destination === null) return // Cancelled

    const trimmedDest = destination.trim()
    const fileName = node.path.split('/').pop() ?? node.name
    const destinationPath = trimmedDest ? `${trimmedDest}/${fileName}` : fileName

    if (destinationPath === node.path) return

    try {
      await apiClient.moveContent(vaultId, node.path, destinationPath)
      await refreshVaultTree(vaultId)
      tabDispatch({
        type: 'UPDATE_TAB_PATHS',
        payload: { oldPathPrefix: node.path, newPathPrefix: destinationPath },
      })

      // Update favorites path on move
      favoritesStore.updatePath(vaultId, node.path, destinationPath)
      setFavoritesVersion((v) => v + 1)
    } catch (err: unknown) {
      showToast('error', extractErrorMessage(err, t('fileOps.moveError')))
    }
  }

  function handleExportVault() {
    const vaultId = contextMenuState.vaultId
    if (!vaultId || !apiClient) return
    const vault = state.vaults.find((v) => v.id === vaultId)
    void exportVault(dispatch, apiClient, vaultId, vault?.name)
  }

  function handleNewFromTemplate() {
    const vaultId = contextMenuState.vaultId
    if (!vaultId) return
    setTemplateSelectorVaultId(vaultId)
    setTemplateSelectorOpen(true)
  }

  function handleTemplateFileCreated(filePath: string, fileName: string) {
    const vaultId = templateSelectorVaultId
    if (!vaultId || !apiClient) return
    // Open the created file in a tab
    openTab(tabDispatch, dispatch, apiClient, vaultId, filePath, fileName.endsWith('.md') ? fileName : `${fileName}.md`)
    // Refresh file tree
    refreshVaultTree(vaultId).catch(() => { /* ignore */ })
  }

  function handleRename(node: DirectoryTree) {
    setInlineInputState({
      visible: true,
      mode: 'rename',
      parentPath: '',
      node,
      vaultId: contextMenuState.vaultId,
    })
  }

  function handleDelete(node: DirectoryTree) {
    setDeleteConfirm({ open: true, node, vaultId: contextMenuState.vaultId })
  }

  function handleDeleteConfirmed() {
    const node = deleteConfirm.node
    const vaultId = deleteConfirm.vaultId
    setDeleteConfirm({ open: false, node: null, vaultId: null })
    if (!node || !vaultId || !apiClient) return

    // Close affected tabs and drop favorites immediately, before the delete request
    // round-trips. Recreating a file at the same path (e.g. a daily note for the same
    // day) reuses a deterministic tab id (vaultId::filePath); if the old tab were still
    // open when that happens, OPEN_TAB would reactivate it with its stale content
    // instead of loading the freshly created file. Doing this synchronously ÔÇö rather
    // than in the delete's .then() ÔÇö closes that window regardless of network timing.
    tabDispatch({
      type: 'CLOSE_TABS_BY_PATH',
      payload: { pathPrefix: node.path },
    })
    favoritesStore.removeByPath(vaultId, node.path)
    setFavoritesVersion((v) => v + 1)

    apiClient.deleteContent(vaultId, node.path).then(async () => {
      // Reload tree for this vault
      await refreshVaultTree(vaultId)
    }).catch((err: unknown) => {
      showToast('error', extractErrorMessage(err, t('fileOps.deleteError')))
    })
  }

  function handleDeleteCancelled() {
    setDeleteConfirm({ open: false, node: null, vaultId: null })
  }

  /** Handles a context menu action selection for the currently targeted node. */
  function handleMenuSelect(action: string) {
    const node = contextMenuState.targetNode
    if (!node) return

    switch (action) {
      case 'newFile': {
        const parentPath = node.type === 'directory'
          ? node.path
          : node.path.lastIndexOf('/') === -1 ? '' : node.path.slice(0, node.path.lastIndexOf('/'))
        handleNewFile(parentPath)
        break
      }
      case 'newFolder': {
        const parentPath = node.type === 'directory'
          ? node.path
          : node.path.lastIndexOf('/') === -1 ? '' : node.path.slice(0, node.path.lastIndexOf('/'))
        handleNewFolder(parentPath)
        break
      }
      case 'newCanvas': {
        const vaultId = contextMenuState.vaultId
        if (!vaultId) break
        const parentPath = node.type === 'directory'
          ? node.path
          : node.path.lastIndexOf('/') === -1 ? '' : node.path.slice(0, node.path.lastIndexOf('/'))
        void createCanvasFile(vaultId, parentPath)
        break
      }
      case 'rename':
        handleRename(node)
        break
      case 'delete':
        handleDelete(node)
        break
      case 'copy':
        void handleCopyFile(node)
        break
      case 'move':
        void handleMoveFile(node)
        break
      case 'export':
        handleExportVault()
        break
      case 'newFromTemplate':
        handleNewFromTemplate()
        break
      case 'toggleFavorite':
        if (contextMenuState.vaultId) {
          handleToggleFavorite(contextMenuState.vaultId, node.path)
        }
        break
      case 'versions':
        if (contextMenuState.vaultId && onOpenVersions) {
          onOpenVersions(contextMenuState.vaultId, node.path)
        }
        break
    }
  }

  // --- Inline Input Handlers ---

  async function handleInlineConfirm(value: string) {
    const vaultId = inlineInputState.vaultId
    if (!vaultId || !apiClient) return

    if (inlineInputState.mode === 'newFile') {
      const normalizedName = normalizeFileName(value)
      const validationError = validateFileName(normalizedName)
      if (validationError) return

      const filePath = inlineInputState.parentPath
        ? `${inlineInputState.parentPath}/${normalizedName}`
        : normalizedName

      try {
        await apiClient.saveFile(vaultId, filePath, '')
        await refreshVaultTree(vaultId)
        // Implicitly select this vault and open the file
        if (state.selectedVaultId !== vaultId) {
          dispatch({ type: 'VAULT_SELECTED', payload: vaultId })
        }
        openTab(tabDispatch, dispatch, apiClient, vaultId, filePath, normalizedName)
      } catch (err: unknown) {
        const msg = err !== null && typeof err === 'object' && 'message' in err
          ? (err as { message: string }).message
          : t('fileOps.createError')
        showToast('error', msg)
      }
    } else if (inlineInputState.mode === 'newFolder') {
      const normalizedName = normalizeFileName(value)
      const validationError = validateFileName(normalizedName)
      if (validationError) return

      const folderPath = inlineInputState.parentPath
        ? `${inlineInputState.parentPath}/${normalizedName}`
        : normalizedName

      // Create a folder by creating a placeholder file inside it, then the folder exists
      // We use saveFile with a .gitkeep or directly with a trailing path that implies directory
      const placeholderPath = `${folderPath}/.gitkeep`

      try {
        await apiClient.saveFile(vaultId, placeholderPath, '')
        // Delete the placeholder ÔÇö the folder now exists on the backend
        await apiClient.deleteContent(vaultId, placeholderPath)
        await refreshVaultTree(vaultId)
        // Expand the new folder
        setExpandedPaths((prev) => {
          const next = new Set(prev)
          next.add(`${vaultId}::${folderPath}`)
          return next
        })
      } catch (err: unknown) {
        const msg = err !== null && typeof err === 'object' && 'message' in err
          ? (err as { message: string }).message
          : t('fileOps.createError')
        showToast('error', msg)
      }
    } else if (inlineInputState.mode === 'newCanvas') {
      const trimmedName = value.trim()
      if (!trimmedName) return
      const validationError = validateFileName(trimmedName.endsWith('.canvas') ? trimmedName : `${trimmedName}.canvas`)
      if (validationError) return

      // Ensure .canvas extension
      const canvasName = trimmedName.endsWith('.canvas') ? trimmedName : `${trimmedName}.canvas`
      const filePath = inlineInputState.parentPath
        ? `${inlineInputState.parentPath}/${canvasName}`
        : canvasName
      const emptyCanvas = '{\n\t"nodes": [],\n\t"edges": []\n}'

      try {
        await apiClient.saveFile(vaultId, filePath, emptyCanvas)
        await refreshVaultTree(vaultId)
        if (state.selectedVaultId !== vaultId) {
          dispatch({ type: 'VAULT_SELECTED', payload: vaultId })
        }
        openTab(tabDispatch, dispatch, apiClient, vaultId, filePath, canvasName)
        showToast('success', t('fileOps.created', { name: canvasName }))
      } catch (err: unknown) {
        showToast('error', extractErrorMessage(err, t('fileOps.canvasCreateError')))
      }
    } else if (inlineInputState.mode === 'rename') {
      const node = inlineInputState.node
      if (!node) return

      let newName = value
      if (newName === node.name) {
        setInlineInputState((prev) => ({ ...prev, visible: false }))
        return
      }

      // For files: preserve original extension if none provided
      if (node.type === 'file') {
        const lastDot = node.name.lastIndexOf('.')
        if (lastDot > 0) {
          const originalExt = node.name.slice(lastDot)
          const newNameHasDot = newName.lastIndexOf('.')
          if (newNameHasDot <= 0) {
            newName = newName + originalExt
          }
        }
      }

      const validationError = validateFileName(newName, 255)
      if (validationError) return

      try {
        await apiClient.renameContent(vaultId, node.path, newName)
        await refreshVaultTree(vaultId)

        // Update tab paths
        const oldPath = node.path
        const parentDir = oldPath.lastIndexOf('/') === -1
          ? ''
          : oldPath.slice(0, oldPath.lastIndexOf('/'))
        const newPath = parentDir ? `${parentDir}/${newName}` : newName

        tabDispatch({
          type: 'UPDATE_TAB_PATHS',
          payload: { oldPathPrefix: oldPath, newPathPrefix: newPath },
        })

        // Update favorites path on rename
        favoritesStore.updatePath(vaultId, oldPath, newPath)
        setFavoritesVersion((v) => v + 1)
      } catch (err: unknown) {
        const msg = err !== null && typeof err === 'object' && 'message' in err
          ? (err as { message: string }).message
          : t('fileOps.renameError')
        showToast('error', msg)
      }
    }

    setInlineInputState((prev) => ({ ...prev, visible: false }))
  }

  function handleInlineCancel() {
    setInlineInputState((prev) => ({ ...prev, visible: false }))
  }

  // --- Drag & Drop Handlers ---

  const handleDragStart = useCallback((e: React.DragEvent<HTMLDivElement>, nodePath: string, nodeType: 'file' | 'directory', vaultId: string) => {
    const vault = state.vaults.find((v) => v.id === vaultId)
    if (vault?.permission === 'read' || dragState.isMoving) {
      e.preventDefault()
      return
    }

    const tree = state.vaultTrees[vaultId]
    if (!tree) {
      e.preventDefault()
      return
    }

    const validTargets = getValidDropTargets(tree, nodePath)

    setDragState({
      draggedPath: nodePath,
      draggedVaultId: vaultId,
      validTargets,
      isMoving: false,
    })

    e.dataTransfer.effectAllowed = 'copyMove'
    e.dataTransfer.setData('application/x-slatebase-path', nodePath)
    e.dataTransfer.setData('application/x-slatebase-type', nodeType)
    e.dataTransfer.setData('application/x-slatebase-vaultid', vaultId)

    const target = e.currentTarget as HTMLElement
    target.style.opacity = '0.5'
  }, [state.vaults, state.vaultTrees, dragState.isMoving])

  const handleDragEnd = useCallback((e: React.DragEvent<HTMLDivElement>) => {
    const target = e.currentTarget as HTMLElement
    target.style.opacity = ''
    setDragState((prev) => ({
      ...prev,
      draggedPath: null,
      draggedVaultId: null,
      validTargets: new Set(),
    }))
  }, [])

  const handleDragOver = useCallback((e: React.DragEvent<HTMLDivElement>, folderPath: string, vaultId: string) => {
    // Internal DnD (moving files within the explorer)
    if (dragState.validTargets.has(folderPath)) {
      e.preventDefault()
      e.dataTransfer.dropEffect = 'move'
      return
    }

    // External file drag from OS (no internal drag in progress)
    if (!dragState.draggedPath && e.dataTransfer.types.includes('Files')) {
      // Don't accept external drops on read-only vaults
      const vault = state.vaults.find((v) => v.id === vaultId)
      if (vault?.permission === 'read') return

      e.preventDefault()
      e.stopPropagation()
      e.dataTransfer.dropEffect = 'copy'

      setExternalDropState((prev) => {
        if (prev.targetPath === folderPath && prev.targetVaultId === vaultId) return prev
        return { targetPath: folderPath, targetVaultId: vaultId }
      })
    }
  }, [dragState.validTargets, dragState.draggedPath, state.vaults])

  const handleDragLeave = useCallback((_e: React.DragEvent<HTMLDivElement>, folderPath: string, vaultId: string) => {
    // Clear external drop target when leaving a folder
    setExternalDropState((prev) => {
      if (prev.targetPath === folderPath && prev.targetVaultId === vaultId) {
        return { targetPath: null, targetVaultId: null }
      }
      return prev
    })
  }, [])

  const handleDrop = useCallback(async (e: React.DragEvent<HTMLDivElement>, targetFolderPath: string, dropVaultId: string) => {
    e.preventDefault()

    // Clear external drop state
    setExternalDropState({ targetPath: null, targetVaultId: null })

    // Check if this is an external file drop from OS
    if (!dragState.draggedPath && e.dataTransfer.files.length > 0) {
      e.stopPropagation()
      if (!apiClient) return

      const vault = state.vaults.find((v) => v.id === dropVaultId)
      if (!vault || vault.permission === 'read') return

      const droppedFiles = Array.from(e.dataTransfer.files)

      // Validate: max 50 files
      if (droppedFiles.length > 50) {
        showToast('error', `Maximal 50 Dateien pro Drop-Vorgang erlaubt (${droppedFiles.length} ausgew├ñhlt)`)
        return
      }

      // Validate individual file sizes (100 MB max)
      const maxFileSize = 104857600
      const validFiles: File[] = []
      for (const file of droppedFiles) {
        if (file.size > maxFileSize) {
          showToast('error', `"${file.name}" ├╝berschreitet die maximale Dateigr├Â├ƒe von 100 MB`)
          continue
        }
        validFiles.push(file)
      }

      if (validFiles.length === 0) return

      try {
        await apiClient.uploadFiles(dropVaultId, validFiles, targetFolderPath)
        await refreshVaultTree(dropVaultId)
      } catch (err) {
        for (const file of validFiles) {
          const reason = err instanceof Error ? err.message : 'Upload fehlgeschlagen'
          showToast('error', `"${file.name}": ${reason}`)
        }
      }
      return
    }

    // Internal DnD: move file/folder within vault
    if (!dragState.validTargets.has(targetFolderPath)) return
    if (!dragState.draggedPath || !dragState.draggedVaultId) return
    if (!apiClient) return

    const vaultId = dragState.draggedVaultId
    const draggedPath = dragState.draggedPath
    const draggedFileName = draggedPath.split('/').pop() ?? draggedPath

    const destinationPath = targetFolderPath
      ? `${targetFolderPath}/${draggedFileName}`
      : draggedFileName

    setDragState({
      draggedPath: null,
      draggedVaultId: null,
      validTargets: new Set(),
      isMoving: true,
    })

    try {
      await apiClient.moveContent(vaultId, draggedPath, destinationPath)
      await refreshVaultTree(vaultId)
      tabDispatch({
        type: 'UPDATE_TAB_PATHS',
        payload: { oldPathPrefix: draggedPath, newPathPrefix: destinationPath },
      })

      // Update favorites path on drag-drop move
      favoritesStore.updatePath(vaultId, draggedPath, destinationPath)
      setFavoritesVersion((v) => v + 1)
    } catch (err: unknown) {
      showToast('error', extractErrorMessage(err, t('fileOps.moveError')))
    } finally {
      setDragState({
        draggedPath: null,
        draggedVaultId: null,
        validTargets: new Set(),
        isMoving: false,
      })
    }
  }, [dragState.validTargets, dragState.draggedPath, dragState.draggedVaultId, apiClient, state.vaults, tabDispatch, t, refreshVaultTree])

  // --- Root Drop Zone Handlers (per vault) ---

  const handleRootDragOver = useCallback((e: React.DragEvent<HTMLDivElement>, vaultId: string) => {
    // Internal DnD
    if (dragState.validTargets.has('')) {
      e.preventDefault()
      e.dataTransfer.dropEffect = 'move'
      return
    }
    // External file drag
    if (!dragState.draggedPath && e.dataTransfer.types.includes('Files')) {
      const vault = state.vaults.find((v) => v.id === vaultId)
      if (vault?.permission === 'read') return
      e.preventDefault()
      e.stopPropagation()
      e.dataTransfer.dropEffect = 'copy'
      setExternalDropState((prev) => {
        if (prev.targetPath === '' && prev.targetVaultId === vaultId) return prev
        return { targetPath: '', targetVaultId: vaultId }
      })
    }
  }, [dragState.validTargets, dragState.draggedPath, state.vaults])

  const handleRootDrop = useCallback((e: React.DragEvent<HTMLDivElement>, vaultId: string) => {
    e.preventDefault()
    handleDrop(e, '', vaultId)
  }, [handleDrop])

  /** Clear external drop state when dragging leaves the explorer entirely. */
  const handleExplorerDragLeave = useCallback((e: React.DragEvent<HTMLDivElement>) => {
    // Only clear if leaving the container itself (not bubbling from children)
    const container = e.currentTarget
    const relatedTarget = e.relatedTarget as Node | null
    if (relatedTarget && container.contains(relatedTarget)) return
    setExternalDropState({ targetPath: null, targetVaultId: null })
  }, [])

  /** Render vault status badges. */
  function renderVaultBadges(vault: VaultInfo) {
    return (
      <>
        {vault.permission === 'read' && (
          <span className="vault-status-icon vault-status-icon--read" title={t('vault.permissionRead')}>
            <Eye size={11} />
          </span>
        )}
        {vault.permission === 'write' && (
          <span className="vault-status-icon vault-status-icon--write" title={t('vault.permissionWrite')}>
            <Pencil size={11} />
          </span>
        )}
        {(vault.shareCount ?? 0) > 0 && (
          <span className="vault-status-icon vault-status-icon--shared" title={t('vault.shared', { count: vault.shareCount ?? 0 })}>
            <Users size={11} />
          </span>
        )}
      </>
    )
  }

  return (
    <div
      className={`file-explorer-container${dragState.isMoving ? ' file-explorer--moving' : ''}`}
      onContextMenu={handleEmptyAreaContextMenu}
      onDragLeave={handleExplorerDragLeave}
    >
      {/* Loading indicator while moving */}
      {dragState.isMoving && (
        <div className="file-explorer-moving-indicator">
          {t('fileOps.moving')}
        </div>
      )}

      {/* Vault list as tree */}
      {state.vaults.length === 0 ? (
        <p className="file-explorer-empty">{t('vault.noVaults')}</p>
      ) : (
        <>
          <nav className="file-explorer" aria-label="File explorer">
          <ul className="file-explorer-tree" role="tree">
            {state.vaults.map((vault) => {
              const isExpanded = expandedVaults.has(vault.id)
              const isSelected = state.selectedVaultId === vault.id
              const tree = state.vaultTrees[vault.id]
              const isLoading = state.vaultTreesLoading.has(vault.id)
              const permission = vault.permission

              // Show new file/folder/canvas input at vault root level
              const showRootNewFileInput = inlineInputState.visible
                && (inlineInputState.mode === 'newFile' || inlineInputState.mode === 'newFolder' || inlineInputState.mode === 'newCanvas')
                && inlineInputState.parentPath === ''
                && inlineInputState.vaultId === vault.id

              const showRootDropZone = dragState.draggedPath !== null
                && dragState.draggedVaultId === vault.id
                && dragState.validTargets.has('')

              return (
                <li key={vault.id} className="tree-node tree-node--vault">
                  <div
                    className={`tree-node-row tree-node-row--vault${isSelected ? ' tree-node-row--vault-selected' : ''}${externalDropState.targetPath === '' && externalDropState.targetVaultId === vault.id ? ' tree-node--drop-target' : ''}`}
                    onContextMenu={(e) => handleVaultContextMenu(e, vault)}
                    onMouseEnter={() => handleVaultMouseEnter(vault.id)}
                    onDragOver={(e) => handleRootDragOver(e, vault.id)}
                    onDragLeave={() => setExternalDropState((prev) => prev.targetPath === '' && prev.targetVaultId === vault.id ? { targetPath: null, targetVaultId: null } : prev)}
                    onDrop={(e) => handleRootDrop(e, vault.id)}
                  >
                    <button
                      type="button"
                      className="tree-node-toggle tree-node-toggle--vault"
                      aria-expanded={isExpanded}
                      onClick={() => handleToggleVault(vault.id)}
                      title={vaultTooltips[vault.id] || vault.name}
                    >
                      <span className="tree-node-chevron" aria-hidden="true">
                        {isExpanded ? <ChevronDown size={12} /> : <ChevronRight size={12} />}
                      </span>
                      <Database size={14} style={{ flexShrink: 0, color: isSelected ? 'var(--accent)' : 'var(--sidebar-text)' }} />
                      <span className="tree-node-name tree-node-name--vault">
                        {vault.name}
                      </span>
                      {renderVaultBadges(vault)}
                    </button>
                  </div>

                  {/* Vault content (expanded) */}
                  {isExpanded && (
                    <ul className="tree-node-children tree-node-children--vault" role="group">
                      {isLoading && (
                        <li className="tree-node tree-node--loading">
                          <span className="tree-node-loading-text">{t('common.loading')}</span>
                        </li>
                      )}
                      {!isLoading && tree && tree.children && tree.children.length > 0 && (
                        tree.children
                          .filter((child) => child.name !== '.trash' && child.name !== '.versions')
                          .map((child) => (
                          <TreeNode
                            key={child.path}
                            node={child}
                            selectedFilePath={selectedFileVaultId === vault.id ? selectedFilePath : null}
                            expandedPaths={expandedPaths}
                            onToggleFolder={handleToggleFolder}
                            onSelectFile={(filePath, fileName) => handleSelectFile(vault.id, filePath, fileName)}
                            dragState={dragState}
                            externalDropState={externalDropState}
                            permission={permission}
                            vaultId={vault.id}
                            onDragStart={handleDragStart}
                            onDragEnd={handleDragEnd}
                            onDragOver={handleDragOver}
                            onDragLeave={handleDragLeave}
                            onDrop={handleDrop}
                            onContextMenu={handleContextMenu}
                            inlineInputState={inlineInputState}
                            onInlineConfirm={handleInlineConfirm}
                            onInlineCancel={handleInlineCancel}
                            isFavorite={(path) => checkIsFavorite(vault.id, path)}
                            onToggleFavorite={(path) => handleToggleFavorite(vault.id, path)}
                          />
                        ))
                      )}
                      {!isLoading && tree && (!tree.children || tree.children.length === 0) && (
                        <li className="tree-node tree-node--empty">
                          <span className="tree-node-empty-text">{t('vault.empty')}</span>
                        </li>
                      )}
                      {showRootNewFileInput && (
                        <li className="tree-node tree-node--file">
                          <div className="tree-node-row">
                            <InlineInput
                              initialValue=""
                              onConfirm={handleInlineConfirm}
                              onCancel={handleInlineCancel}
                              validate={(value) => {
                                if (inlineInputState.mode === 'newCanvas') {
                                  const name = value.trim().endsWith('.canvas') ? value.trim() : `${value.trim()}.canvas`
                                  return validateFileName(name)
                                }
                                const normalized = normalizeFileName(value)
                                return validateFileName(normalized)
                              }}
                            />
                          </div>
                        </li>
                      )}
                      {showRootDropZone && (
                        <li className="tree-node">
                          <div
                            className="file-explorer-root-drop-zone"
                            onDragOver={(e) => handleRootDragOver(e, vault.id)}
                            onDrop={(e) => handleRootDrop(e, vault.id)}
                          >
                            {t('fileOps.dropToRoot')}
                          </div>
                        </li>
                      )}
                    </ul>
                  )}
                </li>
              )
            })}
          </ul>
        </nav>
        </>
      )}

      {/* Create Vault Form */}
      {showCreateVaultForm && (
        <div className="file-explorer-create-vault">
          <form className="file-explorer-create-vault-form" onSubmit={handleCreateVaultSubmit}>
            <input
              type="text"
              className="file-explorer-create-vault-input"
              placeholder={t('vault.vaultNamePlaceholder')}
              value={newVaultName}
              onChange={(e) => setNewVaultName(e.target.value)}
              maxLength={128}
              aria-label={t('vault.vaultNameLabel')}
              autoFocus
            />
            <div className="file-explorer-create-vault-actions">
              <button type="submit" className="file-explorer-create-vault-submit">OK</button>
              <button type="button" className="file-explorer-create-vault-cancel" onClick={() => setShowCreateVaultForm(false)}>├ù</button>
            </div>
            {vaultValidationError && (
              <p className="file-explorer-create-vault-error" role="alert">{vaultValidationError}</p>
            )}
          </form>
        </div>
      )}

      {/* Context Menu */}
      {contextMenuState.visible && contextMenuState.targetNode && (() => {
        const node = contextMenuState.targetNode!
        const permission = state.vaults.find((v) => v.id === contextMenuState.vaultId)?.permission ?? 'read'
        const isReadOnly = permission === 'read'
        const isRoot = node.path === ''
        const isFile = node.type === 'file'
        const isFolder = node.type === 'directory' && !isRoot

        let menuItems: ContextMenuItem[]

        if (isReadOnly) {
          // Read-only users: no write actions, show hint
          menuItems = [{ id: 'no-actions', label: t('contextMenu.noActions'), disabled: true }]
        } else if (isFile) {
          // File context menu: Umbenennen, L├Âschen, Kopieren, Verschieben, Favorit, Versionen
          const fileFavorited = contextMenuState.vaultId
            ? favoritesStore.isFavorite(contextMenuState.vaultId, node.path)
            : false
          menuItems = [
            {
              id: 'toggleFavorite',
              label: fileFavorited ? t('contextMenu.removeFavorite') : t('contextMenu.addFavorite'),
              icon: <Star size={14} />,
            },
            { id: 'separator-fav', label: '', separator: true },
            { id: 'rename', label: t('contextMenu.rename'), icon: <Pencil size={14} /> },
            { id: 'delete', label: t('contextMenu.delete'), icon: <Trash2 size={14} /> },
            { id: 'separator-1', label: '', separator: true },
            { id: 'copy', label: t('contextMenu.copy'), icon: <Copy size={14} /> },
            { id: 'move', label: t('contextMenu.move'), icon: <Move size={14} /> },
            { id: 'separator-2', label: '', separator: true },
            { id: 'versions', label: 'Versionen', icon: <History size={14} /> },
          ]
          menuItems = [...menuItems, ...buildPluginMenuItems(node)]
        } else if (isFolder) {
          // Folder context menu: Neuer Ordner, Neue Datei, Neues Canvas, Umbenennen, L├Âschen
          menuItems = [
            { id: 'newFolder', label: t('contextMenu.newFolder'), icon: <FolderPlus size={14} /> },
            { id: 'newFile', label: t('contextMenu.newFile'), icon: <FilePlus size={14} /> },
            { id: 'newCanvas', label: 'Neues Canvas', icon: <LayoutDashboard size={14} /> },
            { id: 'separator-1', label: '', separator: true },
            { id: 'rename', label: t('contextMenu.rename'), icon: <Pencil size={14} /> },
            { id: 'delete', label: t('contextMenu.delete'), icon: <Trash2 size={14} /> },
          ]
          menuItems = [...menuItems, ...buildPluginMenuItems(node)]
        } else {
          // Vault entry context menu: Neuer Ordner, Neue Datei, Neues Canvas, Neue Notiz aus Vorlage, Export
          menuItems = [
            { id: 'newFolder', label: t('contextMenu.newFolder'), icon: <FolderPlus size={14} /> },
            { id: 'newFile', label: t('contextMenu.newFile'), icon: <FilePlus size={14} /> },
            { id: 'newCanvas', label: 'Neues Canvas', icon: <LayoutDashboard size={14} /> },
            { id: 'newFromTemplate', label: 'Neue Notiz aus Vorlage', icon: <FileText size={14} /> },
            { id: 'separator-1', label: '', separator: true },
            { id: 'export', label: t('contextMenu.export'), icon: <Download size={14} /> },
          ]
        }

        return (
          <ContextMenu
            x={contextMenuState.x}
            y={contextMenuState.y}
            items={menuItems}
            onClose={handleCloseContextMenu}
            onSelect={handleMenuSelect}
          />
        )
      })()}

      {/* Delete Confirmation Modal */}
      <ConfirmModal
        open={deleteConfirm.open}
        title={t('fileOps.deleteConfirmTitle')}
        message={
          deleteConfirm.node?.type === 'directory'
            ? t('fileOps.deleteConfirmFolder', { name: deleteConfirm.node?.name ?? '' })
            : t('fileOps.deleteConfirmMessage', { name: deleteConfirm.node?.name ?? '' })
        }
        confirmLabel={t('common.delete')}
        variant="danger"
        onConfirm={handleDeleteConfirmed}
        onCancel={handleDeleteCancelled}
      />

      {/* Template Selector Modal */}
      {templateSelectorVaultId && apiClient && (
        <TemplateSelector
          isOpen={templateSelectorOpen}
          onClose={() => setTemplateSelectorOpen(false)}
          apiClient={apiClient}
          vaultId={templateSelectorVaultId}
          targetDir=""
          onFileCreated={handleTemplateFileCreated}
        />
      )}
    </div>
  )
}

import { useState, useEffect, type FormEvent } from 'react'
import { useAuthContext } from '../state/authContext'
import { useTranslation } from '../i18n'
import type { IApiClient } from '../api'
import { SlatebaseLogo } from './SlatebaseLogo'

/** Props for the LoginPage component. */
export interface LoginPageProps {
  apiClient: IApiClient
}

/**
 * Checks if an error represents a 429 rate-limit response.
 */
function isRateLimitError(err: unknown): boolean {
  if (err !== null && typeof err === 'object' && 'code' in err) {
    const code = (err as { code: string }).code
    return code === 'RATE_LIMITED' || code === 'TOO_MANY_REQUESTS'
  }
  return false
}

/**
 * Extracts the retry-after value (in seconds) from a rate-limit error.
 * Falls back to 900 seconds (15 minutes) if not available.
 */
function extractRetryAfter(err: unknown): number {
  if (err !== null && typeof err === 'object' && 'retryAfter' in err) {
    const retryAfter = (err as { retryAfter: unknown }).retryAfter
    if (typeof retryAfter === 'number' && retryAfter > 0) return retryAfter
  }
  if (err !== null && typeof err === 'object' && 'message' in err) {
    const message = (err as { message: string }).message
    const match = message.match(/(\d+)\s*(seconds?|Sekunden?)/)
    if (match?.[1]) return parseInt(match[1], 10)
  }
  return 900
}

/**
 * Login page with Slatebase logo and modern card design.
 */
export function LoginPage({ apiClient }: LoginPageProps) {
  const { authState, authDispatch } = useAuthContext()
  const { t } = useTranslation()
  const [username, setUsername] = useState('')
  const [password, setPassword] = useState('')
  const [usernameError, setUsernameError] = useState<string | null>(null)
  const [passwordError, setPasswordError] = useState<string | null>(null)
  const [rateLimitMessage, setRateLimitMessage] = useState<string | null>(null)
  const [version, setVersion] = useState<string | null>(null)

  useEffect(() => {
    const controller = new AbortController()
    apiClient.getVersion()
      .then((result) => {
        if (!controller.signal.aborted) {
          setVersion(result.version)
        }
      })
      .catch(() => {
        // Silently ignore ÔÇö version display is non-critical
      })
    return () => { controller.abort() }
  }, [apiClient])

  function validate(): boolean {
    let valid = true
    if (username.trim() === '') {
      setUsernameError(t('auth.usernameRequired'))
      valid = false
    } else {
      setUsernameError(null)
    }
    if (password === '') {
      setPasswordError(t('auth.passwordRequired'))
      valid = false
    } else {
      setPasswordError(null)
    }
    return valid
  }

  async function handleSubmit(e: FormEvent<HTMLFormElement>): Promise<void> {
    e.preventDefault()
    setRateLimitMessage(null)
    if (!validate()) return
    authDispatch({ type: 'LOGIN_STARTED' })
    try {
      const result = await apiClient.login(username, password)
      apiClient.setToken(result.token)
      apiClient.setCsrfToken(result.csrfToken)
      authDispatch({
        type: 'LOGIN_SUCCESS',
        payload: { token: result.token, csrfToken: result.csrfToken, user: result.user },
      })
    } catch (err: unknown) {
      if (isRateLimitError(err)) {
        const retryAfter = extractRetryAfter(err)
        const msg = t('auth.rateLimited', { seconds: retryAfter })
        setRateLimitMessage(msg)
        authDispatch({ type: 'LOGIN_FAILED', payload: { message: msg } })
      } else {
        authDispatch({
          type: 'LOGIN_FAILED',
          payload: { message: t('auth.loginFailed') },
        })
      }
    }
  }

  return (
    <div className="login-page">
      <div className="login-card">
        <div className="login-logo">
          <SlatebaseLogo size={36} className="login-logo-icon" />
          <span className="login-logo-text">Slatebase</span>
        </div>

        {authState.error === 'auth.sessionExpired' && (
          <div className="login-session-expired-banner" role="alert">
            {t('auth.sessionExpiredBanner')}
          </div>
        )}

        <form className="login-form" onSubmit={handleSubmit} noValidate>
          <div className="login-field">
            <label className="login-label" htmlFor="login-username">{t('auth.username')}</label>
            <input
              id="login-username"
              className="login-input"
              type="text"
              maxLength={128}
              value={username}
              onChange={(e) => { setUsername(e.target.value); if (usernameError) setUsernameError(null) }}
              aria-invalid={usernameError !== null}
              aria-describedby={usernameError ? 'login-username-error' : undefined}
              autoComplete="username"
              autoFocus
            />
            {usernameError && (
              <p id="login-username-error" className="login-field-error" role="alert">{usernameError}</p>
            )}
          </div>

          <div className="login-field">
            <label className="login-label" htmlFor="login-password">{t('auth.password')}</label>
            <input
              id="login-password"
              className="login-input"
              type="password"
              maxLength={256}
              value={password}
              onChange={(e) => { setPassword(e.target.value); if (passwordError) setPasswordError(null) }}
              aria-invalid={passwordError !== null}
              aria-describedby={passwordError ? 'login-password-error' : undefined}
              autoComplete="current-password"
            />
            {passwordError && (
              <p id="login-password-error" className="login-field-error" role="alert">{passwordError}</p>
            )}
          </div>

          {rateLimitMessage && (
            <p className="login-error login-error--rate-limit" role="alert">{rateLimitMessage}</p>
          )}
          {authState.error && !rateLimitMessage && authState.error !== 'auth.sessionExpired' && (
            <p className="login-error" role="alert">{
              authState.error.startsWith('auth.') ? t(authState.error as Parameters<typeof t>[0]) : authState.error
            }</p>
          )}

          <button type="submit" className="login-submit" disabled={authState.isLoading}>
            {authState.isLoading ? t('auth.loggingIn') : t('auth.login')}
          </button>
        </form>

        {version && (
          <p className="login-version">
            {version === 'development' ? 'dev' : `v${version}`}
          </p>
        )}
      </div>
    </div>
  )
}

import { useState, useEffect, useCallback, useRef, type FormEvent } from 'react'
import { useAppContext, loadVaults, deleteVault, exportVault } from '../state'
import { useTranslation } from '../i18n'
import type { IApiClient, UserSearchResult } from '../api'
import type { VaultInfo } from '../types'
import { Database, Eye, Pencil, Crown, Trash2, Users, RefreshCw, X, ArrowRightLeft, Download } from 'lucide-react'
import { ConfirmModal } from './ConfirmModal'
import { VaultDeletionWorkflow } from './VaultDeletionWorkflow'

interface ShareInfo {
  userId: string
  username?: string
  displayName?: string
  permission: 'read' | 'write'
}

interface MyVaultsPageProps {
  apiClient: IApiClient
}

/** Debounce delay for user search. */
const SEARCH_DEBOUNCE_MS = 300

/**
 * Vault overview page for normal users.
 * Shows owned vaults with inline share management, transfer, delete,
 * and shared vaults with owner and permission info.
 */
export function MyVaultsPage({ apiClient }: MyVaultsPageProps) {
  const { state, dispatch } = useAppContext()
  const { t } = useTranslation()
  const [sharesMap, setSharesMap] = useState<Map<string, ShareInfo[]>>(new Map())
  const [expandedVault, setExpandedVault] = useState<string | null>(null)
  const [transferVault, setTransferVault] = useState<string | null>(null)
  const [vaultStats, setVaultStats] = useState<Map<string, { fileCount: number; sizeBytes: number }>>(new Map())
  const [deleteConfirm, setDeleteConfirm] = useState<{ open: boolean; vault: VaultInfo | null }>({
    open: false, vault: null,
  })
  const [deletionWorkflow, setDeletionWorkflow] = useState<{ open: boolean; vaultId: string } | null>(null)

  const ownedVaults = state.vaults.filter((v) => v.permission === 'owner')
  const sharedVaults = state.vaults.filter((v) => v.permission === 'read' || v.permission === 'write')

  // Stable identity strings for dependency tracking (re-fire when vault list changes)
  const ownedVaultIds = ownedVaults.map((v) => v.id).join(',')
  const sharedVaultIds = sharedVaults.map((v) => v.id).join(',')

  /** Load shares for all owned vaults. */
  const loadAllShares = useCallback(async () => {
    if (ownedVaults.length === 0) { setSharesMap(new Map()); return }
    const map = new Map<string, ShareInfo[]>()
    const token = apiClient.getToken()
    const headers: Record<string, string> = {}
    if (token) headers['Authorization'] = `Bearer ${token}`

    await Promise.all(
      ownedVaults.map(async (vault) => {
        try {
          const res = await fetch(`/api/v1/vaults/${vault.id}/shares`, { headers })
          if (res.ok) {
            const data: ShareInfo[] = await res.json()
            map.set(vault.id, data)
          }
        } catch { /* ignore */ }
      }),
    )
    setSharesMap(map)
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [apiClient, ownedVaultIds])

  /** Load file count and size for all vaults. */
  const loadStats = useCallback(async () => {
    const allVaults = [...ownedVaults, ...sharedVaults]
    if (allVaults.length === 0) { setVaultStats(new Map()); return }
    const stats = new Map<string, { fileCount: number; sizeBytes: number }>()

    await Promise.all(
      allVaults.map(async (vault) => {
        try {
          const tree = await apiClient.fetchVaultTree(vault.id)
          let fileCount = 0
          let sizeBytes = 0
          function countFiles(node: { type: string; size?: number; children?: typeof node[] }): void {
            if (node.type === 'file') { fileCount++; sizeBytes += node.size ?? 0 }
            node.children?.forEach(countFiles)
          }
          countFiles(tree)
          stats.set(vault.id, { fileCount, sizeBytes })
        } catch { /* ignore */ }
      }),
    )
    setVaultStats(stats)
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [apiClient, ownedVaultIds, sharedVaultIds])

  useEffect(() => { void loadAllShares() }, [loadAllShares]) // eslint-disable-line react-hooks/set-state-in-effect
  useEffect(() => { void loadStats() }, [loadStats]) // eslint-disable-line react-hooks/set-state-in-effect

  async function handleDelete(vault: VaultInfo): Promise<void> {
    const shares = sharesMap.get(vault.id) ?? []
    if (shares.length > 0) {
      // Vault has shares ÔÇö open the guided deletion workflow
      setDeletionWorkflow({ open: true, vaultId: vault.id })
    } else {
      // No shares ÔÇö simple confirmation
      setDeleteConfirm({ open: true, vault })
    }
  }

  async function handleDeleteConfirmed(): Promise<void> {
    const vault = deleteConfirm.vault
    setDeleteConfirm({ open: false, vault: null })
    if (!vault) return
    await deleteVault(dispatch, apiClient, vault.id)
  }

  function handleDeletionWorkflowComplete(): void {
    setDeletionWorkflow(null)
    void loadVaults(dispatch, apiClient)
    void loadAllShares()
  }

  function handleRefresh(): void {
    void loadVaults(dispatch, apiClient)
  }

  async function handleRevokeShare(vaultId: string, userId: string): Promise<void> {
    const token = apiClient.getToken()
    const csrf = apiClient.getCsrfToken()
    const headers: Record<string, string> = {}
    if (token) headers['Authorization'] = `Bearer ${token}`
    if (csrf) headers['X-CSRF-Token'] = csrf
    try {
      await fetch(`/api/v1/vaults/${vaultId}/shares/${userId}`, { method: 'DELETE', headers })
      await loadAllShares()
    } catch { /* ignore */ }
  }

  async function handleChangePermission(vaultId: string, userId: string, newPermission: 'read' | 'write'): Promise<void> {
    const token = apiClient.getToken()
    const csrf = apiClient.getCsrfToken()
    const headers: Record<string, string> = { 'Content-Type': 'application/json' }
    if (token) headers['Authorization'] = `Bearer ${token}`
    if (csrf) headers['X-CSRF-Token'] = csrf
    try {
      await fetch(`/api/v1/vaults/${vaultId}/shares/${userId}`, {
        method: 'PUT', headers, body: JSON.stringify({ permission: newPermission }),
      })
      await loadAllShares()
    } catch { /* ignore */ }
  }

  async function handleTransfer(vaultId: string, newOwnerId: string): Promise<void> {
    const token = apiClient.getToken()
    const csrf = apiClient.getCsrfToken()
    const headers: Record<string, string> = { 'Content-Type': 'application/json' }
    if (token) headers['Authorization'] = `Bearer ${token}`
    if (csrf) headers['X-CSRF-Token'] = csrf

    try {
      const res = await fetch(`/api/v1/vaults/${vaultId}/transfer`, {
        method: 'POST', headers, body: JSON.stringify({ newOwnerId }),
      })
      if (!res.ok) {
        const body = await res.json().catch(() => ({ message: 'Fehler' }))
        throw new Error((body as { message?: string }).message ?? `HTTP ${res.status}`)
      }
      void loadVaults(dispatch, apiClient)
    } catch (err: unknown) {
      throw err instanceof Error ? err : new Error(String(err))
    }
  }

  function formatBytes(bytes: number): string {
    if (bytes < 1024) return `${bytes} B`
    if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`
    return `${(bytes / (1024 * 1024)).toFixed(1)} MB`
  }

  return (
    <div className="my-vaults-page">
      <div className="my-vaults-header">
        <Database size={22} color="var(--accent-text)" />
        <h1 className="my-vaults-title">Meine Vaults</h1>
        <button
          className="admin-users-btn admin-users-btn--small"
          onClick={handleRefresh}
          style={{ marginLeft: 'auto' }}
        >
          <RefreshCw size={13} /> Aktualisieren
        </button>
      </div>

      {/* Owned vaults section */}
      <section className="my-vaults-section">
        <h2 className="my-vaults-section-title">
          <Crown size={14} /> Eigene Vaults ({ownedVaults.length})
        </h2>
        {ownedVaults.length === 0 ? (
          <p className="my-vaults-empty">Keine eigenen Vaults vorhanden.</p>
        ) : (
          <ul className="my-vaults-list">
            {ownedVaults.map((vault) => {
              const shares = sharesMap.get(vault.id) ?? []
              const stats = vaultStats.get(vault.id)
              const isExpanded = expandedVault === vault.id
              return (
                <li key={vault.id} className="my-vaults-item my-vaults-item--detailed">
                  <div className="my-vaults-item-main">
                    <Database size={14} className="my-vaults-item-icon" />
                    <span className="my-vaults-item-name">{vault.name}</span>
                    {stats && (
                      <span className="my-vaults-item-stats">
                        {stats.fileCount} Dateien ┬À {formatBytes(stats.sizeBytes)}
                      </span>
                    )}
                    <button
                      className="my-vaults-share-btn"
                      onClick={() => setExpandedVault(isExpanded ? null : vault.id)}
                      title="Freigaben verwalten"
                      aria-label={`Freigaben f├╝r "${vault.name}" verwalten`}
                    >
                      <Users size={12} />
                      {shares.length > 0 && <span className="my-vaults-share-count">{shares.length}</span>}
                    </button>
                    <button
                      className="my-vaults-action-btn"
                      onClick={() => void exportVault(dispatch, apiClient, vault.id, vault.name)}
                      title="Vault exportieren"
                      aria-label={`Vault "${vault.name}" exportieren`}
                    >
                      <Download size={12} />
                    </button>
                    <button
                      className={`my-vaults-action-btn${transferVault === vault.id ? ' my-vaults-action-btn--active' : ''}`}
                      onClick={() => setTransferVault(transferVault === vault.id ? null : vault.id)}
                      title="Besitz ├╝bertragen"
                      aria-label={`Vault "${vault.name}" ├╝bertragen`}
                    >
                      <ArrowRightLeft size={12} />
                    </button>
                    <button
                      className="my-vaults-delete-btn"
                      onClick={() => void handleDelete(vault)}
                      title={`"${vault.name}" l├Âschen`}
                      aria-label={`Vault "${vault.name}" l├Âschen`}
                    >
                      <Trash2 size={12} />
                    </button>
                  </div>

                  {/* Inline share management */}
                  {isExpanded && (
                    <div className="my-vaults-sharing-panel">
                      {shares.length > 0 && (
                        <div className="my-vaults-sharing-list">
                          {shares.map((s) => (
                            <div key={s.userId} className="my-vaults-sharing-entry">
                              <span className="my-vaults-sharing-user">{s.username ?? s.userId}</span>
                              <select
                                className="my-vaults-sharing-perm-select"
                                value={s.permission}
                                onChange={(e) => void handleChangePermission(vault.id, s.userId, e.target.value as 'read' | 'write')}
                                aria-label={`Berechtigung f├╝r ${s.username ?? s.userId}`}
                              >
                                <option value="read">Lesen</option>
                                <option value="write">Schreiben</option>
                              </select>
                              <button
                                className="my-vaults-sharing-revoke"
                                onClick={() => void handleRevokeShare(vault.id, s.userId)}
                                title="Freigabe widerrufen"
                                aria-label={`Freigabe f├╝r ${s.username ?? s.userId} widerrufen`}
                              >
                                <X size={12} />
                              </button>
                            </div>
                          ))}
                        </div>
                      )}
                      {shares.length === 0 && (
                        <p className="my-vaults-sharing-empty">Noch nicht geteilt.</p>
                      )}
                      <AddShareForm
                        apiClient={apiClient}
                        vaultId={vault.id}
                        onShareAdded={loadAllShares}
                      />
                    </div>
                  )}

                  {/* Inline transfer form */}
                  {transferVault === vault.id && (
                    <TransferForm
                      apiClient={apiClient}
                      vaultId={vault.id}
                      vaultName={vault.name}
                      onTransferred={() => { setTransferVault(null); void loadVaults(dispatch, apiClient) }}
                      onCancel={() => setTransferVault(null)}
                      onTransfer={handleTransfer}
                    />
                  )}
                </li>
              )
            })}
          </ul>
        )}
      </section>

      {/* Shared vaults section */}
      <section className="my-vaults-section">
        <h2 className="my-vaults-section-title">
          Mit mir geteilt ({sharedVaults.length})
        </h2>
        {sharedVaults.length === 0 ? (
          <p className="my-vaults-empty">Keine geteilten Vaults vorhanden.</p>
        ) : (
          <ul className="my-vaults-list">
            {sharedVaults.map((vault) => {
              const stats = vaultStats.get(vault.id)
              return (
                <li key={vault.id} className="my-vaults-item my-vaults-item--detailed">
                  <div className="my-vaults-item-main">
                    <Database size={14} className="my-vaults-item-icon" />
                    <span className="my-vaults-item-name">{vault.name}</span>
                    {stats && (
                      <span className="my-vaults-item-stats">
                        {stats.fileCount} Dateien ┬À {formatBytes(stats.sizeBytes)}
                      </span>
                    )}
                    {vault.permission === 'read' ? (
                      <span className="my-vaults-badge my-vaults-badge--read">
                        <Eye size={11} /> Nur Lesen
                      </span>
                    ) : (
                      <span className="my-vaults-badge my-vaults-badge--write">
                        <Pencil size={11} /> Bearbeiten
                      </span>
                    )}
                  </div>
                  <div className="my-vaults-item-owner">
                    Besitzer: <strong>{vault.ownerName ?? vault.ownerId ?? 'ÔÇö'}</strong>
                  </div>
                </li>
              )
            })}
          </ul>
        )}
      </section>

      {/* Delete Confirmation Modal (only for vaults without shares) */}
      <ConfirmModal
        open={deleteConfirm.open}
        title={t('vault.deleteVault')}
        message={deleteConfirm.vault ? t('vault.deleteConfirm', { name: deleteConfirm.vault.name }) : ''}
        confirmLabel={t('common.delete')}
        variant="danger"
        onConfirm={handleDeleteConfirmed}
        onCancel={() => setDeleteConfirm({ open: false, vault: null })}
      />

      {/* Vault Deletion Workflow (shown when vault has active shares) */}
      {deletionWorkflow?.open && (
        <div className="vault-deletion-workflow-overlay">
          <div className="vault-deletion-workflow-modal">
            <VaultDeletionWorkflow
              apiClient={apiClient}
              vaultId={deletionWorkflow.vaultId}
              onComplete={handleDeletionWorkflowComplete}
            />
          </div>
        </div>
      )}
    </div>
  )
}

// ÔöÇÔöÇÔöÇ Inline Add Share Form ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

interface AddShareFormProps {
  apiClient: IApiClient
  vaultId: string
  onShareAdded: () => Promise<void>
}

function AddShareForm({ apiClient, vaultId, onShareAdded }: AddShareFormProps) {
  const [username, setUsername] = useState('')
  const [selectedUserId, setSelectedUserId] = useState<string | null>(null)
  const [permission, setPermission] = useState<'read' | 'write'>('read')
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [suggestions, setSuggestions] = useState<UserSearchResult[]>([])
  const [showSuggestions, setShowSuggestions] = useState(false)
  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null)

  useEffect(() => {
    return () => { if (debounceRef.current) clearTimeout(debounceRef.current) }
  }, [])

  function handleUsernameChange(value: string): void {
    setUsername(value)
    setSelectedUserId(null)
    if (error) setError(null)

    if (debounceRef.current) clearTimeout(debounceRef.current)
    debounceRef.current = setTimeout(() => {
      if (value.trim().length === 0) { setSuggestions([]); setShowSuggestions(false); return }
      void apiClient.searchUsers(value.trim()).then((results) => {
        setSuggestions(results)
        setShowSuggestions(results.length > 0)
      }).catch(() => { setSuggestions([]); setShowSuggestions(false) })
    }, SEARCH_DEBOUNCE_MS)
  }

  function selectSuggestion(user: UserSearchResult): void {
    setUsername(user.username)
    setSelectedUserId(user.userId)
    setSuggestions([])
    setShowSuggestions(false)
  }

  async function handleSubmit(e: FormEvent): Promise<void> {
    e.preventDefault()
    setError(null)
    setShowSuggestions(false)

    const trimmed = username.trim()
    if (trimmed === '') { setError('Benutzername eingeben.'); return }

    const targetId = selectedUserId ?? trimmed
    setLoading(true)

    try {
      const token = apiClient.getToken()
      const csrf = apiClient.getCsrfToken()
      const headers: Record<string, string> = { 'Content-Type': 'application/json' }
      if (token) headers['Authorization'] = `Bearer ${token}`
      if (csrf) headers['X-CSRF-Token'] = csrf

      const res = await fetch(`/api/v1/vaults/${vaultId}/shares`, {
        method: 'POST', headers, body: JSON.stringify({ userId: targetId, permission }),
      })

      if (!res.ok) {
        const body = await res.json().catch(() => ({ message: 'Fehler' }))
        throw new Error(body.message ?? `HTTP ${res.status}`)
      }

      setUsername('')
      setSelectedUserId(null)
      setPermission('read')
      await onShareAdded()
    } catch (err: unknown) {
      setError(err instanceof Error ? err.message : 'Fehler beim Hinzuf├╝gen')
    } finally {
      setLoading(false)
    }
  }

  return (
    <form className="my-vaults-add-share" onSubmit={handleSubmit} noValidate>
      <div className="my-vaults-add-share-row">
        <div className="my-vaults-add-share-input-wrap">
          <input
            type="text"
            className="my-vaults-add-share-input"
            value={username}
            onChange={(e) => handleUsernameChange(e.target.value)}
            onFocus={() => { if (suggestions.length > 0 && !selectedUserId) setShowSuggestions(true) }}
            onBlur={() => setTimeout(() => setShowSuggestions(false), 150)}
            placeholder="Benutzer hinzuf├╝genÔÇª"
            autoComplete="off"
            aria-label="Benutzername f├╝r Freigabe"
          />
          {showSuggestions && suggestions.length > 0 && (
            <ul className="my-vaults-add-share-suggestions">
              {suggestions.map((user) => (
                <li
                  key={user.userId}
                  className="my-vaults-add-share-suggestion"
                  onMouseDown={(e) => { e.preventDefault(); selectSuggestion(user) }}
                >
                  <span>{user.username}</span>
                  {user.displayName && user.displayName !== user.username && (
                    <span className="my-vaults-add-share-suggestion-name">{user.displayName}</span>
                  )}
                </li>
              ))}
            </ul>
          )}
        </div>
        <select
          className="my-vaults-add-share-perm"
          value={permission}
          onChange={(e) => setPermission(e.target.value as 'read' | 'write')}
          aria-label="Berechtigung"
        >
          <option value="read">Lesen</option>
          <option value="write">Schreiben</option>
        </select>
        <button type="submit" className="my-vaults-add-share-btn" disabled={loading}>
          {loading ? 'ÔÇª' : '+'}
        </button>
      </div>
      {error && <p className="my-vaults-add-share-error">{error}</p>}
    </form>
  )
}

// ÔöÇÔöÇÔöÇ Inline Transfer Form ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

