/** Tab for plugin management page */
type PluginTab = 'installed' | 'available'

/** Plugin status types */
type PluginStatus = 'active' | 'inactive' | 'error' | 'loading'

/** Compatibility levels */
type CompatibilityLevel = 'full' | 'partial' | 'unsupported' | 'unknown'

/** Merged plugin data for display */
interface PluginDisplayItem {
  pluginId: string
  name: string
  version: string
  author: string
  description: string
  status: PluginStatus
  compatibilityLevel: CompatibilityLevel
  compatibilityReasons: string[]
  compatibilityApiCalls: ApiCallClassification[]
  error?: string
  hasSettings: boolean
  hasEvalUsage: boolean
}

/** Props for the PluginManagementPage component. */
export interface PluginManagementPageProps {
  /** API client instance for making authenticated requests. */
  apiClient: IApiClient
  /** Current vault ID to manage plugins for. */
  vaultId: string
}

// ÔöÇÔöÇÔöÇ Component ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

/**
 * Plugin management page displaying installed plugins with controls for
 * activation/deactivation, settings, and compatibility details.
 */
export function PluginManagementPage({ apiClient, vaultId }: PluginManagementPageProps) {
  const { t } = useTranslation()
  const [activeTab, setActiveTab] = useState<PluginTab>('installed')
  const [plugins, setPlugins] = useState<PluginDisplayItem[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [expandedPlugin, setExpandedPlugin] = useState<string | null>(null)
  const [togglingPlugins, setTogglingPlugins] = useState<Set<string>>(new Set())
  const [reloadingPlugins, setReloadingPlugins] = useState<Set<string>>(new Set())
  const [registryData, setRegistryData] = useState<PluginRegistryData | null>(null)
  const [settingsModal, setSettingsModal] = useState<{ pluginId: string; pluginName: string } | null>(null)
  const [settingsJson, setSettingsJson] = useState('')
  const [settingsSaving, setSettingsSaving] = useState(false)
  const [settingsError, setSettingsError] = useState<string | null>(null)
  const [settingsLoading, setSettingsLoading] = useState(false)
  const [deleteConfirm, setDeleteConfirm] = useState<{ pluginId: string; pluginName: string } | null>(null)
  const [deletingPlugins, setDeletingPlugins] = useState<Set<string>>(new Set())
  const [evalWarningConfirm, setEvalWarningConfirm] = useState<{ pluginId: string; pluginName: string } | null>(null)
  const [updateCount, setUpdateCount] = useState<number>(0)
  const [checkingUpdates, setCheckingUpdates] = useState(false)
  const [updateInfo, setUpdateInfo] = useState<Map<string, { latestVersion: string; repo: string }>>(new Map())
  const [hasCheckedUpdates, setHasCheckedUpdates] = useState(false)
  const [updatingPlugins, setUpdatingPlugins] = useState<Set<string>>(new Set())
  const [isUpdatingAll, setIsUpdatingAll] = useState(false)

  const analyzerRef = useRef(new CompatibilityAnalyzer())
  const settingsContainerRef = useRef<HTMLDivElement>(null)
  const pluginContext = useContext(PluginContext)

  // ÔöÇÔöÇÔöÇ Background: Analyze compatibility + detect settings ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

  /**
   * Fetches bundles for all plugins, runs compatibility analysis, and checks
   * if settings exist. Updates both the display list and the persisted registry.
   */
  const analyzeAndDetectSettings = useCallback(async (
    manifests: PluginManifest[],
    _registry: PluginRegistryData | null,
  ): Promise<void> => {
    const updates: Array<{
      pluginId: string
      compatibilityLevel?: CompatibilityLevel
      compatibilityReasons?: string[]
      compatibilityApiCalls?: ApiCallClassification[]
      hasSettings?: boolean
    }> = []

    await Promise.all(manifests.map(async (manifest) => {
      const update: {
        pluginId: string
        compatibilityLevel?: CompatibilityLevel
        compatibilityReasons?: string[]
        compatibilityApiCalls?: ApiCallClassification[]
        hasSettings?: boolean
      } = {
        pluginId: manifest.id,
      }

      // 1. Compatibility analysis (always run to populate reasons/apiCalls)
      try {
        const bundle = await apiClient.loadBundle(vaultId, manifest.id)
        const report = analyzerRef.current.analyze(bundle, manifest)
        update.compatibilityLevel = report.level
        update.compatibilityReasons = report.reasons
        update.compatibilityApiCalls = report.apiCalls
      } catch {
        // Bundle load failed ÔÇö leave as unknown
      }

      // 2. Settings: always available for installed plugins
      // Plugins can always be configured (empty {} if no data.json exists yet)
      update.hasSettings = true

      updates.push(update)
    }))

    // Apply updates to display list
    if (updates.length > 0) {
      setPlugins(prev => prev.map(p => {
        const upd = updates.find(u => u.pluginId === p.pluginId)
        if (!upd) return p
        return {
          ...p,
          compatibilityLevel: upd.compatibilityLevel ?? p.compatibilityLevel,
          compatibilityReasons: upd.compatibilityReasons ?? p.compatibilityReasons,
          compatibilityApiCalls: upd.compatibilityApiCalls ?? p.compatibilityApiCalls,
          hasSettings: upd.hasSettings ?? p.hasSettings,
        }
      }))

      // Compatibility analysis is display-only. Persisting a full registry
      // snapshot here can overwrite newer activation state from the loader.
    }
  }, [apiClient, vaultId])

  // ÔöÇÔöÇÔöÇ Load plugins ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

  const loadPlugins = useCallback(async () => {
    setLoading(true)
    setError(null)
    try {
      const [manifestsResult, registry] = await Promise.all([
        apiClient.listPlugins(vaultId),
        apiClient.loadRegistry(vaultId).catch(() => null),
      ])

      const manifests: PluginManifest[] = manifestsResult.plugins ?? []
      setRegistryData(registry)

      const merged: PluginDisplayItem[] = manifests.map((manifest) => {
        const regEntry = registry?.plugins?.[manifest.id]
        return {
          pluginId: manifest.id,
          name: manifest.name,
          version: manifest.version,
          author: manifest.author ?? 'Unbekannt',
          description: manifest.description ?? '',
          status: regEntry?.status === 'loading'
            ? 'active'
            : (regEntry?.status as PluginStatus) ?? 'inactive',
          compatibilityLevel: (regEntry?.compatibilityLevel as CompatibilityLevel) ?? 'unknown',
          compatibilityReasons: [],
          compatibilityApiCalls: [],
          error: regEntry?.error,
          hasSettings: true, // All installed plugins can be configured
          hasEvalUsage: regEntry?.hasEvalUsage === true,
        }
      })

      setPlugins(merged)

      // Background: Analyze compatibility and detect settings for each plugin
      void analyzeAndDetectSettings(manifests, registry)
    } catch (err: unknown) {
      setError(extractErrorMessage(err, 'Fehler beim Laden der Plugins'))
    } finally {
      setLoading(false)
    }
  }, [apiClient, vaultId, analyzeAndDetectSettings])

  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    void loadPlugins()
  }, [loadPlugins])

  // Check for available updates on mount (for badge on "Verf├╝gbare Plugins" tab)
  useEffect(() => {
    void (async () => {
      try {
        const result = await apiClient.checkPluginUpdates(vaultId)
        const count = result.plugins.filter(p => p.hasUpdate).length
        setUpdateCount(count)
      } catch {
        // Non-critical: update check failure doesn't affect page functionality
      }
    })()
  }, [apiClient, vaultId])

  // ÔöÇÔöÇÔöÇ Check for updates handler ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

  const handleCheckUpdates = async () => {
    setCheckingUpdates(true)
    try {
      const result = await apiClient.checkPluginUpdates(vaultId)
      const map = new Map<string, { latestVersion: string; repo: string }>()
      let count = 0
      for (const info of result.plugins) {
        if (info.hasUpdate) {
          map.set(info.pluginId, { latestVersion: info.latestVersion, repo: info.repo })
          count++
        }
      }
      setUpdateInfo(map)
      setUpdateCount(count)
      setHasCheckedUpdates(true)
    } catch {
      // Silently fail
    } finally {
      setCheckingUpdates(false)
    }
  }

  // ÔöÇÔöÇÔöÇ Update single plugin handler ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

  async function handleUpdatePlugin(pluginId: string): Promise<void> {
    setUpdatingPlugins(prev => new Set(prev).add(pluginId))
    try {
      await apiClient.updatePlugin(vaultId, pluginId)
      // Remove from updateInfo after successful update
      setUpdateInfo(prev => {
        const next = new Map(prev)
        next.delete(pluginId)
        return next
      })
      setUpdateCount(prev => Math.max(0, prev - 1))
      // Reload plugins to show new version
      void loadPlugins()
    } catch (err: unknown) {
      setError(extractErrorMessage(err, t('pluginStore.update') + ' fehlgeschlagen'))
    } finally {
      setUpdatingPlugins(prev => {
        const next = new Set(prev)
        next.delete(pluginId)
        return next
      })
    }
  }

  // ÔöÇÔöÇÔöÇ Update all plugins handler ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

  async function handleUpdateAllInstalled(): Promise<void> {
    setIsUpdatingAll(true)
    try {
      await apiClient.updateAllPlugins(vaultId)
      setUpdateInfo(new Map())
      setUpdateCount(0)
      // Reload to reflect new versions
      void loadPlugins()
    } catch (err: unknown) {
      setError(extractErrorMessage(err, t('pluginStore.updateAll') + ' fehlgeschlagen'))
    } finally {
      setIsUpdatingAll(false)
    }
  }

  // ÔöÇÔöÇÔöÇ Settings modal handlers ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

  async function openSettings(pluginId: string, pluginName: string): Promise<void> {
    setSettingsModal({ pluginId, pluginName })
    setSettingsError(null)
    setSettingsLoading(true)

    // Check if the plugin has a native settings tab registered
    const settingTab = pluginContext?.settingTabRegistry.get(pluginId)
    if (settingTab) {
      // Native settings: try declarative definitions first, then fall back to display()
      try {
        settingTab.containerEl.innerHTML = ''

        // Check for declarative settings (Obsidian 1.13+)
        const defs = (settingTab as unknown as { getSettingDefinitions?: () => unknown[] }).getSettingDefinitions?.()
        if (defs && Array.isArray(defs) && defs.length > 0) {
          // Use declarative renderer
          const { renderSettingDefinitions } = await import('../plugins/compat/declarative-settings-renderer')
          renderSettingDefinitions(
            defs as import('../plugins/compat/declarative-settings-renderer').SettingDefinitionItem[],
            settingTab.containerEl,
            settingTab as import('../plugins/compat/declarative-settings-renderer').IDeclarativeSettingTab,
          )
        } else {
          // Classic imperative display()
          settingTab.display()
        }
      } catch (err) {
        console.error(`[PluginSettings] Error rendering settings for "${pluginId}":`, err)
        const detail = extractErrorMessage(err, 'Unbekannter Fehler')
        // If the error is about uninitialized state (common during async plugin startup),
        // show a retry-friendly message instead of a permanent error
        if (detail.includes('not ready') || detail.includes('not initialized') || detail.includes('not ready yet')) {
          setSettingsError(`Plugin wird noch initialisiert. Bitte in wenigen Sekunden erneut versuchen.`)
        } else {
          setSettingsError(`Plugin-Einstellungen konnten nicht gerendert werden: ${detail}`)
        }
      }
      setSettingsLoading(false)
      // Mount containerEl in the next render via ref
      requestAnimationFrame(() => {
        if (settingsContainerRef.current && settingTab.containerEl) {
          settingsContainerRef.current.innerHTML = ''
          settingsContainerRef.current.appendChild(settingTab.containerEl)
        }
      })
      return
    }

    // Fallback: JSON editor
    try {
      const data = await apiClient.loadSettings(vaultId, pluginId)
      setSettingsJson(data !== null && data !== undefined ? JSON.stringify(data, null, 2) : '{}')
    } catch {
      setSettingsJson('{}')
      setSettingsError('Einstellungen konnten nicht geladen werden.')
    } finally {
      setSettingsLoading(false)
    }
  }

  async function saveSettings(): Promise<void> {
    if (!settingsModal) return
    setSettingsSaving(true)
    setSettingsError(null)
    try {
      const parsed = JSON.parse(settingsJson)
      await apiClient.saveSettings(vaultId, settingsModal.pluginId, parsed)
      setSettingsModal(null)
    } catch (err: unknown) {
      if (err instanceof SyntaxError) {
        setSettingsError('Ung├╝ltiges JSON-Format.')
      } else {
        setSettingsError(extractErrorMessage(err, 'Speichern fehlgeschlagen.'))
      }
    } finally {
      setSettingsSaving(false)
    }
  }

  // ÔöÇÔöÇÔöÇ Toggle activation ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

  async function handleToggle(pluginId: string): Promise<void> {
    if (togglingPlugins.has(pluginId)) return

    const plugin = plugins.find((p) => p.pluginId === pluginId)
    if (!plugin) return

    const newStatus: PluginStatus = plugin.status === 'active' ? 'inactive' : 'active'

    // Show eval usage warning before activation (not deactivation)
    if (newStatus === 'active' && plugin.hasEvalUsage) {
      setEvalWarningConfirm({ pluginId, pluginName: plugin.name })
      return
    }

    await performToggle(pluginId, plugin, newStatus)
  }

  /** Performs the actual toggle after any confirmation. */
  async function performToggle(pluginId: string, plugin: PluginDisplayItem, newStatus: PluginStatus): Promise<void> {

    // Optimistic update
    setPlugins((prev) => prev.map((p) =>
      p.pluginId === pluginId ? { ...p, status: newStatus, error: undefined } : p
    ))
    setTogglingPlugins((prev) => new Set([...prev, pluginId]))

    try {
      if (pluginContext) {
        await pluginContext.setPluginEnabled(pluginId, newStatus === 'active')
        setRegistryData(await apiClient.loadRegistry(vaultId))
      } else {
        // Fallback for isolated rendering without PluginProvider.
        const currentRegistry = registryData ?? { version: 1 as const, plugins: {} }
        const updatedRegistry: PluginRegistryData = {
          ...currentRegistry,
          plugins: {
            ...currentRegistry.plugins,
            [pluginId]: {
              ...currentRegistry.plugins[pluginId],
              status: newStatus,
              permissions: currentRegistry.plugins[pluginId]?.permissions ?? {
                network: false,
                networkAllowlist: [],
                filesystemWrite: false,
                domManipulation: false,
              },
              compatibilityLevel: currentRegistry.plugins[pluginId]?.compatibilityLevel ?? 'unknown',
              installedAt: currentRegistry.plugins[pluginId]?.installedAt ?? new Date().toISOString(),
              updatedAt: new Date().toISOString(),
            },
          },
        }
        if (newStatus === 'active' && updatedRegistry.plugins[pluginId]) {
          delete updatedRegistry.plugins[pluginId]!.error
        }
        await apiClient.saveRegistry(vaultId, updatedRegistry)
        setRegistryData(updatedRegistry)
      }
    } catch {
      // Rollback on failure
      setPlugins((prev) => prev.map((p) =>
        p.pluginId === pluginId ? { ...p, status: plugin.status, error: plugin.error } : p
      ))
    } finally {
      setTogglingPlugins((prev) => {
        const next = new Set(prev)
        next.delete(pluginId)
        return next
      })
    }
  }

  /** Confirms activation of a plugin with eval usage after user acknowledged the warning. */
  function handleEvalWarningConfirm(): void {
    if (!evalWarningConfirm) return
    const plugin = plugins.find((p) => p.pluginId === evalWarningConfirm.pluginId)
    if (!plugin) {
      setEvalWarningConfirm(null)
      return
    }
    setEvalWarningConfirm(null)
    void performToggle(evalWarningConfirm.pluginId, plugin, 'active')
  }

  // ÔöÇÔöÇÔöÇ Reload plugin ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

  async function handleReload(pluginId: string): Promise<void> {
    if (reloadingPlugins.has(pluginId)) return

    setReloadingPlugins((prev) => new Set([...prev, pluginId]))
    setPlugins((prev) => prev.map((p) =>
      p.pluginId === pluginId ? { ...p, status: 'loading' as PluginStatus, error: undefined } : p
    ))

    try {
      if (pluginContext) {
        await pluginContext.setPluginEnabled(pluginId, false)
        await pluginContext.setPluginEnabled(pluginId, true)
        setRegistryData(await apiClient.loadRegistry(vaultId))
      } else {
        const currentRegistry = registryData ?? { version: 1 as const, plugins: {} }
        const updatedRegistry: PluginRegistryData = {
          ...currentRegistry,
          plugins: {
            ...currentRegistry.plugins,
            [pluginId]: {
              ...currentRegistry.plugins[pluginId],
              status: 'active',
              permissions: currentRegistry.plugins[pluginId]?.permissions ?? {
                network: false,
                networkAllowlist: [],
                filesystemWrite: false,
                domManipulation: false,
              },
              compatibilityLevel: currentRegistry.plugins[pluginId]?.compatibilityLevel ?? 'unknown',
              installedAt: currentRegistry.plugins[pluginId]?.installedAt ?? new Date().toISOString(),
              updatedAt: new Date().toISOString(),
            },
          },
        }
        delete updatedRegistry.plugins[pluginId]!.error
        await apiClient.saveRegistry(vaultId, updatedRegistry)
        setRegistryData(updatedRegistry)
      }
      setPlugins((prev) => prev.map((p) =>
        p.pluginId === pluginId ? { ...p, status: 'active', error: undefined } : p
      ))
    } catch (err: unknown) {
      const detail = extractErrorMessage(err, 'Neu laden fehlgeschlagen')
      setPlugins((prev) => prev.map((p) =>
        p.pluginId === pluginId ? { ...p, status: 'error', error: `Neu laden fehlgeschlagen: ${detail}` } : p
      ))
    } finally {
      setReloadingPlugins((prev) => {
        const next = new Set(prev)
        next.delete(pluginId)
        return next
      })
    }
  }

  // ÔöÇÔöÇÔöÇ Delete plugin ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

  async function handleDelete(pluginId: string): Promise<void> {
    if (deletingPlugins.has(pluginId)) return

    setDeletingPlugins((prev) => new Set([...prev, pluginId]))

    try {
      // Deactivate first to clean up runtime registrations (icons, commands, views)
      if (pluginContext) {
        await pluginContext.setPluginEnabled(pluginId, false)
      }

      await apiClient.deletePlugin(vaultId, pluginId)

      // Remove from registry
      if (registryData) {
        const updatedRegistry: PluginRegistryData = {
          ...registryData,
          plugins: { ...registryData.plugins },
        }
        delete updatedRegistry.plugins[pluginId]
        await apiClient.saveRegistry(vaultId, updatedRegistry).catch(() => { /* non-critical */ })
        setRegistryData(updatedRegistry)
      }

      // Remove from display list
      setPlugins((prev) => prev.filter((p) => p.pluginId !== pluginId))
    } catch (err: unknown) {
      setError(extractErrorMessage(err, 'Deinstallation fehlgeschlagen.'))
    } finally {
      setDeletingPlugins((prev) => {
        const next = new Set(prev)
        next.delete(pluginId)
        return next
      })
      setDeleteConfirm(null)
    }
  }

  // ÔöÇÔöÇÔöÇ Compatibility level helpers ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

  function getCompatibilityIcon(level: CompatibilityLevel) {
    switch (level) {
      case 'full': return <CheckCircle2 size={14} className="plugin-compat-icon plugin-compat-icon--full" />
      case 'partial': return <AlertCircle size={14} className="plugin-compat-icon plugin-compat-icon--partial" />
      case 'unsupported': return <XCircle size={14} className="plugin-compat-icon plugin-compat-icon--unsupported" />
      case 'unknown': return <HelpCircle size={14} className="plugin-compat-icon plugin-compat-icon--unknown" />
    }
  }

  function getCompatibilityLabel(level: CompatibilityLevel): string {
    switch (level) {
      case 'full': return 'Voll kompatibel'
      case 'partial': return 'Teilweise kompatibel'
      case 'unsupported': return 'Nicht unterst├╝tzt'
      case 'unknown': return 'Unbekannt'
    }
  }

  function getStatusLabel(status: PluginStatus): string {
    switch (status) {
      case 'active': return 'Aktiv'
      case 'inactive': return 'Inaktiv'
      case 'error': return 'Fehler'
      case 'loading': return 'LadenÔÇª'
    }
  }

  // ÔöÇÔöÇÔöÇ Render ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

  // Tab bar component (reused across states)
  const tabBar = (
    <div className="plugin-management-tabs">
      <button
        className={`plugin-management-tab ${activeTab === 'installed' ? 'plugin-management-tab--active' : ''}`}
        onClick={() => setActiveTab('installed')}
      >
        {t('pluginStore.tabInstalled')}
      </button>
      <button
        className={`plugin-management-tab ${activeTab === 'available' ? 'plugin-management-tab--active' : ''}`}
        onClick={() => setActiveTab('available')}
      >
        {t('pluginStore.tabAvailable')}{updateCount > 0 && <span className="plugin-management-tab__badge">{updateCount}</span>}
      </button>
    </div>
  )

  // Loading state
  if (loading) {
    return (
      <div className="plugin-management-page">
        <div className="plugin-management-header">
          <h1 className="plugin-management-title">
            <Plug size={20} />
            Plugins
          </h1>
        </div>
        {tabBar}
        {activeTab === 'installed' ? (
          <div className="plugin-management-loading" role="status" aria-live="polite">
            <span className="plugin-management-spinner" aria-hidden="true" />
            <span>Plugins werden geladenÔÇª</span>
          </div>
        ) : (
          <PluginStoreBrowser vaultId={vaultId} apiClient={apiClient} onPluginInstalled={() => void loadPlugins()} />
        )}
      </div>
    )
  }

  // Error state
  if (error) {
    return (
      <div className="plugin-management-page">
        <div className="plugin-management-header">
          <h1 className="plugin-management-title">
            <Plug size={20} />
            Plugins
          </h1>
        </div>
        {tabBar}
        {activeTab === 'installed' ? (
          <div className="plugin-management-error" role="alert">
            <AlertTriangle size={16} />
            <span>{error}</span>
            <button
              className="plugin-management-btn plugin-management-btn--small"
              onClick={() => void loadPlugins()}
            >
              <RefreshCw size={12} />
              Erneut versuchen
            </button>
          </div>
        ) : (
          <PluginStoreBrowser vaultId={vaultId} apiClient={apiClient} onPluginInstalled={() => void loadPlugins()} />
        )}
      </div>
    )
  }

  // Empty state
  if (plugins.length === 0) {
    return (
      <div className="plugin-management-page">
        <div className="plugin-management-header">
          <h1 className="plugin-management-title">
            <Plug size={20} />
            Plugins
          </h1>
        </div>
        {tabBar}
        {activeTab === 'installed' ? (
          <>
            <PluginUploadSection apiClient={apiClient} vaultId={vaultId} onPluginInstalled={() => void loadPlugins()} />
            <div className="plugin-management-empty">
              <Plug size={32} className="plugin-management-empty-icon" />
              <p className="plugin-management-empty-title">Keine Plugins installiert</p>
              <p className="plugin-management-empty-text">
                Installiere Obsidian Community Plugins, um zus├ñtzliche Funktionen hinzuzuf├╝gen.
              </p>
            </div>
          </>
        ) : (
          <PluginStoreBrowser vaultId={vaultId} apiClient={apiClient} onPluginInstalled={() => void loadPlugins()} />
        )}
      </div>
    )
  }

  // Plugin list
  return (
    <div className="plugin-management-page">
      <div className="plugin-management-header">
        <h1 className="plugin-management-title">
          <Plug size={20} />
          Plugins
        </h1>
        <span className="plugin-management-count">{plugins.length} installiert</span>
      </div>

      {tabBar}

      {activeTab === 'installed' ? (
        <>
          <PluginUploadSection apiClient={apiClient} vaultId={vaultId} onPluginInstalled={() => void loadPlugins()} />

          <div className="plugin-management-warning" role="status">
            <AlertTriangle size={14} />
            <span>
              <strong>Experimentell:</strong> Die Plugin-Kompatibilit├ñtsschicht befindet sich in aktiver Entwicklung.
              Nur browser-kompatible Plugins k├Ânnen ausgef├╝hrt werden. Plugins die Node.js-Module ben├Âtigen
              (z.B. IMAP, Git, Datenbank-Zugriff) werden erst mit serverseitiger Plugin-Ausf├╝hrung unterst├╝tzt.
            </span>
          </div>

          <div className="plugin-management-update-actions">
            <button
              className="plugin-management-check-updates-button"
              onClick={() => void handleCheckUpdates()}
              disabled={checkingUpdates}
            >
              {checkingUpdates && <Loader2 size={14} className="plugin-spinning" />}
              {t('pluginStore.checkUpdates')}
            </button>
            {updateInfo.size > 0 && !checkingUpdates && (
              <>
                <span className="plugin-management-update-summary">
                  {updateCount} {t('pluginStore.updatesAvailable').replace('{count}', '')}
                </span>
                <button
                  className="plugin-management-update-all-button"
                  onClick={() => void handleUpdateAllInstalled()}
                  disabled={isUpdatingAll}
                >
                  {isUpdatingAll && <Loader2 size={14} className="plugin-spinning" />}
                  {t('pluginStore.updateAll')}
                </button>
              </>
            )}
            {updateInfo.size === 0 && !checkingUpdates && hasCheckedUpdates && updateCount === 0 && plugins.length > 0 && (
              <span className="plugin-management-all-up-to-date">
                <CheckCircle2 size={13} />
                {t('pluginStore.allUpToDate')}
              </span>
            )}
          </div>

      <div className="plugin-management-list">
        {plugins.map((plugin) => (
          <div
            key={plugin.pluginId}
            className={`plugin-card plugin-card--${plugin.status}`}
          >
            {/* Plugin header row */}
            <div className="plugin-card-header">
              <div className="plugin-card-info">
                <div className="plugin-card-name-row">
                  <span className="plugin-card-name">{plugin.name}</span>
                  <span className="plugin-card-version">v{plugin.version}</span>
                  {updateInfo.has(plugin.pluginId) && (
                    <span className="plugin-management-update-hint">
                      {plugin.version} ÔåÆ {updateInfo.get(plugin.pluginId)!.latestVersion}
                    </span>
                  )}
                  <span className={`plugin-card-status plugin-card-status--${plugin.status}`}>
                    {getStatusLabel(plugin.status)}
                  </span>
                </div>
                <div className="plugin-card-meta">
                  <span className="plugin-card-author">{plugin.author}</span>
                  <span className="plugin-card-compat">
                    {getCompatibilityIcon(plugin.compatibilityLevel)}
                    {getCompatibilityLabel(plugin.compatibilityLevel)}
                  </span>
                </div>
              </div>

              <div className="plugin-card-actions">
                {updateInfo.has(plugin.pluginId) && (
                  <button
                    className="plugin-card-btn plugin-card-btn--update"
                    onClick={() => void handleUpdatePlugin(plugin.pluginId)}
                    disabled={updatingPlugins.has(plugin.pluginId)}
                    title={t('pluginStore.update')}
                    aria-label={`${plugin.name} aktualisieren`}
                  >
                    {updatingPlugins.has(plugin.pluginId) ? <Loader2 size={14} className="plugin-spinning" /> : <RefreshCw size={14} />}
                    {t('pluginStore.update')}
                  </button>
                )}
                {plugin.hasSettings && plugin.status === 'active' && (
                  <button
                    className="plugin-card-btn plugin-card-btn--settings"
                    title="Einstellungen"
                    aria-label={`Einstellungen f├╝r ${plugin.name}`}
                    onClick={() => void openSettings(plugin.pluginId, plugin.name)}
                  >
                    <Settings size={14} />
                  </button>
                )}
                <button
                  className="plugin-card-btn plugin-card-btn--delete"
                  title="Deinstallieren"
                  aria-label={`${plugin.name} deinstallieren`}
                  onClick={() => setDeleteConfirm({ pluginId: plugin.pluginId, pluginName: plugin.name })}
                  disabled={deletingPlugins.has(plugin.pluginId)}
                >
                  <Trash2 size={14} />
                </button>
                <label className="plugin-card-toggle" aria-label={`${plugin.name} ${plugin.status === 'active' ? 'deaktivieren' : 'aktivieren'}`}>
                  <input
                    type="checkbox"
                    checked={plugin.status === 'active'}
                    disabled={togglingPlugins.has(plugin.pluginId)}
                    onChange={() => void handleToggle(plugin.pluginId)}
                  />
                  <span className="plugin-card-toggle-slider" />
                </label>
              </div>
            </div>

            {/* Description */}
            {plugin.description && (
              <p className="plugin-card-description">
                {plugin.description.length > 200
                  ? `${plugin.description.slice(0, 200)}ÔÇª`
                  : plugin.description
                }
              </p>
            )}

            {/* Error display */}
            {plugin.status === 'error' && plugin.error && (
              <div className="plugin-card-error">
                <AlertTriangle size={13} />
                <span className="plugin-card-error-message">{plugin.error}</span>
                <button
                  className="plugin-card-btn plugin-card-btn--reload"
                  onClick={() => void handleReload(plugin.pluginId)}
                  disabled={reloadingPlugins.has(plugin.pluginId)}
                  title="Neu laden"
                >
                  <RefreshCw size={12} className={reloadingPlugins.has(plugin.pluginId) ? 'plugin-spinning' : ''} />
                  Neu laden
                </button>
              </div>
            )}

            {/* Eval usage warning indicator */}
            {plugin.hasEvalUsage && plugin.status !== 'error' && (
              <div className="plugin-card-eval-warning">
                <AlertTriangle size={13} />
                <span>{t('pluginStore.evalWarningTitle')}: {t('pluginStore.evalWarningMessage')}</span>
              </div>
            )}

            {/* Expandable compatibility details */}
            <button
              className="plugin-card-expand-btn"
              onClick={() => setExpandedPlugin(expandedPlugin === plugin.pluginId ? null : plugin.pluginId)}
              aria-expanded={expandedPlugin === plugin.pluginId}
            >
              {expandedPlugin === plugin.pluginId
                ? <ChevronDown size={12} />
                : <ChevronRight size={12} />
              }
              Kompatibilit├ñtsdetails
            </button>

            {expandedPlugin === plugin.pluginId && (
              <div className="plugin-card-details">
                <div className="plugin-card-detail-row">
                  <span className="plugin-card-detail-label">Kompatibilit├ñt:</span>
                  <span className="plugin-card-detail-value">
                    {getCompatibilityIcon(plugin.compatibilityLevel)}
                    {getCompatibilityLabel(plugin.compatibilityLevel)}
                  </span>
                </div>

                {/* Compatibility reasons */}
                {plugin.compatibilityReasons.length > 0 && (
                  <div className="plugin-card-detail-reasons">
                    <span className="plugin-card-detail-label">Begr├╝ndung:</span>
                    <ul className="plugin-card-reasons-list">
                      {plugin.compatibilityReasons.map((reason, idx) => (
                        <li key={idx} className="plugin-card-reasons-item">{reason}</li>
                      ))}
                    </ul>
                  </div>
                )}

                {/* Detected API calls */}
                {plugin.compatibilityApiCalls.length > 0 && (
                  <div className="plugin-card-detail-apicalls">
                    <span className="plugin-card-detail-label">Erkannte API-Aufrufe:</span>
                    <div className="plugin-card-apicalls-grid">
                      {plugin.compatibilityApiCalls.map((call) => (
                        <div key={call.method} className={`plugin-card-apicall plugin-card-apicall--${call.classification}`}>
                          <code className="plugin-card-apicall-method">{call.method}</code>
                          <span className={`plugin-card-apicall-badge plugin-card-apicall-badge--${call.classification}`}>
                            {call.classification === 'supported' && 'unterst├╝tzt'}
                            {call.classification === 'partial' && 'teilweise'}
                            {call.classification === 'unsupported' && 'nicht unterst├╝tzt'}
                          </span>
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                <div className="plugin-card-detail-row">
                  <span className="plugin-card-detail-label">Plugin-ID:</span>
                  <span className="plugin-card-detail-value plugin-card-detail-value--mono">{plugin.pluginId}</span>
                </div>
                <div className="plugin-card-detail-row">
                  <span className="plugin-card-detail-label">Version:</span>
                  <span className="plugin-card-detail-value">{plugin.version}</span>
                </div>
                {plugin.author && (
                  <div className="plugin-card-detail-row">
                    <span className="plugin-card-detail-label">Autor:</span>
                    <span className="plugin-card-detail-value">{plugin.author}</span>
                  </div>
                )}
              </div>
            )}
          </div>
        ))}
      </div>

      {/* Settings modal */}
      {settingsModal && createPortal(
        <div className="plugin-settings-overlay" onClick={() => setSettingsModal(null)}>
          <div className="plugin-settings-modal" onClick={(e) => e.stopPropagation()}>
            <div className="plugin-settings-modal-header">
              <h2 className="plugin-settings-modal-title">
                <Settings size={16} />
                Einstellungen: {settingsModal.pluginName}
              </h2>
              <button
                className="plugin-settings-modal-close"
                onClick={() => setSettingsModal(null)}
                aria-label="Schlie├ƒen"
              >
                <X size={16} />
              </button>
            </div>
            <div className="plugin-settings-modal-body">
              {settingsLoading ? (
                <div className="plugin-settings-loading">
                  <span className="plugin-management-spinner" aria-hidden="true" />
                  <span>Einstellungen werden geladenÔÇª</span>
                </div>
              ) : pluginContext?.settingTabRegistry.has(settingsModal.pluginId) ? (
                /* Native plugin settings tab UI */
                <div ref={settingsContainerRef} className="plugin-settings-native" data-plugin-id={settingsModal.pluginId} />
              ) : (
                /* Fallback: JSON editor */
                <>
                  <label className="plugin-settings-label" htmlFor="plugin-settings-editor">
                    Plugin-Daten (JSON):
                  </label>
                  <textarea
                    id="plugin-settings-editor"
                    className="plugin-settings-textarea"
                    value={settingsJson}
                    onChange={(e) => setSettingsJson(e.target.value)}
                    spellCheck={false}
                    rows={16}
                  />
                </>
              )}
              {settingsError && (
                <div className="plugin-settings-error" role="alert">
                  <AlertTriangle size={13} />
                  <span>{settingsError}</span>
                </div>
              )}
            </div>
            <div className="plugin-settings-modal-footer">
              <button
                className="plugin-management-btn plugin-management-btn--secondary"
                onClick={() => {
                  // Call hide() on the setting tab if it exists
                  const tab = pluginContext?.settingTabRegistry.get(settingsModal.pluginId)
                  if (tab) { try { tab.hide() } catch { /* ignore */ } }
                  setSettingsModal(null)
                }}
              >
                {pluginContext?.settingTabRegistry.has(settingsModal.pluginId) ? 'Schlie├ƒen' : 'Abbrechen'}
              </button>
              {!pluginContext?.settingTabRegistry.has(settingsModal.pluginId) && (
                <button
                  className="plugin-management-btn plugin-management-btn--primary"
                  onClick={() => void saveSettings()}
                  disabled={settingsSaving || settingsLoading}
                >
                  <Save size={13} />
                  {settingsSaving ? 'SpeichernÔÇª' : 'Speichern'}
                </button>
              )}
            </div>
          </div>
        </div>,
        document.body
      )}
      {/* Delete confirmation modal */}
      <ConfirmModal
        open={deleteConfirm !== null}
        title="Plugin deinstallieren"
        message={`M├Âchtest du das Plugin ÔÇ×${deleteConfirm?.pluginName ?? ''}" wirklich deinstallieren? Alle Plugin-Daten (Bundle, Styles, Einstellungen) werden unwiderruflich gel├Âscht.`}
        confirmLabel="Deinstallieren"
        variant="danger"
        onConfirm={() => { if (deleteConfirm) void handleDelete(deleteConfirm.pluginId) }}
        onCancel={() => setDeleteConfirm(null)}
      />
      {/* Eval usage warning modal */}
      <ConfirmModal
        open={evalWarningConfirm !== null}
        title={t('pluginStore.evalWarningTitle')}
        message={`${evalWarningConfirm?.pluginName ?? ''}: ${t('pluginStore.evalWarningMessage')}`}
        confirmLabel={t('pluginStore.evalWarningConfirm')}
        cancelLabel={t('pluginStore.evalWarningCancel')}
        variant="danger"
        onConfirm={handleEvalWarningConfirm}
        onCancel={() => setEvalWarningConfirm(null)}
      />
        </>
      ) : (
        <PluginStoreBrowser vaultId={vaultId} apiClient={apiClient} onPluginInstalled={() => void loadPlugins()} />
      )}
    </div>
  )
}

// ÔöÇÔöÇÔöÇ Helper: Upload section with directory tree from context ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

/** Props for the upload section wrapper. */
interface PluginUploadSectionProps {
  apiClient: IApiClient
  vaultId: string
  onPluginInstalled: () => void
}

/**
 * Wraps PluginUpload with access to the API client.
 */
function PluginUploadSection({ apiClient, vaultId, onPluginInstalled }: PluginUploadSectionProps) {
  return (
    <PluginUpload
      apiClient={apiClient}
      vaultId={vaultId}
      onPluginInstalled={onPluginInstalled}
    />
  )
}

import { useRef, useState, type ReactNode } from 'react'
import { useTabContext } from '../state/tabContext'
import { useTranslation } from '../i18n'
import { Eye, Pencil, X, Share2 } from 'lucide-react'
import { getFileIcon, getFileIconClass, getDisplayName } from '../utils/fileIcons'

/** A single settings-page tab shown ahead of the file tabs (not draggable). */
export interface SettingsTabDescriptor {
  /** Stable identifier for the React key ÔÇö the AppPage value. */
  key: string
  label: string
  icon?: ReactNode
  isActive: boolean
  onActivate: () => void
  onClose: () => void
  closeAriaLabel: string
  closeTitle: string
}

/** Props for the TabBar component. */
export interface TabBarProps {
  /** Settings pages currently open as tabs (e.g. Profile, Sessions, Admin panels). */
  settingsTabs: SettingsTabDescriptor[]
  /** True while a settings tab is the active content (no file tab shows as active). */
  isShowingSettings: boolean
  /** Called when a file tab is clicked, before activating it ÔÇö lets the caller deactivate any settings tab. */
  onActivateFileTab: () => void
}

/**
 * TabBar renders the unified horizontal tab strip: settings-page tabs first
 * (not draggable), then open file tabs (draggable/reorderable), in one row.
 * Each file tab shows the filename (truncated to fit), a mode toggle icon,
 * and a close button. The active tab is visually distinguished.
 */
export function TabBar({ settingsTabs, isShowingSettings, onActivateFileTab }: TabBarProps) {
  const { t } = useTranslation()
  const { tabState, tabDispatch } = useTabContext()
  const { tabs, activeTabId } = tabState
  const dragIndexRef = useRef<number | null>(null)
  const [dragOverIndex, setDragOverIndex] = useState<number | null>(null)

  if (settingsTabs.length === 0 && tabs.length === 0) {
    return null
  }

  function handleActivate(tabId: string) {
    onActivateFileTab()
    tabDispatch({ type: 'ACTIVATE_TAB', payload: { tabId } })
  }

  function handleClose(e: React.MouseEvent, tabId: string) {
    e.stopPropagation()
    tabDispatch({ type: 'CLOSE_TAB', payload: { tabId } })
  }

  function handleToggleMode(e: React.MouseEvent, tabId: string) {
    e.stopPropagation()
    tabDispatch({ type: 'TOGGLE_MODE', payload: { tabId } })
  }

  function handleDragStart(e: React.DragEvent, index: number) {
    dragIndexRef.current = index
    e.dataTransfer.effectAllowed = 'move'
    e.dataTransfer.setData('text/plain', String(index))
  }

  function handleDragOver(e: React.DragEvent, index: number) {
    e.preventDefault()
    e.dataTransfer.dropEffect = 'move'
    if (dragIndexRef.current !== null && dragIndexRef.current !== index) {
      setDragOverIndex(index)
    }
  }

  function handleDragLeave() {
    setDragOverIndex(null)
  }

  function handleDrop(e: React.DragEvent, toIndex: number) {
    e.preventDefault()
    setDragOverIndex(null)
    const fromIndex = dragIndexRef.current
    if (fromIndex !== null && fromIndex !== toIndex) {
      tabDispatch({ type: 'REORDER_TABS', payload: { fromIndex, toIndex } })
    }
    dragIndexRef.current = null
  }

  function handleDragEnd() {
    dragIndexRef.current = null
    setDragOverIndex(null)
  }

  /** Dropping past the last tab (in the row's empty space) moves it to the end. */
  function handleRowDragOver(e: React.DragEvent) {
    if (dragIndexRef.current !== null) {
      e.preventDefault()
      e.dataTransfer.dropEffect = 'move'
    }
  }

  function handleRowDrop(e: React.DragEvent) {
    e.preventDefault()
    setDragOverIndex(null)
    const fromIndex = dragIndexRef.current
    const lastIndex = tabs.length - 1
    if (fromIndex !== null && fromIndex !== lastIndex) {
      tabDispatch({ type: 'REORDER_TABS', payload: { fromIndex, toIndex: lastIndex } })
    }
    dragIndexRef.current = null
  }

  return (
    <div
      className="tab-bar"
      role="tablist"
      aria-label={t('tabs.ariaLabel')}
      onDragOver={handleRowDragOver}
      onDrop={handleRowDrop}
    >
      {settingsTabs.map((settingsTab) => (
        <div
          key={`settings-${settingsTab.key}`}
          role="tab"
          aria-selected={settingsTab.isActive}
          className={`tab-bar-tab${settingsTab.isActive ? ' tab-bar-tab--active' : ''}`}
          onClick={settingsTab.onActivate}
          title={settingsTab.label}
          tabIndex={settingsTab.isActive ? 0 : -1}
        >
          {settingsTab.icon && <span style={{ flexShrink: 0 }}>{settingsTab.icon}</span>}
          <span className="tab-bar-tab-label">{settingsTab.label}</span>
          <button
            type="button"
            className="tab-bar-close-btn"
            aria-label={settingsTab.closeAriaLabel}
            title={settingsTab.closeTitle}
            onClick={(e) => { e.stopPropagation(); settingsTab.onClose() }}
          >
            <X size={12} />
          </button>
        </div>
      ))}

      {tabs.map((tab, index) => {
        const isActive = !isShowingSettings && tab.id === activeTabId
        const hasUnsaved = tab.editBuffer !== null && tab.editBuffer !== tab.content
        const modeLabel = tab.mode === 'edit' ? t('tabs.showPreview') : t('tabs.edit')
        const ModeIcon = tab.mode === 'edit' ? Eye : Pencil
        const isGraphTab = tab.filePath === '__graph__'
        const isCanvasTab = tab.fileName.endsWith('.canvas')
        const TabFileIcon = isGraphTab ? Share2 : getFileIcon(tab.fileName)
        const tabFileIconClass = isGraphTab ? 'tab-icon-graph' : getFileIconClass(tab.fileName)
        const displayName = isGraphTab ? tab.fileName : getDisplayName(tab.fileName)

        return (
          <div
            key={tab.id}
            role="tab"
            aria-selected={isActive}
            aria-label={tab.filePath}
            className={`tab-bar-tab${isActive ? ' tab-bar-tab--active' : ''}${dragOverIndex === index ? ' tab-bar-tab--drag-over' : ''}`}
            onClick={() => handleActivate(tab.id)}
            title={isGraphTab ? 'Graph' : tab.filePath}
            tabIndex={isActive ? 0 : -1}
            draggable
            onDragStart={(e) => handleDragStart(e, index)}
            onDragOver={(e) => handleDragOver(e, index)}
            onDragLeave={handleDragLeave}
            onDrop={(e) => handleDrop(e, index)}
            onDragEnd={handleDragEnd}
          >
            <TabFileIcon size={13} className={`tab-bar-tab-icon ${tabFileIconClass}`} />
            <span className="tab-bar-tab-label">
              {hasUnsaved ? 'ÔùÅ ' : ''}{displayName}
            </span>
            {!tab.isBinary && !isGraphTab && !isCanvasTab && (
              <button
                type="button"
                className="tab-bar-mode-btn"
                aria-label={modeLabel}
                title={modeLabel}
                onClick={(e) => handleToggleMode(e, tab.id)}
              >
                <ModeIcon size={12} />
              </button>
            )}
            <button
              type="button"
              className="tab-bar-close-btn"
              aria-label={t('tabs.closeTabAriaLabel', { name: tab.fileName })}
              title={t('tabs.closeTab')}
              onClick={(e) => handleClose(e, tab.id)}
            >
              <X size={12} />
            </button>
          </div>
        )
      })}
    </div>
  )
}

import { useState, useEffect, useRef, useCallback } from 'react'
import { FileText, Search } from 'lucide-react'
import type { IApiClient } from '../api'
import { showToast } from './ToastNotification'
import './TemplateSelector.css'

/**
 * Template entry returned by the API.
 */
interface TemplateEntry {
  /** Display name (filename without .md). */
  name: string
  /** Relative path within the template directory. */
  path: string
}

export interface TemplateSelectorProps {
  /** Whether the selector is open. */
  isOpen: boolean
  /** Called to close the selector. */
  onClose: () => void
  /** API client instance. */
  apiClient: IApiClient
  /** Vault ID to fetch templates from. */
  vaultId: string
  /** Target directory for new file (relative path, empty string for root). */
  targetDir: string
  /** Called after a file is successfully created. Receives the file path. */
  onFileCreated: (filePath: string, fileName: string) => void
}

/**
 * TemplateSelector ÔÇö Two-step modal for creating a note from a template.
 *
 * Step 1: Show sorted template list for selection (with search filter).
 * Step 2: Prompt for the target filename.
 *
 * On Escape at any step, closes without side effects.
 * Shows info message if no templates are available.
 * Shows error message on filename conflict (409).
 *
 * Requirements: 7.1, 7.2, 7.3, 7.4, 7.6, 7.7
 */
export function TemplateSelector({
  isOpen,
  onClose,
  apiClient,
  vaultId,
  targetDir,
  onFileCreated,
}: TemplateSelectorProps) {
  const [step, setStep] = useState<'loading' | 'select' | 'filename'>('loading')
  const [templates, setTemplates] = useState<TemplateEntry[]>([])
  const [selectedTemplate, setSelectedTemplate] = useState<TemplateEntry | null>(null)
  const [query, setQuery] = useState('')
  const [selectedIndex, setSelectedIndex] = useState(0)
  const [fileName, setFileName] = useState('')
  const [fileNameError, setFileNameError] = useState<string | null>(null)
  const [isCreating, setIsCreating] = useState(false)

  const inputRef = useRef<HTMLInputElement>(null)
  const fileNameInputRef = useRef<HTMLInputElement>(null)
  const listRef = useRef<HTMLUListElement>(null)

  // Fetch templates when opened
  useEffect(() => {
    if (!isOpen) return

    // eslint-disable-next-line react-hooks/set-state-in-effect
    setStep('loading')
    setQuery('')
    setSelectedIndex(0)
    setSelectedTemplate(null)
    setFileName('')
    setFileNameError(null)
    setIsCreating(false)

    apiClient.listTemplates(vaultId).then(
      (result) => {
        if (result.templates.length === 0) {
          showToast('info', `Keine Vorlagen verf├╝gbar. Erstellen Sie .md-Dateien im Verzeichnis "Templates/" Ihres Vaults.`)
          onClose()
          return
        }
        setTemplates(result.templates)
        setStep('select')
        requestAnimationFrame(() => {
          inputRef.current?.focus()
        })
      },
      (err) => {
        const message = err && typeof err === 'object' && 'message' in err
          ? (err as { message: string }).message
          : 'Vorlagen konnten nicht geladen werden'
        showToast('error', message)
        onClose()
      }
    )
  }, [isOpen, apiClient, vaultId, onClose])

  // Filter templates by query
  const filteredTemplates = filterTemplates(templates, query)

  // Clamp selectedIndex
  useEffect(() => {
    if (selectedIndex >= filteredTemplates.length) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setSelectedIndex(Math.max(0, filteredTemplates.length - 1))
    }
  }, [filteredTemplates.length, selectedIndex])

  // Scroll selected item into view
  useEffect(() => {
    if (!listRef.current) return
    const selectedEl = listRef.current.querySelector('[aria-selected="true"]')
    if (selectedEl && typeof selectedEl.scrollIntoView === 'function') {
      selectedEl.scrollIntoView({ block: 'nearest' })
    }
  }, [selectedIndex])

  const handleSelectTemplate = useCallback((template: TemplateEntry) => {
    setSelectedTemplate(template)
    setStep('filename')
    setFileName('')
    setFileNameError(null)
    requestAnimationFrame(() => {
      fileNameInputRef.current?.focus()
    })
  }, [])

  const handleCreateFile = useCallback(async () => {
    if (!selectedTemplate || !fileName.trim()) return
    if (isCreating) return

    const trimmedName = fileName.trim()

    // Basic validation
    if (trimmedName.length > 255) {
      setFileNameError('Dateiname darf maximal 255 Zeichen lang sein')
      return
    }
    if (/[<>:"/\\|?*]/.test(trimmedName) || /[\x00-\x1f]/.test(trimmedName)) { // eslint-disable-line no-control-regex
      setFileNameError('Dateiname enth├ñlt ung├╝ltige Zeichen')
      return
    }

    setIsCreating(true)
    setFileNameError(null)

    try {
      const result = await apiClient.createFromTemplate(
        vaultId,
        selectedTemplate.name,
        targetDir,
        trimmedName
      )
      onFileCreated(result.path, trimmedName)
      onClose()
    } catch (err) {
      const error = err as { code?: string; message?: string } | undefined
      if (error?.code === 'TEMPLATE_CONFLICT') {
        setFileNameError(`Eine Datei mit dem Namen "${trimmedName}" existiert bereits`)
      } else {
        const message = error?.message ?? 'Datei konnte nicht erstellt werden'
        setFileNameError(message)
      }
    } finally {
      setIsCreating(false)
    }
  }, [selectedTemplate, fileName, isCreating, apiClient, vaultId, targetDir, onFileCreated, onClose])

  const handleKeyDownSelect = useCallback((e: React.KeyboardEvent) => {
    switch (e.key) {
      case 'ArrowDown':
        e.preventDefault()
        setSelectedIndex(prev =>
          prev < filteredTemplates.length - 1 ? prev + 1 : prev
        )
        break
      case 'ArrowUp':
        e.preventDefault()
        setSelectedIndex(prev => (prev > 0 ? prev - 1 : prev))
        break
      case 'Enter':
        e.preventDefault()
        if (filteredTemplates.length > 0) {
          const selected = filteredTemplates[selectedIndex]
          if (selected) {
            handleSelectTemplate(selected)
          }
        }
        break
      case 'Escape':
        e.preventDefault()
        onClose()
        break
    }
  }, [filteredTemplates, selectedIndex, handleSelectTemplate, onClose])

  const handleKeyDownFileName = useCallback((e: React.KeyboardEvent) => {
    switch (e.key) {
      case 'Enter':
        e.preventDefault()
        void handleCreateFile()
        break
      case 'Escape':
        e.preventDefault()
        onClose()
        break
    }
  }, [handleCreateFile, onClose])

  const handleOverlayClick = useCallback((e: React.MouseEvent) => {
    if (e.target === e.currentTarget) {
      onClose()
    }
  }, [onClose])

  if (!isOpen || step === 'loading') return null

  return (
    <div
      className="template-selector-overlay"
      onClick={handleOverlayClick}
      role="presentation"
    >
      <div
        className="template-selector"
        role="dialog"
        aria-modal="true"
        aria-label="Neue Notiz aus Vorlage"
      >
        {step === 'select' && (
          <>
            <div className="template-selector-header">
              <Search size={14} className="template-selector-search-icon" />
              <input
                ref={inputRef}
                type="text"
                className="template-selector-input"
                placeholder="Vorlage suchenÔÇª"
                value={query}
                onChange={(e) => {
                  setQuery(e.target.value)
                  setSelectedIndex(0)
                }}
                onKeyDown={handleKeyDownSelect}
                role="combobox"
                aria-expanded="true"
                aria-controls="template-selector-list"
                aria-activedescendant={
                  filteredTemplates.length > 0
                    ? `template-item-${selectedIndex}`
                    : undefined
                }
                aria-autocomplete="list"
              />
            </div>

            <ul
              ref={listRef}
              id="template-selector-list"
              className="template-selector-list"
              role="listbox"
              aria-label="Vorlagen"
            >
              {filteredTemplates.length === 0 ? (
                <li className="template-selector-empty" role="option" aria-selected={false}>
                  Keine Vorlagen gefunden
                </li>
              ) : (
                filteredTemplates.map((tmpl, index) => (
                  <li
                    key={tmpl.path}
                    id={`template-item-${index}`}
                    className={`template-selector-item${index === selectedIndex ? ' template-selector-item--selected' : ''}`}
                    role="option"
                    aria-selected={index === selectedIndex}
                    onClick={() => handleSelectTemplate(tmpl)}
                  >
                    <FileText size={14} className="template-selector-item-icon" />
                    <span className="template-selector-item-name">{tmpl.name}</span>
                  </li>
                ))
              )}
            </ul>
          </>
        )}

        {step === 'filename' && (
          <div className="template-selector-filename">
            <label className="template-selector-filename-label">
              Dateiname f├╝r neue Notiz (Vorlage: {selectedTemplate?.name})
            </label>
            <input
              ref={fileNameInputRef}
              type="text"
              className="template-selector-filename-input"
              placeholder="Dateiname (ohne .md)"
              value={fileName}
              onChange={(e) => {
                setFileName(e.target.value)
                setFileNameError(null)
              }}
              onKeyDown={handleKeyDownFileName}
              aria-label="Dateiname"
              aria-invalid={fileNameError ? 'true' : undefined}
              disabled={isCreating}
            />
            {fileNameError && (
              <p className="template-selector-filename-error" role="alert">
                {fileNameError}
              </p>
            )}
            <div className="template-selector-filename-actions">
              <button
                type="button"
                className="template-selector-btn template-selector-btn--primary"
                onClick={() => void handleCreateFile()}
                disabled={!fileName.trim() || isCreating}
              >
                {isCreating ? 'ErstelleÔÇª' : 'Erstellen'}
              </button>
              <button
                type="button"
                className="template-selector-btn template-selector-btn--secondary"
                onClick={onClose}
                disabled={isCreating}
              >
                Abbrechen
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

/**
 * Filter templates by case-insensitive substring match on name.
 */
function filterTemplates(templates: TemplateEntry[], query: string): TemplateEntry[] {
  if (!query) return templates
  const lowerQuery = query.toLowerCase()
  return templates.filter(t => t.name.toLowerCase().includes(lowerQuery))
}

import { useState, useEffect, useCallback } from 'react'
import { Trash2, RotateCcw, FileText, Folder, Loader2 } from 'lucide-react'
import type { IApiClient, TrashEntryInfo } from '../api'
import { ConfirmModal } from './ConfirmModal'
import { showToast } from './ToastNotification'
import './TrashView.css'

export interface TrashViewProps {
  /** Vault ID to display trash entries for. */
  vaultId: string
  /** API client instance. */
  apiClient: IApiClient
}

/**
 * Formats a date string to DD.MM.YYYY HH:mm in local timezone.
 */
function formatDeletionDate(isoDate: string): string {
  const date = new Date(isoDate)
  const day = String(date.getDate()).padStart(2, '0')
  const month = String(date.getMonth() + 1).padStart(2, '0')
  const year = date.getFullYear()
  const hours = String(date.getHours()).padStart(2, '0')
  const minutes = String(date.getMinutes()).padStart(2, '0')
  return `${day}.${month}.${year} ${hours}:${minutes}`
}

/**
 * Papierkorb-Ansicht ÔÇö displays deleted files with restore and permanent delete actions.
 */
export function TrashView({ vaultId, apiClient }: TrashViewProps) {
  const [entries, setEntries] = useState<TrashEntryInfo[]>([])
  const [loading, setLoading] = useState(true)
  const [actionInProgress, setActionInProgress] = useState<string | null>(null)
  const [confirmDelete, setConfirmDelete] = useState<TrashEntryInfo | null>(null)

  const fetchTrash = useCallback(async () => {
    setLoading(true)
    try {
      const result = await apiClient.listTrash(vaultId)
      setEntries(result.entries)
    } catch {
      showToast('error', 'Papierkorb konnte nicht geladen werden.')
    } finally {
      setLoading(false)
    }
  }, [apiClient, vaultId])

  useEffect(() => {
    // Data fetching on mount ÔÇö setState inside async callback is expected
    // eslint-disable-next-line react-hooks/set-state-in-effect
    void fetchTrash()
  }, [fetchTrash])

  const handleRestore = useCallback(async (entry: TrashEntryInfo) => {
    setActionInProgress(entry.id)
    try {
      await apiClient.restoreTrash(vaultId, entry.id)
      showToast('success', `"${entry.originalPath}" wiederhergestellt.`)
      await fetchTrash()
    } catch (err: unknown) {
      const message = err && typeof err === 'object' && 'message' in err
        ? (err as { message: string }).message
        : 'Unbekannter Fehler'
      showToast('error', `Wiederherstellung fehlgeschlagen: ${message}`)
    } finally {
      setActionInProgress(null)
    }
  }, [apiClient, vaultId, fetchTrash])

  const handleDeletePermanently = useCallback(async (entry: TrashEntryInfo) => {
    setConfirmDelete(null)
    setActionInProgress(entry.id)
    try {
      await apiClient.deleteTrash(vaultId, entry.id)
      showToast('success', `"${entry.originalPath}" endg├╝ltig gel├Âscht.`)
      await fetchTrash()
    } catch (err: unknown) {
      const message = err && typeof err === 'object' && 'message' in err
        ? (err as { message: string }).message
        : 'Unbekannter Fehler'
      showToast('error', `L├Âschen fehlgeschlagen: ${message}`)
    } finally {
      setActionInProgress(null)
    }
  }, [apiClient, vaultId, fetchTrash])

  if (loading) {
    return (
      <div className="trash-view">
        <div className="trash-view__header">
          <Trash2 size={18} className="trash-view__header-icon" />
          <h2 className="trash-view__title">Papierkorb</h2>
        </div>
        <div className="trash-view__loading">
          <Loader2 size={18} className="trash-view__spinner" />
          <span>Lade PapierkorbÔÇª</span>
        </div>
      </div>
    )
  }

  return (
    <div className="trash-view">
      <div className="trash-view__header">
        <Trash2 size={18} className="trash-view__header-icon" />
        <h2 className="trash-view__title">Papierkorb</h2>
        <span className="trash-view__count">{entries.length}</span>
      </div>

      {entries.length === 0 ? (
        <div className="trash-view__empty">
          <Trash2 size={32} className="trash-view__empty-icon" />
          <p className="trash-view__empty-text">Der Papierkorb ist leer.</p>
        </div>
      ) : (
        <ul className="trash-view__list" role="list">
          {entries.map((entry) => (
            <li key={entry.id} className="trash-view__entry">
              <div className="trash-view__entry-icon">
                {entry.isDirectory
                  ? <Folder size={16} />
                  : <FileText size={16} />
                }
              </div>
              <div className="trash-view__entry-info">
                <span className="trash-view__entry-path" title={entry.originalPath}>
                  {entry.originalPath}
                </span>
                <span className="trash-view__entry-date">
                  Gel├Âscht: {formatDeletionDate(entry.deletedAt)}
                </span>
              </div>
              <div className="trash-view__entry-actions">
                <button
                  type="button"
                  className="trash-view__btn trash-view__btn--restore"
                  onClick={() => void handleRestore(entry)}
                  disabled={actionInProgress === entry.id}
                  title="Wiederherstellen"
                  aria-label={`${entry.originalPath} wiederherstellen`}
                >
                  <RotateCcw size={14} />
                  <span>Wiederherstellen</span>
                </button>
                <button
                  type="button"
                  className="trash-view__btn trash-view__btn--delete"
                  onClick={() => setConfirmDelete(entry)}
                  disabled={actionInProgress === entry.id}
                  title="Endg├╝ltig l├Âschen"
                  aria-label={`${entry.originalPath} endg├╝ltig l├Âschen`}
                >
                  <Trash2 size={14} />
                  <span>Endg├╝ltig l├Âschen</span>
                </button>
              </div>
            </li>
          ))}
        </ul>
      )}

      <ConfirmModal
        open={confirmDelete !== null}
        title="Endg├╝ltig l├Âschen"
        message={confirmDelete
          ? `"${confirmDelete.originalPath}" wird unwiderruflich gel├Âscht. Diese Aktion kann nicht r├╝ckg├ñngig gemacht werden.`
          : ''
        }
        confirmLabel="Endg├╝ltig l├Âschen"
        cancelLabel="Abbrechen"
        variant="danger"
        onConfirm={() => {
          if (confirmDelete) {
            void handleDeletePermanently(confirmDelete)
          }
        }}
        onCancel={() => setConfirmDelete(null)}
      />
    </div>
  )
}

import { useState, useRef, useEffect, useCallback } from 'react'
import { useAppContext, createVault, deleteVault, loadVaults } from '../state'
import { useTranslation } from '../i18n'
import { ChevronDown, ChevronUp, Plus, Trash2, Database, Eye, Pencil, Users } from 'lucide-react'
import { ConfirmModal } from './ConfirmModal'
import { VaultDeletionWorkflow } from './VaultDeletionWorkflow'

/**
 * Maximum vault name length as defined in the spec.
 */
const MAX_VAULT_NAME_LENGTH = 128

interface VaultListProps {
  onRegisterCreateVault?: (trigger: () => void) => void
}

/**
 * Renders a dropdown menu for vault selection, creation, and deletion.
 * The dropdown shows the currently selected vault name (or a placeholder).
 * Clicking opens a list of vaults with delete buttons and a create option.
 */
export function VaultList({ onRegisterCreateVault }: VaultListProps) {
  const { state, dispatch, apiClient } = useAppContext()
  const { t } = useTranslation()
  const [isOpen, setIsOpen] = useState(false)
  const [showCreateForm, setShowCreateForm] = useState(false)
  const [newVaultName, setNewVaultName] = useState('')
  const [validationError, setValidationError] = useState<string | null>(null)
  const [deleteConfirm, setDeleteConfirm] = useState<{ open: boolean; vaultId: string; vaultName: string }>({
    open: false, vaultId: '', vaultName: '',
  })
  const [deletionWorkflow, setDeletionWorkflow] = useState<{ open: boolean; vaultId: string } | null>(null)
  const dropdownRef = useRef<HTMLDivElement>(null)

  const triggerCreateVault = useCallback(() => {
    setIsOpen(true)
    setShowCreateForm(true)
    setValidationError(null)
  }, [])

  useEffect(() => {
    onRegisterCreateVault?.(triggerCreateVault)
  }, [onRegisterCreateVault, triggerCreateVault])

  const selectedVault = state.vaults.find((v) => v.id === state.selectedVaultId)

  // Close dropdown on outside click
  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsOpen(false)
        setShowCreateForm(false)
        setValidationError(null)
      }
    }
    document.addEventListener('mousedown', handleClickOutside)
    return () => document.removeEventListener('mousedown', handleClickOutside)
  }, [])

  function handleSelect(vaultId: string) {
    dispatch({ type: 'VAULT_SELECTED', payload: vaultId })
    setIsOpen(false)
  }

  function handleShowCreateForm() {
    setShowCreateForm(true)
    setValidationError(null)
  }

  function handleCancelCreate() {
    setShowCreateForm(false)
    setNewVaultName('')
    setValidationError(null)
  }

  async function handleCreateSubmit(e: React.FormEvent) {
    e.preventDefault()

    const trimmed = newVaultName
    if (trimmed.length === 0 || trimmed.trim().length === 0) {
      setValidationError(t('vault.nameEmpty'))
      return
    }
    if (trimmed.length > MAX_VAULT_NAME_LENGTH) {
      setValidationError(t('vault.nameTooLong', { max: MAX_VAULT_NAME_LENGTH }))
      return
    }
    if (state.vaults.some((v) => v.name === trimmed)) {
      setValidationError(t('vault.nameExists', { name: trimmed }))
      return
    }

    if (!apiClient) return

    setValidationError(null)
    await createVault(dispatch, apiClient, trimmed)

    setNewVaultName('')
    setShowCreateForm(false)
  }

  async function handleDelete(e: React.MouseEvent, vaultId: string, vaultName: string) {
    e.stopPropagation()
    setDeleteConfirm({ open: true, vaultId, vaultName })
  }

  async function handleDeleteConfirmed() {
    const { vaultId } = deleteConfirm
    setDeleteConfirm({ open: false, vaultId: '', vaultName: '' })
    if (!apiClient) return

    try {
      await apiClient.deleteVault(vaultId)
      dispatch({ type: 'VAULT_DELETED', payload: vaultId })
    } catch (err: unknown) {
      const error = err as { code?: string; message?: string }
      if (error.code === 'VAULT_HAS_ACTIVE_SHARES') {
        // Vault has active shares ÔÇö open the guided deletion workflow
        setDeletionWorkflow({ open: true, vaultId })
      } else {
        // Fallback: use the standard error dispatch
        await deleteVault(dispatch, apiClient, vaultId)
      }
    }
  }

  function handleDeletionWorkflowComplete() {
    setDeletionWorkflow(null)
    if (apiClient) {
      void loadVaults(dispatch, apiClient)
    }
  }

  return (
    <div className="vault-dropdown" ref={dropdownRef}>
      {/* Dropdown trigger */}
      <button
        type="button"
        className="vault-dropdown-trigger"
        onClick={() => setIsOpen(!isOpen)}
        aria-expanded={isOpen}
        aria-haspopup="listbox"
        aria-label={t('vault.selectAriaLabel')}
      >
        <span className="vault-dropdown-label">
          {selectedVault
            ? <>
                <Database size={13} style={{ display: 'inline', verticalAlign: 'middle', marginRight: 5 }} />
                {selectedVault.name}
                {selectedVault.permission === 'read' && (
                  <span className="vault-status-icon vault-status-icon--read" title={t('vault.permissionRead')}>
                    <Eye size={12} />
                  </span>
                )}
                {(selectedVault.shareCount ?? 0) > 0 && (
                  <span className="vault-status-icon vault-status-icon--shared" title={t('vault.shared', { count: selectedVault.shareCount ?? 0 })}>
                    <Users size={12} />
                  </span>
                )}
              </>
            : t('vault.select')}
        </span>
        <span className="vault-dropdown-chevron" aria-hidden="true">
          {isOpen ? <ChevronUp size={13} /> : <ChevronDown size={13} />}
        </span>
      </button>

      {/* Dropdown menu */}
      {isOpen && (
        <div className="vault-dropdown-menu" role="listbox">
          {state.vaults.length === 0 ? (
            <p className="vault-dropdown-empty">{t('vault.noVaults')}</p>
          ) : (
            <ul className="vault-dropdown-list">
              {state.vaults.map((vault) => (
                <li
                  key={vault.id}
                  className={`vault-dropdown-item${state.selectedVaultId === vault.id ? ' vault-dropdown-item--selected' : ''}`}
                  role="option"
                  aria-selected={state.selectedVaultId === vault.id}
                >
                  <button
                    type="button"
                    className="vault-dropdown-item-btn"
                    aria-label={`Vault: ${vault.name}`}
                    onClick={() => handleSelect(vault.id)}
                  >
                    {vault.name}
                    {vault.permission === 'read' && (
                      <span className="vault-permission-badge vault-permission-badge--read" title={t('vault.permissionRead')}>
                        <Eye size={11} />
                      </span>
                    )}
                    {vault.permission === 'write' && (
                      <span className="vault-permission-badge vault-permission-badge--write" title={t('vault.permissionWrite')}>
                        <Pencil size={11} />
                      </span>
                    )}
                    {(vault.shareCount ?? 0) > 0 && (
                      <span className="vault-permission-badge vault-permission-badge--shared" title={t('vault.shared', { count: vault.shareCount ?? 0 })}>
                        <Users size={11} />
                      </span>
                    )}
                  </button>
                  {(vault.permission === 'owner' || vault.permission === undefined) && (
                    <button
                      type="button"
                      className="vault-dropdown-item-delete"
                      aria-label={t('vault.deleteVaultAriaLabel', { name: vault.name })}
                      title={t('files.deleteTitle', { name: vault.name })}
                      onClick={(e) => handleDelete(e, vault.id, vault.name)}
                    >
                      <Trash2 size={13} />
                    </button>
                  )}
                </li>
              ))}
            </ul>
          )}

          {/* Create vault section */}
          <div className="vault-dropdown-create">
            {!showCreateForm ? (
              <button
                type="button"
                className="vault-dropdown-create-btn"
                onClick={handleShowCreateForm}
              >
                <Plus size={13} /> {t('vault.newVault')}
              </button>
            ) : (
              <form className="vault-dropdown-create-form" onSubmit={handleCreateSubmit}>
                <input
                  type="text"
                  className="vault-dropdown-create-input"
                  placeholder={t('vault.vaultNamePlaceholder')}
                  value={newVaultName}
                  onChange={(e) => setNewVaultName(e.target.value)}
                  maxLength={MAX_VAULT_NAME_LENGTH}
                  aria-label={t('vault.vaultNameLabel')}
                  autoFocus
                />
                <div className="vault-dropdown-create-actions">
                  <button type="submit" className="vault-dropdown-create-submit">
                    OK
                  </button>
                  <button type="button" className="vault-dropdown-create-cancel" onClick={handleCancelCreate}>
                    ├ù
                  </button>
                </div>
                {validationError && (
                  <p className="vault-dropdown-create-error" role="alert">
                    {validationError}
                  </p>
                )}
              </form>
            )}
          </div>
        </div>
      )}

      {/* Delete Confirmation Modal */}
      <ConfirmModal
        open={deleteConfirm.open}
        title={t('vault.deleteVault')}
        message={t('vault.deleteConfirm', { name: deleteConfirm.vaultName })}
        confirmLabel={t('common.delete')}
        variant="danger"
        onConfirm={handleDeleteConfirmed}
        onCancel={() => setDeleteConfirm({ open: false, vaultId: '', vaultName: '' })}
      />

      {/* Vault Deletion Workflow (shown when vault has active shares) */}
      {deletionWorkflow?.open && apiClient && (
        <div className="vault-deletion-workflow-overlay">
          <div className="vault-deletion-workflow-modal">
            <VaultDeletionWorkflow
              apiClient={apiClient}
              vaultId={deletionWorkflow.vaultId}
              onComplete={handleDeletionWorkflowComplete}
            />
          </div>
        </div>
      )}
    </div>
  )
}

/**
 * CanvasMinimap ÔÇö Scaled overview of the full canvas with a viewport indicator rectangle.
 * Click or drag on the minimap to navigate to that position.
 */

import { memo, useCallback, useRef } from 'react'
import type { CanvasNode } from '../../canvas/types'
import type { CanvasViewport } from '../../state/canvasState'
import { getCanvasColorVar } from './canvas-utils'

interface CanvasMinimapProps {
  nodes: CanvasNode[]
  viewport: CanvasViewport
  /** Container dimensions in pixels. */
  containerWidth: number
  containerHeight: number
  onNavigate: (x: number, y: number) => void
  visible: boolean
}

/** Fixed minimap dimensions. */
const MINIMAP_WIDTH = 180
const MINIMAP_HEIGHT = 120
const MINIMAP_PADDING = 10

export const CanvasMinimap = memo(function CanvasMinimap({
  nodes, viewport, containerWidth, containerHeight, onNavigate, visible,
}: CanvasMinimapProps) {
  const minimapRef = useRef<HTMLDivElement>(null)

  /** Convert minimap click coordinates to canvas coordinates and navigate. */
  const handleClick = useCallback((e: React.MouseEvent) => {
    if (!minimapRef.current || nodes.length === 0) return
    const rect = minimapRef.current.getBoundingClientRect()
    const clickX = e.clientX - rect.left
    const clickY = e.clientY - rect.top

    // Compute bounding box for coordinate conversion
    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity
    for (const node of nodes) {
      minX = Math.min(minX, node.x)
      minY = Math.min(minY, node.y)
      maxX = Math.max(maxX, node.x + node.width)
      maxY = Math.max(maxY, node.y + node.height)
    }
    const contentWidth = maxX - minX + MINIMAP_PADDING * 2
    const contentHeight = maxY - minY + MINIMAP_PADDING * 2
    const scale = Math.min(
      (MINIMAP_WIDTH - 8) / contentWidth,
      (MINIMAP_HEIGHT - 8) / contentHeight,
    )
    const offsetX = (MINIMAP_WIDTH - contentWidth * scale) / 2
    const offsetY = (MINIMAP_HEIGHT - contentHeight * scale) / 2
    const viewWidth = containerWidth / viewport.zoom
    const viewHeight = containerHeight / viewport.zoom

    // Convert back to canvas coordinates
    const canvasX = (clickX - offsetX) / scale + minX - MINIMAP_PADDING
    const canvasY = (clickY - offsetY) / scale + minY - MINIMAP_PADDING

    // Center the viewport on clicked position
    const newX = -(canvasX - viewWidth / 2)
    const newY = -(canvasY - viewHeight / 2)
    onNavigate(newX, newY)
  }, [nodes, containerWidth, containerHeight, viewport.zoom, onNavigate])

  // Early return AFTER all hooks
  if (!visible || nodes.length === 0) return null

  // Compute bounding box of all nodes
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity
  for (const node of nodes) {
    minX = Math.min(minX, node.x)
    minY = Math.min(minY, node.y)
    maxX = Math.max(maxX, node.x + node.width)
    maxY = Math.max(maxY, node.y + node.height)
  }

  const contentWidth = maxX - minX + MINIMAP_PADDING * 2
  const contentHeight = maxY - minY + MINIMAP_PADDING * 2

  // Scale factor to fit content into minimap
  const scale = Math.min(
    (MINIMAP_WIDTH - 8) / contentWidth,
    (MINIMAP_HEIGHT - 8) / contentHeight,
  )

  // Offset to center content in minimap
  const offsetX = (MINIMAP_WIDTH - contentWidth * scale) / 2
  const offsetY = (MINIMAP_HEIGHT - contentHeight * scale) / 2

  // Viewport rectangle in minimap coordinates
  const viewWidth = containerWidth / viewport.zoom
  const viewHeight = containerHeight / viewport.zoom
  const viewLeft = -viewport.x
  const viewTop = -viewport.y

  const viewRectX = offsetX + (viewLeft - minX + MINIMAP_PADDING) * scale
  const viewRectY = offsetY + (viewTop - minY + MINIMAP_PADDING) * scale
  const viewRectW = viewWidth * scale
  const viewRectH = viewHeight * scale

  return (
    <div
      ref={minimapRef}
      className="canvas-minimap"
      onClick={handleClick}
      role="navigation"
      aria-label="Canvas-Minimap"
    >
      <svg
        width={MINIMAP_WIDTH}
        height={MINIMAP_HEIGHT}
        className="canvas-minimap__svg"
      >
        {/* Node rectangles */}
        {nodes.map((node) => {
          const rx = offsetX + (node.x - minX + MINIMAP_PADDING) * scale
          const ry = offsetY + (node.y - minY + MINIMAP_PADDING) * scale
          const rw = node.width * scale
          const rh = node.height * scale
          const fill = getCanvasColorVar(node.color) ?? (node.type === 'group' ? 'var(--canvas-group-bg)' : 'var(--canvas-node-bg)')

          return (
            <rect
              key={node.id}
              x={rx}
              y={ry}
              width={Math.max(2, rw)}
              height={Math.max(2, rh)}
              rx={1}
              fill={fill}
              stroke="var(--canvas-node-border)"
              strokeWidth={0.5}
              opacity={node.type === 'group' ? 0.4 : 0.8}
            />
          )
        })}

        {/* Viewport indicator */}
        <rect
          x={viewRectX}
          y={viewRectY}
          width={viewRectW}
          height={viewRectH}
          fill="none"
          stroke="var(--canvas-selection-color)"
          strokeWidth={1.5}
          rx={1}
          className="canvas-minimap__viewport-rect"
        />
      </svg>
    </div>
  )
})

/**
 * CanvasView ÔÇö Main container component for rendering Obsidian .canvas files.
 * Manages viewport (zoom/pan), wires CanvasProvider, and orchestrates rendering layers.
 */

import { useCallback, useRef, useState, useEffect } from 'react'
import { CanvasProvider, useCanvasContext } from '../../state/canvasContext'
import type { DirectoryTree } from '../../types'
import type { CanvasNode, CanvasEdge, TextNode, FileNode, LinkNode, GroupNode } from '../../canvas/types'
import { parseCanvas } from '../../canvas'
import { TextNodeRenderer } from './TextNodeRenderer'
import { FileNodeRenderer } from './FileNodeRenderer'
import { LinkNodeRenderer } from './LinkNodeRenderer'
import { GroupNodeRenderer } from './GroupNodeRenderer'
import { EdgeRenderer } from './EdgeRenderer'
import { CanvasMinimap } from './CanvasMinimap'
import { EdgeContextMenu } from './EdgeContextMenu'
import { CanvasContextMenu } from './CanvasContextMenu'
import type { CanvasContextAction } from './CanvasContextMenu'
import { CanvasToolbar } from './CanvasToolbar'
import type { CanvasViewMode } from './CanvasToolbar'
import { CanvasSourceView } from './CanvasSourceView'
import { useViewportCulling } from './useViewportCulling'
import { generateCanvasId } from './canvas-utils'
import './CanvasView.css'

// ÔöÇÔöÇÔöÇ Props ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

export interface CanvasViewProps {
  vaultId: string
  filePath: string
  /** Raw JSON content of the .canvas file. */
  content: string
  /** Whether the canvas is read-only (no editing). */
  readOnly: boolean
  /** Callback to save changes (receives serialized JSON). */
  onSave: (content: string) => Promise<void>
  /** Callback to open a vault file in a new tab. */
  onFileOpen: (path: string) => void
  /** Directory tree for resolving file references. */
  directoryTree: DirectoryTree | null
  /** Auth token for file previews. */
  token?: string
  /** Callback to save file content. */
  onFileSave?: (filePath: string, content: string) => Promise<void>
}

/**
 * CanvasView wraps the inner canvas with the CanvasProvider.
 */
export function CanvasView(props: CanvasViewProps) {
  return (
    <CanvasProvider content={props.content} readOnly={props.readOnly} onSave={props.onSave}>
      <CanvasViewInner {...props} />
    </CanvasProvider>
  )
}

// ÔöÇÔöÇÔöÇ Constants ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

const MIN_ZOOM = 0.1
const MAX_ZOOM = 4.0
const ZOOM_STEP = 0.1
const GRID_SIZE = 20

// ÔöÇÔöÇÔöÇ Inner Component ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

function CanvasViewInner({ vaultId, readOnly, onFileOpen, directoryTree, token, onFileSave }: CanvasViewProps) {
  const { state, dispatch, save } = useCanvasContext()
  const containerRef = useRef<HTMLDivElement>(null)
  const [isPanning, setIsPanning] = useState(false)
  const [showGrid, setShowGrid] = useState(true)
  const [showMinimap, setShowMinimap] = useState(true)
  const [containerSize, setContainerSize] = useState({ width: 800, height: 600 })
  const [edgeContextMenu, setEdgeContextMenu] = useState<{ edge: CanvasEdge; x: number; y: number } | null>(null)
  const [contextMenu, setContextMenu] = useState<{ x: number; y: number; targetNodeId: string | null } | null>(null)
  const [viewMode, setViewMode] = useState<CanvasViewMode>('visual')
  const panStartRef = useRef<{ x: number; y: number; viewX: number; viewY: number } | null>(null)
  const [spaceHeld, setSpaceHeld] = useState(false)
  const [hasClipboard, setHasClipboard] = useState(false)
  const [editingNodeId, setEditingNodeId] = useState<string | null>(null)
  const [editingMode, setEditingMode] = useState<'content' | 'path'>('content')
  const [isDragOver, setIsDragOver] = useState(false)

  const { document, viewport, parseError, dirty, selectedNodeIds, selectedEdgeIds } = state

  // ÔöÇÔöÇÔöÇ Track container size for viewport culling + minimap ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  useEffect(() => {
    if (!containerRef.current) return
    const observer = new ResizeObserver((entries) => {
      for (const entry of entries) {
        setContainerSize({ width: entry.contentRect.width, height: entry.contentRect.height })
      }
    })
    observer.observe(containerRef.current)
    return () => observer.disconnect()
  }, [])

  // ÔöÇÔöÇÔöÇ Clipboard for copy/paste ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  const clipboardRef = useRef<CanvasNode[]>([])

  // ÔöÇÔöÇÔöÇ Toolbar add-node handlers (center of visible viewport) ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

  const addNodeAtCenter = useCallback((type: 'text' | 'file' | 'link' | 'group') => {
    const rect = containerRef.current?.getBoundingClientRect()
    if (!rect) return
    const cx = (rect.width / 2) / viewport.zoom - viewport.x
    const cy = (rect.height / 2) / viewport.zoom - viewport.y

    let node: CanvasNode
    switch (type) {
      case 'text':
        node = { id: generateCanvasId(), type: 'text', x: cx - 100, y: cy - 50, width: 200, height: 100, text: '' }
        break
      case 'file':
        node = { id: generateCanvasId(), type: 'file', x: cx - 100, y: cy - 40, width: 200, height: 80, file: '' }
        break
      case 'link':
        node = { id: generateCanvasId(), type: 'link', x: cx - 150, y: cy - 110, width: 300, height: 220, url: 'https://' }
        break
      case 'group':
        node = { id: generateCanvasId(), type: 'group', x: cx - 150, y: cy - 100, width: 300, height: 200, label: 'Gruppe' }
        break
    }
    dispatch({ type: 'ADD_NODE', payload: { node } })
  }, [viewport, dispatch])

  // ÔöÇÔöÇÔöÇ Keyboard Shortcuts ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

  useEffect(() => {
    function handleKeyDown(e: KeyboardEvent) {
      // Ignore keyboard shortcuts when focus is inside a textarea or input
      const tag = (e.target as HTMLElement)?.tagName
      if (tag === 'TEXTAREA' || tag === 'INPUT') return

      if (e.key === ' ' && !e.repeat) {
        setSpaceHeld(true)
      }
      // Ctrl+Z / Cmd+Z ÔåÆ Undo
      if ((e.ctrlKey || e.metaKey) && e.key === 'z' && !e.shiftKey) {
        e.preventDefault()
        dispatch({ type: 'UNDO' })
      }
      // Ctrl+Shift+Z / Cmd+Shift+Z ÔåÆ Redo
      if ((e.ctrlKey || e.metaKey) && e.key === 'z' && e.shiftKey) {
        e.preventDefault()
        dispatch({ type: 'REDO' })
      }
      // Ctrl+Y ÔåÆ Redo (alternative)
      if ((e.ctrlKey || e.metaKey) && e.key === 'y') {
        e.preventDefault()
        dispatch({ type: 'REDO' })
      }
      // Ctrl+S / Cmd+S ÔåÆ Save
      if ((e.ctrlKey || e.metaKey) && e.key === 's') {
        e.preventDefault()
        void save()
      }
      // Ctrl+C / Cmd+C ÔåÆ Copy selected nodes
      if ((e.ctrlKey || e.metaKey) && e.key === 'c' && !readOnly) {
        const selected = document?.nodes.filter((n) => selectedNodeIds.has(n.id)) ?? []
        if (selected.length > 0) {
          clipboardRef.current = selected
          setHasClipboard(true)
        }
      }
      // Ctrl+V / Cmd+V ÔåÆ Paste copied nodes
      if ((e.ctrlKey || e.metaKey) && e.key === 'v' && !readOnly) {
        if (clipboardRef.current.length > 0) {
          const offset = 30
          const newIds: string[] = []
          for (const node of clipboardRef.current) {
            const newNode: CanvasNode = { ...node, id: generateCanvasId(), x: node.x + offset, y: node.y + offset }
            dispatch({ type: 'ADD_NODE', payload: { node: newNode } })
            newIds.push(newNode.id)
          }
          dispatch({ type: 'SELECT_NODES', payload: { nodeIds: newIds } })
        }
      }
      // Ctrl+A / Cmd+A ÔåÆ Select all
      if ((e.ctrlKey || e.metaKey) && e.key === 'a' && document) {
        e.preventDefault()
        dispatch({ type: 'SELECT_NODES', payload: { nodeIds: document.nodes.map((n) => n.id) } })
      }
      // Delete / Backspace ÔåÆ Delete selected
      if ((e.key === 'Delete' || e.key === 'Backspace') && !readOnly) {
        const nodeIds = [...selectedNodeIds]
        const edgeIds = [...selectedEdgeIds]
        if (nodeIds.length > 0) {
          dispatch({ type: 'DELETE_NODES', payload: { nodeIds } })
        }
        if (edgeIds.length > 0) {
          dispatch({ type: 'DELETE_EDGES', payload: { edgeIds } })
        }
      }
      // Escape ÔåÆ Deselect
      if (e.key === 'Escape') {
        dispatch({ type: 'DESELECT_ALL' })
        setContextMenu(null)
      }
      // T ÔåÆ Add text node at center
      if (e.key === 't' && !e.ctrlKey && !e.metaKey && !e.altKey && !readOnly) {
        addNodeAtCenter('text')
      }
      // F ÔåÆ Add file node at center (only without modifier)
      if (e.key === 'f' && !e.ctrlKey && !e.metaKey && !e.altKey && !readOnly) {
        addNodeAtCenter('file')
      }
      // G ÔåÆ Add group at center
      if (e.key === 'g' && !e.ctrlKey && !e.metaKey && !e.altKey && !readOnly) {
        addNodeAtCenter('group')
      }
    }

    function handleKeyUp(e: KeyboardEvent) {
      if (e.key === ' ') {
        setSpaceHeld(false)
      }
    }

    window.addEventListener('keydown', handleKeyDown)
    window.addEventListener('keyup', handleKeyUp)
    return () => {
      window.removeEventListener('keydown', handleKeyDown)
      window.removeEventListener('keyup', handleKeyUp)
    }
  }, [dispatch, save, readOnly, selectedNodeIds, selectedEdgeIds, document, addNodeAtCenter])

  // ÔöÇÔöÇÔöÇ Zoom ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

  const handleWheel = useCallback((e: React.WheelEvent) => {
    // Don't zoom when the wheel event originates inside any canvas node
    const target = e.target as HTMLElement
    if (target.closest('.canvas-node')) return

    e.preventDefault()
    const delta = e.deltaY > 0 ? -ZOOM_STEP : ZOOM_STEP
    const newZoom = Math.min(MAX_ZOOM, Math.max(MIN_ZOOM, viewport.zoom + delta))
    dispatch({ type: 'SET_VIEWPORT', payload: { ...viewport, zoom: newZoom } })
  }, [viewport, dispatch])

  // ÔöÇÔöÇÔöÇ Pan ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

  const handleMouseDown = useCallback((e: React.MouseEvent) => {
    // Middle mouse button or space+left click for panning
    if (e.button === 1 || (spaceHeld && e.button === 0)) {
      e.preventDefault()
      setIsPanning(true)
      panStartRef.current = { x: e.clientX, y: e.clientY, viewX: viewport.x, viewY: viewport.y }
    }
    // Left click on background ÔåÆ deselect
    if (e.button === 0 && !spaceHeld && e.target === e.currentTarget) {
      dispatch({ type: 'DESELECT_ALL' })
    }
  }, [spaceHeld, viewport, dispatch])

  const handleMouseMove = useCallback((e: React.MouseEvent) => {
    if (!isPanning || !panStartRef.current) return
    const dx = e.clientX - panStartRef.current.x
    const dy = e.clientY - panStartRef.current.y
    dispatch({
      type: 'SET_VIEWPORT',
      payload: {
        ...viewport,
        x: panStartRef.current.viewX + dx / viewport.zoom,
        y: panStartRef.current.viewY + dy / viewport.zoom,
      },
    })
  }, [isPanning, viewport, dispatch])

  const handleMouseUp = useCallback(() => {
    setIsPanning(false)
    panStartRef.current = null
  }, [])

  // ÔöÇÔöÇÔöÇ Double-click ÔåÆ Create new TextNode ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

  const handleDoubleClick = useCallback((e: React.MouseEvent) => {
    if (readOnly || spaceHeld) return
    // Only trigger on the background (not on nodes)
    if (e.target !== e.currentTarget) return

    const rect = containerRef.current?.getBoundingClientRect()
    if (!rect) return

    // Convert screen coordinates to canvas coordinates
    const canvasX = (e.clientX - rect.left) / viewport.zoom - viewport.x
    const canvasY = (e.clientY - rect.top) / viewport.zoom - viewport.y

    const newNode: TextNode = {
      id: generateCanvasId(),
      type: 'text',
      x: canvasX - 100, // Center the node at click position
      y: canvasY - 50,
      width: 200,
      height: 100,
      text: '',
    }

    dispatch({ type: 'ADD_NODE', payload: { node: newNode } })
  }, [readOnly, spaceHeld, viewport, dispatch])

  // ÔöÇÔöÇÔöÇ Context Menu (Right-Click) ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

  const handleContextMenu = useCallback((e: React.MouseEvent) => {
    e.preventDefault()
    // Find if right-click is on a node
    const target = e.target as HTMLElement
    const nodeEl = target.closest('[data-node-id]') as HTMLElement | null
    const targetNodeId = nodeEl?.dataset['nodeId'] ?? null

    // If right-clicking a node, select it if not already selected
    if (targetNodeId && !selectedNodeIds.has(targetNodeId)) {
      dispatch({ type: 'SELECT_NODES', payload: { nodeIds: [targetNodeId] } })
    }

    setContextMenu({ x: e.clientX, y: e.clientY, targetNodeId })
  }, [selectedNodeIds, dispatch])

  /** Convert screen coordinates to canvas coordinates. */
  const screenToCanvas = useCallback((screenX: number, screenY: number) => {
    const rect = containerRef.current?.getBoundingClientRect()
    if (!rect) return { x: 0, y: 0 }
    return {
      x: (screenX - rect.left) / viewport.zoom - viewport.x,
      y: (screenY - rect.top) / viewport.zoom - viewport.y,
    }
  }, [viewport])

  // ÔöÇÔöÇÔöÇ Fit to View ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

  const fitToView = useCallback(() => {
    if (!document || document.nodes.length === 0 || !containerRef.current) return
    const padding = 50
    const rect = containerRef.current.getBoundingClientRect()

    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity
    for (const node of document.nodes) {
      minX = Math.min(minX, node.x)
      minY = Math.min(minY, node.y)
      maxX = Math.max(maxX, node.x + node.width)
      maxY = Math.max(maxY, node.y + node.height)
    }

    const contentWidth = maxX - minX + padding * 2
    const contentHeight = maxY - minY + padding * 2
    const zoom = Math.min(
      rect.width / contentWidth,
      rect.height / contentHeight,
      1, // Don't zoom in beyond 100%
    )
    const centerX = (minX + maxX) / 2
    const centerY = (minY + maxY) / 2

    dispatch({
      type: 'SET_VIEWPORT',
      payload: {
        x: -centerX + (rect.width / 2) / zoom,
        y: -centerY + (rect.height / 2) / zoom,
        zoom: Math.max(MIN_ZOOM, zoom),
      },
    })
  }, [document, dispatch])

  /** Handle context menu action. */
  const handleContextMenuAction = useCallback((action: CanvasContextAction) => {
    setContextMenu(null)

    const addPos = contextMenu ? screenToCanvas(contextMenu.x, contextMenu.y) : { x: 0, y: 0 }

    switch (action) {
      case 'edit-node': {
        // Enter edit mode for the targeted node
        if (contextMenu?.targetNodeId) {
          setEditingMode('content')
          setEditingNodeId(contextMenu.targetNodeId)
        }
        break
      }
      case 'edit-file-path': {
        // Enter path-edit mode for the targeted file node
        if (contextMenu?.targetNodeId) {
          setEditingMode('path')
          setEditingNodeId(contextMenu.targetNodeId)
        }
        break
      }
      case 'add-text': {
        const node: TextNode = { id: generateCanvasId(), type: 'text', x: addPos.x - 100, y: addPos.y - 50, width: 200, height: 100, text: '' }
        dispatch({ type: 'ADD_NODE', payload: { node } })
        break
      }
      case 'add-file': {
        const node: FileNode = { id: generateCanvasId(), type: 'file', x: addPos.x - 100, y: addPos.y - 40, width: 200, height: 80, file: '' }
        dispatch({ type: 'ADD_NODE', payload: { node } })
        break
      }
      case 'add-link': {
        const node: LinkNode = { id: generateCanvasId(), type: 'link', x: addPos.x - 150, y: addPos.y - 110, width: 300, height: 220, url: 'https://' }
        dispatch({ type: 'ADD_NODE', payload: { node } })
        break
      }
      case 'add-group': {
        const node: GroupNode = { id: generateCanvasId(), type: 'group', x: addPos.x - 150, y: addPos.y - 100, width: 300, height: 200, label: 'Gruppe' }
        dispatch({ type: 'ADD_NODE', payload: { node } })
        break
      }
      case 'copy': {
        const selected = document?.nodes.filter((n) => selectedNodeIds.has(n.id)) ?? []
        if (selected.length > 0) {
          clipboardRef.current = selected
          setHasClipboard(true)
        }
        break
      }
      case 'paste': {
        if (clipboardRef.current.length > 0) {
          const offset = 30
          const newIds: string[] = []
          for (const node of clipboardRef.current) {
            const newNode: CanvasNode = { ...node, id: generateCanvasId(), x: addPos.x + offset, y: addPos.y + offset }
            dispatch({ type: 'ADD_NODE', payload: { node: newNode } })
            newIds.push(newNode.id)
          }
          dispatch({ type: 'SELECT_NODES', payload: { nodeIds: newIds } })
        }
        break
      }
      case 'duplicate': {
        const selected = document?.nodes.filter((n) => selectedNodeIds.has(n.id)) ?? []
        const newIds: string[] = []
        for (const node of selected) {
          const newNode: CanvasNode = { ...node, id: generateCanvasId(), x: node.x + 30, y: node.y + 30 }
          dispatch({ type: 'ADD_NODE', payload: { node: newNode } })
          newIds.push(newNode.id)
        }
        if (newIds.length > 0) dispatch({ type: 'SELECT_NODES', payload: { nodeIds: newIds } })
        break
      }
      case 'select-all': {
        if (document) dispatch({ type: 'SELECT_NODES', payload: { nodeIds: document.nodes.map((n) => n.id) } })
        break
      }
      case 'fit-view': {
        fitToView()
        break
      }
      case 'undo': {
        dispatch({ type: 'UNDO' })
        break
      }
      case 'redo': {
        dispatch({ type: 'REDO' })
        break
      }
      case 'delete': {
        const nodeIds = [...selectedNodeIds]
        const edgeIds = [...selectedEdgeIds]
        if (nodeIds.length > 0) dispatch({ type: 'DELETE_NODES', payload: { nodeIds } })
        if (edgeIds.length > 0) dispatch({ type: 'DELETE_EDGES', payload: { edgeIds } })
        break
      }
      case 'color-1':
      case 'color-2':
      case 'color-3':
      case 'color-4':
      case 'color-5':
      case 'color-6': {
        const colorNum = action.replace('color-', '')
        for (const nodeId of selectedNodeIds) {
          dispatch({ type: 'UPDATE_NODE_COLOR', payload: { nodeId, color: colorNum } })
        }
        break
      }
      case 'color-none': {
        for (const nodeId of selectedNodeIds) {
          dispatch({ type: 'UPDATE_NODE_COLOR', payload: { nodeId, color: undefined } })
        }
        break
      }
    }
  }, [contextMenu, screenToCanvas, document, selectedNodeIds, selectedEdgeIds, dispatch, fitToView])

  // ÔöÇÔöÇÔöÇ Zoom handlers for toolbar ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

  const handleZoomIn = useCallback(() => {
    const newZoom = Math.min(MAX_ZOOM, viewport.zoom + ZOOM_STEP)
    dispatch({ type: 'SET_VIEWPORT', payload: { ...viewport, zoom: newZoom } })
  }, [viewport, dispatch])

  const handleZoomOut = useCallback(() => {
    const newZoom = Math.max(MIN_ZOOM, viewport.zoom - ZOOM_STEP)
    dispatch({ type: 'SET_VIEWPORT', payload: { ...viewport, zoom: newZoom } })
  }, [viewport, dispatch])

  // ÔöÇÔöÇÔöÇ Source view apply handler ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

  const handleApplySource = useCallback((json: string) => {
    const result = parseCanvas(json)
    if (result.success && result.document) {
      dispatch({ type: 'LOAD_CANVAS', payload: { document: result.document } })
    }
  }, [dispatch])

  // ÔöÇÔöÇÔöÇ Drag-and-Drop from FileExplorer ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

  const handleDragOver = useCallback((e: React.DragEvent) => {
    // Accept drops with slatebase path data (from FileExplorer)
    if (e.dataTransfer.types.includes('application/x-slatebase-path')) {
      e.preventDefault()
      e.dataTransfer.dropEffect = 'copy'
      setIsDragOver(true)
    }
  }, [])

  const handleDragLeave = useCallback((e: React.DragEvent) => {
    // Only handle leave for the container itself, not children
    if (e.currentTarget === e.target || !e.currentTarget.contains(e.relatedTarget as Node)) {
      setIsDragOver(false)
    }
  }, [])

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault()
    setIsDragOver(false)
    if (readOnly) return

    const filePath = e.dataTransfer.getData('application/x-slatebase-path')
    const fileType = e.dataTransfer.getData('application/x-slatebase-type')
    if (!filePath) return

    // Convert drop position to canvas coordinates
    const rect = containerRef.current?.getBoundingClientRect()
    if (!rect) return
    const canvasX = (e.clientX - rect.left) / viewport.zoom - viewport.x
    const canvasY = (e.clientY - rect.top) / viewport.zoom - viewport.y

    // Create a FileNode at the drop position
    if (fileType === 'file') {
      const node: FileNode = {
        id: generateCanvasId(),
        type: 'file',
        x: canvasX - 100,
        y: canvasY - 50,
        width: 250,
        height: 150,
        file: filePath,
      }
      dispatch({ type: 'ADD_NODE', payload: { node } })
    }
  }, [readOnly, viewport, dispatch])

  // ÔöÇÔöÇÔöÇ Node content change handlers ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

  const handleFilePathChange = useCallback((nodeId: string, newPath: string) => {
    dispatch({ type: 'UPDATE_NODE_FILE', payload: { nodeId, file: newPath } })
  }, [dispatch])

  const handleUrlChange = useCallback((nodeId: string, newUrl: string) => {
    dispatch({ type: 'UPDATE_NODE_URL', payload: { nodeId, url: newUrl } })
  }, [dispatch])

  // Auto fit-to-view on initial load
  const hasFitRef = useRef(false)
  useEffect(() => {
    if (document && document.nodes.length > 0 && !hasFitRef.current) {
      hasFitRef.current = true
      // Defer to allow container to measure
      requestAnimationFrame(() => fitToView())
    }
  }, [document, fitToView])

  // ÔöÇÔöÇÔöÇ Viewport culling + callbacks (must be above early returns per rules-of-hooks) ÔöÇ

  const allGroupNodes = document ? document.nodes.filter((n) => n.type === 'group') : []
  const allContentNodes = document ? document.nodes.filter((n) => n.type !== 'group') : []
  const groupNodes = useViewportCulling(allGroupNodes, viewport, containerSize.width, containerSize.height)
  const contentNodes = useViewportCulling(allContentNodes, viewport, containerSize.width, containerSize.height)

  /** Minimap navigation handler. */
  const handleMinimapNavigate = useCallback((x: number, y: number) => {
    dispatch({ type: 'SET_VIEWPORT', payload: { ...viewport, x, y } })
  }, [viewport, dispatch])

  /** Edge context menu handlers. */
  const handleEdgeContextMenu = useCallback((edgeId: string, x: number, y: number) => {
    const edge = document?.edges.find((e) => e.id === edgeId)
    if (edge) setEdgeContextMenu({ edge, x, y })
  }, [document])

  const handleEdgeUpdateLabel = useCallback((edgeId: string, label: string) => {
    dispatch({ type: 'UPDATE_EDGE_LABEL', payload: { edgeId, label } })
  }, [dispatch])

  const handleEdgeUpdateArrows = useCallback((edgeId: string, fromEnd: 'none' | 'arrow' | undefined, toEnd: 'none' | 'arrow' | undefined) => {
    dispatch({ type: 'UPDATE_EDGE_ARROWS', payload: { edgeId, fromEnd, toEnd } })
  }, [dispatch])

  const handleEdgeDelete = useCallback((edgeId: string) => {
    dispatch({ type: 'DELETE_EDGES', payload: { edgeIds: [edgeId] } })
  }, [dispatch])

  // ÔöÇÔöÇÔöÇ Parse Error ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

  if (parseError) {
    return (
      <div className="canvas-view canvas-view--error">
        <div className="canvas-view__error-content">
          <h3>Canvas konnte nicht geladen werden</h3>
          <p className="canvas-view__error-message">{parseError}</p>
          <p className="canvas-view__error-hint">Die Datei enth├ñlt ung├╝ltiges JSON. ├ûffne sie im Texteditor um den Fehler zu beheben.</p>
        </div>
      </div>
    )
  }

  if (!document) {
    return (
      <div className="canvas-view canvas-view--loading">
        <span className="app-loading-spinner" aria-hidden="true" />
        <span>Canvas ladenÔÇª</span>
      </div>
    )
  }

  // ÔöÇÔöÇÔöÇ Render ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

  const transform = `scale(${viewport.zoom}) translate(${viewport.x}px, ${viewport.y}px)`
  const cursorClass = isPanning ? 'canvas-view--panning' : spaceHeld ? 'canvas-view--pan-ready' : ''

  return (
    <div className="canvas-view__wrapper">
      {/* Enhanced Toolbar */}
      <CanvasToolbar
        zoom={viewport.zoom}
        dirty={dirty}
        readOnly={readOnly}
        showGrid={showGrid}
        showMinimap={showMinimap}
        canUndo={state.undoStack.length > 0}
        canRedo={state.redoStack.length > 0}
        viewMode={viewMode}
        onAddText={() => addNodeAtCenter('text')}
        onAddFile={() => addNodeAtCenter('file')}
        onAddLink={() => addNodeAtCenter('link')}
        onAddGroup={() => addNodeAtCenter('group')}
        onZoomIn={handleZoomIn}
        onZoomOut={handleZoomOut}
        onFitView={fitToView}
        onToggleGrid={() => setShowGrid(!showGrid)}
        onToggleMinimap={() => setShowMinimap(!showMinimap)}
        onUndo={() => dispatch({ type: 'UNDO' })}
        onRedo={() => dispatch({ type: 'REDO' })}
        onSave={() => void save()}
        onSetViewMode={setViewMode}
      />

      {/* Source View Mode */}
      {viewMode === 'source' && document && (
        <CanvasSourceView
          document={document}
          readOnly={readOnly}
          onApplySource={handleApplySource}
        />
      )}

      {/* Visual Canvas (hidden in source mode) */}
      {viewMode === 'visual' && (
        <>
          {/* Canvas container */}
          <div
            ref={containerRef}
            className={`canvas-view ${cursorClass} ${isDragOver ? 'canvas-view--drag-over' : ''}`}
            onWheel={handleWheel}
            onMouseDown={handleMouseDown}
            onMouseMove={handleMouseMove}
            onMouseUp={handleMouseUp}
            onMouseLeave={handleMouseUp}
            onDoubleClick={handleDoubleClick}
            onContextMenu={handleContextMenu}
            onDragOver={handleDragOver}
            onDragLeave={handleDragLeave}
            onDrop={handleDrop}
            tabIndex={0}
            role="application"
            aria-label="Canvas-Ansicht"
          >
            {/* Grid background */}
            {showGrid && (
              <svg className="canvas-view__grid" aria-hidden="true">
                <defs>
                  <pattern
                    id="canvas-grid"
                    width={GRID_SIZE * viewport.zoom}
                    height={GRID_SIZE * viewport.zoom}
                    patternUnits="userSpaceOnUse"
                    x={(viewport.x * viewport.zoom) % (GRID_SIZE * viewport.zoom)}
                    y={(viewport.y * viewport.zoom) % (GRID_SIZE * viewport.zoom)}
                  >
                    <circle
                      cx={GRID_SIZE * viewport.zoom / 2}
                      cy={GRID_SIZE * viewport.zoom / 2}
                      r="1"
                      className="canvas-view__grid-dot"
                    />
                  </pattern>
                </defs>
                <rect width="100%" height="100%" fill="url(#canvas-grid)" />
              </svg>
            )}

            {/* Transformed content layer */}
            <div className="canvas-view__transform-layer" style={{ transform }}>
              {/* SVG layer for edges */}
              <EdgeRenderer
                edges={document.edges}
                nodes={document.nodes}
                selectedEdgeIds={selectedEdgeIds}
                onSelectEdge={(edgeId, additive) => dispatch({ type: 'SELECT_EDGES', payload: { edgeIds: [edgeId], additive } })}
                onEdgeContextMenu={readOnly ? undefined : handleEdgeContextMenu}
                readOnly={readOnly}
              />

              {/* Group nodes (below content nodes) */}
              {groupNodes.map((node) => (
                node.type === 'group' && (
                  <GroupNodeRenderer
                    key={node.id}
                    node={node}
                    selected={selectedNodeIds.has(node.id)}
                    onSelect={(additive) => dispatch({ type: 'SELECT_NODES', payload: { nodeIds: [node.id], additive } })}
                    readOnly={readOnly}
                  />
                )
              ))}

              {/* Content nodes */}
              {contentNodes.map((node) => {
                switch (node.type) {
                  case 'text':
                    return (
                      <TextNodeRenderer
                        key={node.id}
                        node={node}
                        vaultId={vaultId}
                        selected={selectedNodeIds.has(node.id)}
                        onSelect={(additive) => dispatch({ type: 'SELECT_NODES', payload: { nodeIds: [node.id], additive } })}
                        onTextChange={(text) => dispatch({ type: 'UPDATE_NODE_TEXT', payload: { nodeId: node.id, text } })}
                        directoryTree={directoryTree}
                        readOnly={readOnly}
                        token={token}
                        editing={editingNodeId === node.id}
                        onEditEnd={() => setEditingNodeId(null)}
                      />
                    )
                  case 'file':
                    return (
                      <FileNodeRenderer
                        key={node.id}
                        node={node}
                        selected={selectedNodeIds.has(node.id)}
                        onSelect={(additive) => dispatch({ type: 'SELECT_NODES', payload: { nodeIds: [node.id], additive } })}
                        onFileOpen={onFileOpen}
                        onFilePathChange={(newPath) => handleFilePathChange(node.id, newPath)}
                        onFileSave={onFileSave}
                        directoryTree={directoryTree}
                        readOnly={readOnly}
                        editing={editingNodeId === node.id}
                        editPath={editingMode === 'path'}
                        onEditEnd={() => { setEditingNodeId(null); setEditingMode('content') }}
                        vaultId={vaultId}
                        token={token}
                      />
                    )
                  case 'link':
                    return (
                      <LinkNodeRenderer
                        key={node.id}
                        node={node}
                        selected={selectedNodeIds.has(node.id)}
                        onSelect={(additive) => dispatch({ type: 'SELECT_NODES', payload: { nodeIds: [node.id], additive } })}
                        onUrlChange={(newUrl) => handleUrlChange(node.id, newUrl)}
                        readOnly={readOnly}
                        editing={editingNodeId === node.id}
                        onEditEnd={() => setEditingNodeId(null)}
                      />
                    )
                  default:
                    return null
                }
              })}
            </div>
          </div>

          {/* Minimap */}
          <CanvasMinimap
            nodes={document.nodes}
            viewport={viewport}
            containerWidth={containerSize.width}
            containerHeight={containerSize.height}
            onNavigate={handleMinimapNavigate}
            visible={showMinimap}
          />

          {/* Edge Context Menu */}
          {edgeContextMenu && (
            <EdgeContextMenu
              edge={edgeContextMenu.edge}
              position={{ x: edgeContextMenu.x, y: edgeContextMenu.y }}
              onClose={() => setEdgeContextMenu(null)}
              onUpdateLabel={handleEdgeUpdateLabel}
              onUpdateArrows={handleEdgeUpdateArrows}
              onDelete={handleEdgeDelete}
            />
          )}

          {/* Canvas Context Menu */}
          {contextMenu && (() => {
            const targetNode = contextMenu.targetNodeId
              ? document.nodes.find((n) => n.id === contextMenu.targetNodeId)
              : undefined
            const targetIsMarkdownFile = targetNode?.type === 'file'
              && /\.(md|markdown)$/i.test(targetNode.file)
            return (
              <CanvasContextMenu
                x={contextMenu.x}
                y={contextMenu.y}
                targetNodeId={contextMenu.targetNodeId}
                targetIsMarkdownFile={targetIsMarkdownFile}
                readOnly={readOnly}
                canUndo={state.undoStack.length > 0}
                canRedo={state.redoStack.length > 0}
                canPaste={hasClipboard}
                hasSelection={selectedNodeIds.size > 0 || selectedEdgeIds.size > 0}
                onClose={() => setContextMenu(null)}
                onAction={handleContextMenuAction}
              />
            )
          })()}
        </>
      )}
    </div>
  )
}

/**
 * FileNodeRenderer ÔÇö Renders a file reference node with rich content preview.
 * - Images: renders the actual image inline
 * - Markdown: fetches and renders a preview of the file content
 * - PDF: shows a PDF icon with filename
 * - Other: shows file icon + name
 * Supports drag/move, resize, double-click to open, and edit mode for path editing.
 */

import { memo, useCallback, useState, useRef, useEffect, useMemo } from 'react'
import { FileText, ImageIcon, AlertTriangle, Film, Music, FileCode } from 'lucide-react'
import type { FileNode } from '../../canvas/types'
import type { DirectoryTree } from '../../types'
import { getCanvasColorClass } from './canvas-utils'
import { useNodeDrag } from './useNodeDrag'
import { useNodeResize } from './useNodeResize'
import { ResizeHandles } from './ResizeHandles'
import { NodeAnchors } from './NodeAnchors'
import { renderSimpleMarkdown } from './markdown-render.tsx'

export interface FileNodeRendererProps {
  node: FileNode
  selected: boolean
  onSelect: (additive: boolean) => void
  onFileOpen: (path: string) => void
  onFilePathChange?: (newPath: string) => void
  directoryTree: DirectoryTree | null
  readOnly: boolean
  /** Whether this node is in edit mode (editing the file path or content). */
  editing?: boolean
  /** When true, edit the file PATH even for markdown files (instead of content). */
  editPath?: boolean
  /** Callback when edit mode should end. */
  onEditEnd?: () => void
  /** Vault ID for constructing preview URLs. */
  vaultId?: string
  /** Auth token for fetching file content. */
  token?: string
  /** Callback to save file content (for inline MD editing). */
  onFileSave?: (filePath: string, content: string) => Promise<void>
}

/** Check if a file exists in the directory tree. */
function fileExistsInTree(tree: DirectoryTree | null, filePath: string): boolean {
  if (!tree) return false
  const normalized = filePath.replace(/\\/g, '/')
  function search(node: DirectoryTree): boolean {
    if (node.path.replace(/\\/g, '/') === normalized) return true
    if (node.children) {
      for (const child of node.children) {
        if (search(child)) return true
      }
    }
    return false
  }
  return search(tree)
}

/** Check file type category. */
function getFileCategory(path: string): 'image' | 'video' | 'audio' | 'pdf' | 'markdown' | 'other' {
  const ext = path.split('.').pop()?.toLowerCase() ?? ''
  if (['png', 'jpg', 'jpeg', 'gif', 'webp', 'avif', 'bmp', 'svg'].includes(ext)) return 'image'
  if (['mp4', 'webm', 'mov', 'avi'].includes(ext)) return 'video'
  if (['mp3', 'wav', 'ogg', 'flac', 'aac'].includes(ext)) return 'audio'
  if (ext === 'pdf') return 'pdf'
  if (['md', 'markdown'].includes(ext)) return 'markdown'
  return 'other'
}

/** Get the icon for a file category. */
function getCategoryIcon(category: ReturnType<typeof getFileCategory>) {
  switch (category) {
    case 'image': return ImageIcon
    case 'video': return Film
    case 'audio': return Music
    case 'pdf': return FileCode
    case 'markdown': return FileText
    default: return FileText
  }
}

export const FileNodeRenderer = memo(function FileNodeRenderer({
  node, selected, onSelect, onFileOpen, onFilePathChange, directoryTree, readOnly,
  editing, editPath, onEditEnd, vaultId, token, onFileSave,
}: FileNodeRendererProps) {
  const colorClass = getCanvasColorClass(node.color)
  const exists = fileExistsInTree(directoryTree, node.file)
  const fileName = node.file.split('/').pop() ?? node.file
  const category = getFileCategory(node.file)
  const Icon = !exists ? AlertTriangle : getCategoryIcon(category)

  // When editing a markdown file, the textarea edits its CONTENT. For every
  // other category ÔÇö or when path editing is explicitly requested ÔÇö the input
  // edits the file PATH instead.
  const showPathEditor = !!editPath || category !== 'markdown'

  const [editValue, setEditValue] = useState(node.file)
  const [mdContent, setMdContent] = useState<string | null>(null)
  const inputRef = useRef<HTMLInputElement>(null)
  const textareaRef = useRef<HTMLTextAreaElement>(null)

  const { onDragStart } = useNodeDrag(node.id, readOnly)
  const { onResizeStart } = useNodeResize(node.id, readOnly)

  // ÔöÇÔöÇ File search (path editor) ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  const [suggestionsOpen, setSuggestionsOpen] = useState(false)
  const [highlightIndex, setHighlightIndex] = useState(-1)

  /** Flat list of all file paths in the vault (directories excluded). */
  const allFilePaths = useMemo(() => {
    const out: string[] = []
    const walk = (n: DirectoryTree | null | undefined) => {
      if (!n) return
      if (n.type === 'file') out.push(n.path)
      n.children?.forEach(walk)
    }
    walk(directoryTree)
    return out.sort((a, b) => a.localeCompare(b))
  }, [directoryTree])

  /** Files matching the current query (case-insensitive substring), capped. */
  const suggestions = useMemo(() => {
    const q = editValue.trim().toLowerCase()
    const matches = q === ''
      ? allFilePaths
      : allFilePaths.filter((p) => p.toLowerCase().includes(q))
    return matches.slice(0, 30)
  }, [allFilePaths, editValue])

  // Fetch markdown file content for preview or editing
  useEffect(() => {
    if (category !== 'markdown' || !exists || !vaultId || !token) {
      setMdContent(null)
      return
    }
    let cancelled = false
    const url = `/api/v1/vaults/${vaultId}/files?path=${encodeURIComponent(node.file)}`
    fetch(url, {
      headers: { 'Authorization': `Bearer ${token}` },
    })
      .then((res) => {
        if (!res.ok) throw new Error('fetch failed')
        return res.json()
      })
      .then((data: { content?: string }) => {
        if (!cancelled && data.content != null) {
          setMdContent(data.content)
          if (editing && !showPathEditor) setEditValue(data.content)
        }
      })
      .catch(() => {
        if (!cancelled) setMdContent(null)
      })
    return () => { cancelled = true }
  }, [category, exists, vaultId, token, node.file, editing, showPathEditor])

  // Focus the editor when entering edit mode. Deferred via rAF so focus wins
  // the race against the context menu (portal) unmounting in the same commit.
  useEffect(() => {
    if (!editing) return
    const raf = requestAnimationFrame(() => {
      if (showPathEditor) {
        inputRef.current?.focus()
        inputRef.current?.select()
      } else {
        const ta = textareaRef.current
        if (ta) {
          ta.focus()
          ta.setSelectionRange(ta.value.length, ta.value.length)
        }
      }
    })
    return () => cancelAnimationFrame(raf)
  }, [editing, showPathEditor])

  // When entering path-edit mode, seed the buffer with the current path
  // (content-edit mode is seeded by the markdown fetch effect above) and open
  // the file search dropdown.
  useEffect(() => {
    if (editing && showPathEditor) {
      setEditValue(node.file)
      setSuggestionsOpen(true)
      setHighlightIndex(-1)
    } else {
      setSuggestionsOpen(false)
    }
  }, [editing, showPathEditor, node.file])

  useEffect(() => {
    setEditValue(node.file)
  }, [node.file])

  const handleMouseDown = useCallback((e: React.MouseEvent) => {
    if (e.button !== 0 || editing) return
    onSelect(e.shiftKey)
    onDragStart(e)
  }, [editing, onSelect, onDragStart])

  const commitEdit = useCallback(() => {
    if (showPathEditor) {
      // Editing the file PATH.
      const trimmed = editValue.trim()
      if (trimmed !== node.file && onFilePathChange) {
        onFilePathChange(trimmed)
      }
    } else {
      // Editing the markdown file CONTENT.
      if (mdContent != null && editValue !== mdContent && onFileSave && vaultId && token) {
        onFileSave(node.file, editValue)
        setMdContent(editValue) // optimistic: keep preview in sync
      }
    }
    onEditEnd?.()
  }, [showPathEditor, editValue, mdContent, node.file, onFilePathChange, onFileSave, vaultId, token, onEditEnd])

  // Prevent mouse events from closing edit mode prematurely
  const handlePointerDown = useCallback((e: React.PointerEvent) => {
    e.stopPropagation()
  }, [])

  const handleKeyDown = useCallback((e: React.KeyboardEvent) => {
    // Enter commits only in the single-line path editor; in the content
    // textarea Enter must insert a newline.
    if (e.key === 'Enter' && showPathEditor) {
      e.preventDefault()
      commitEdit()
    } else if (e.key === 'Escape') {
      // Reset to original value on escape
      if (!showPathEditor && mdContent != null) {
        setEditValue(mdContent)
      } else {
        setEditValue(node.file)
      }
      onEditEnd?.()
    }
  }, [commitEdit, showPathEditor, mdContent, node.file, onEditEnd])

  /** Apply a file path picked from the search dropdown and finish editing. */
  const selectSuggestion = useCallback((path: string) => {
    setEditValue(path)
    setSuggestionsOpen(false)
    if (path !== node.file && onFilePathChange) {
      onFilePathChange(path)
    }
    onEditEnd?.()
  }, [node.file, onFilePathChange, onEditEnd])

  /** Key handling for the path search input (suggestion navigation). */
  const handlePathKeyDown = useCallback((e: React.KeyboardEvent) => {
    if (e.key === 'ArrowDown') {
      e.preventDefault()
      if (suggestions.length === 0) return
      setSuggestionsOpen(true)
      setHighlightIndex((i) => (i + 1) % suggestions.length)
    } else if (e.key === 'ArrowUp') {
      e.preventDefault()
      if (suggestions.length === 0) return
      setSuggestionsOpen(true)
      setHighlightIndex((i) => (i <= 0 ? suggestions.length - 1 : i - 1))
    } else if (e.key === 'Enter') {
      e.preventDefault()
      const picked = highlightIndex >= 0 ? suggestions[highlightIndex] : undefined
      if (picked) {
        selectSuggestion(picked)
      } else {
        commitEdit()
      }
    } else if (e.key === 'Escape') {
      e.stopPropagation()
      if (suggestionsOpen) {
        setSuggestionsOpen(false)
      } else {
        setEditValue(node.file)
        onEditEnd?.()
      }
    }
  }, [suggestions, highlightIndex, suggestionsOpen, selectSuggestion, commitEdit, node.file, onEditEnd])

  /** Render the content preview based on file category. */
  const renderContent = () => {
    if (editing) {
      if (!showPathEditor) {
        return (
          <textarea
            ref={textareaRef}
            className="canvas-node__file-md-full-editor"
            value={editValue}
            onChange={(e) => setEditValue(e.target.value)}
            onBlur={commitEdit}
            onKeyDown={handleKeyDown}
            onPointerDown={handlePointerDown}
            spellCheck={false}
            aria-label="Markdown-Inhalt bearbeiten"
          />
        )
      }
      return (
        <div className="canvas-node__file-edit canvas-node__file-path-edit">
          <label className="canvas-node__edit-label">Datei suchen:</label>
          <div className="canvas-node__file-search">
            <input
              ref={inputRef}
              className="canvas-node__file-input"
              value={editValue}
              onChange={(e) => { setEditValue(e.target.value); setSuggestionsOpen(true); setHighlightIndex(-1) }}
              onFocus={() => setSuggestionsOpen(true)}
              onBlur={commitEdit}
              onKeyDown={handlePathKeyDown}
              onPointerDown={handlePointerDown}
              placeholder="Dateiname oder PfadÔÇª"
              aria-label="Dateipfad bearbeiten"
              autoComplete="off"
            />
            {suggestionsOpen && suggestions.length > 0 && (
              <ul className="canvas-node__file-suggestions" role="listbox">
                {suggestions.map((path, i) => (
                  <li
                    key={path}
                    role="option"
                    aria-selected={i === highlightIndex}
                    className={`canvas-node__file-suggestion${i === highlightIndex ? ' canvas-node__file-suggestion--active' : ''}`}
                    onMouseDown={(e) => { e.preventDefault(); selectSuggestion(path) }}
                    onMouseEnter={() => setHighlightIndex(i)}
                    title={path}
                  >
                    <span className="canvas-node__file-suggestion-name">{path.split('/').pop()}</span>
                    {path.includes('/') && (
                      <span className="canvas-node__file-suggestion-dir">{path.slice(0, path.lastIndexOf('/'))}</span>
                    )}
                  </li>
                ))}
              </ul>
            )}
          </div>
        </div>
      )
    }

    if (!exists) {
      return (
        <div className="canvas-node__content canvas-node__file-content">
          <AlertTriangle size={16} className="canvas-node__file-icon canvas-node__file-icon--broken" />
          <span className="canvas-node__file-name canvas-node__file-name--broken">{fileName}</span>
        </div>
      )
    }

    if (category === 'image' && vaultId && token) {
      const imgSrc = `/api/v1/vaults/${vaultId}/files?path=${encodeURIComponent(node.file)}&raw=true&token=${encodeURIComponent(token)}`
      return (
        <div className="canvas-node__content canvas-node__file-preview">
          <img
            src={imgSrc}
            alt={fileName}
            className="canvas-node__file-image"
            draggable={false}
          />
        </div>
      )
    }

    if (category === 'markdown' && mdContent != null) {
      return (
        <div className="canvas-node__content canvas-node__file-preview">
          <div className="canvas-node__file-md-rendered">
            {renderSimpleMarkdown(mdContent)}
          </div>
        </div>
      )
    }

    return (
      <div className="canvas-node__content canvas-node__file-content">
        <Icon size={16} className="canvas-node__file-icon" />
        <span className="canvas-node__file-name">{fileName}</span>
        {node.subpath && <span className="canvas-node__file-subpath">{node.subpath}</span>}
      </div>
    )
  }

  return (
    <div
      className={`canvas-node canvas-node--file ${colorClass} ${selected ? 'canvas-node--selected' : ''} ${!exists ? 'canvas-node--broken' : ''} ${editing && showPathEditor ? 'canvas-node--editing-path' : ''}`}
      style={{
        left: node.x,
        top: node.y,
        width: node.width,
        height: node.height,
      }}
      data-node-id={node.id}
      onMouseDown={handleMouseDown}
      onDoubleClick={() => {
        if (exists && !editing) onFileOpen(node.file)
      }}
      role="button"
      tabIndex={0}
      aria-label={`Dateiknoten: ${fileName}`}
    >
      {renderContent()}
      <ResizeHandles visible={selected && !readOnly} onResizeStart={onResizeStart} />
      <NodeAnchors nodeId={node.id} width={node.width} height={node.height} visible={selected && !readOnly} />
    </div>
  )
})

/**
 * GroupNodeRenderer ÔÇö Renders a group node (container with label).
 * Supports drag/move and resize.
 */

import { memo, useCallback } from 'react'
import type { GroupNode } from '../../canvas/types'
import { getCanvasColorClass } from './canvas-utils'
import { useNodeDrag } from './useNodeDrag'
import { useNodeResize } from './useNodeResize'
import { ResizeHandles } from './ResizeHandles'
import { NodeAnchors } from './NodeAnchors'

export interface GroupNodeRendererProps {
  node: GroupNode
  selected: boolean
  onSelect: (additive: boolean) => void
  readOnly: boolean
}

export const GroupNodeRenderer = memo(function GroupNodeRenderer({
  node, selected, onSelect, readOnly,
}: GroupNodeRendererProps) {
  const colorClass = getCanvasColorClass(node.color)

  const { onDragStart } = useNodeDrag(node.id, readOnly)
  const { onResizeStart } = useNodeResize(node.id, readOnly)

  const handleMouseDown = useCallback((e: React.MouseEvent) => {
    if (e.button !== 0) return
    e.stopPropagation()
    onSelect(e.shiftKey)
    onDragStart(e)
  }, [onSelect, onDragStart])

  return (
    <div
      className={`canvas-node canvas-node--group ${colorClass} ${selected ? 'canvas-node--selected' : ''}`}
      style={{
        left: node.x,
        top: node.y,
        width: node.width,
        height: node.height,
      }}
      data-node-id={node.id}
      onMouseDown={handleMouseDown}
      role="group"
      aria-label={node.label ? `Gruppe: ${node.label}` : 'Gruppe'}
    >
      {node.label && (
        <span className="canvas-node__group-label">{node.label}</span>
      )}
      <ResizeHandles visible={selected && !readOnly} onResizeStart={onResizeStart} />
      <NodeAnchors nodeId={node.id} width={node.width} height={node.height} visible={selected && !readOnly} />
    </div>
  )
})

/**
 * LinkNodeRenderer ÔÇö Renders an external URL link node with iframe content preview.
 * In preview mode: shows an iframe of the URL (sandboxed).
 * In edit mode: allows editing the URL.
 * Supports drag/move, resize, and double-click to open URL externally.
 */

import { memo, useCallback, useState, useRef, useEffect } from 'react'
import { ExternalLink, Globe } from 'lucide-react'
import type { LinkNode } from '../../canvas/types'
import { getCanvasColorClass } from './canvas-utils'
import { useNodeDrag } from './useNodeDrag'
import { useNodeResize } from './useNodeResize'
import { ResizeHandles } from './ResizeHandles'
import { NodeAnchors } from './NodeAnchors'

export interface LinkNodeRendererProps {
  node: LinkNode
  selected: boolean
  onSelect: (additive: boolean) => void
  onUrlChange?: (newUrl: string) => void
  readOnly: boolean
  /** Whether this node is in edit mode. */
  editing?: boolean
  /** Callback when edit mode should end. */
  onEditEnd?: () => void
}

export const LinkNodeRenderer = memo(function LinkNodeRenderer({
  node, selected, onSelect, onUrlChange, readOnly, editing, onEditEnd,
}: LinkNodeRendererProps) {
  const colorClass = getCanvasColorClass(node.color)
  const [editUrl, setEditUrl] = useState(node.url)
  const inputRef = useRef<HTMLInputElement>(null)

  const { onDragStart } = useNodeDrag(node.id, readOnly)
  const { onResizeStart } = useNodeResize(node.id, readOnly)

  /** Extract display hostname from URL. */
  let displayUrl = node.url
  try {
    const url = new URL(node.url)
    displayUrl = url.hostname + (url.pathname !== '/' ? url.pathname : '')
  } catch {
    // Keep original if invalid URL
  }

  // Focus input when entering edit mode
  useEffect(() => {
    if (editing && inputRef.current) {
      inputRef.current.focus()
      inputRef.current.select()
    }
  }, [editing])

  // Sync editUrl when node.url changes externally
  useEffect(() => {
    if (!editing) setEditUrl(node.url)
  }, [node.url, editing])

  const handleMouseDown = useCallback((e: React.MouseEvent) => {
    if (e.button !== 0 || editing) return
    onSelect(e.shiftKey)
    onDragStart(e)
  }, [onSelect, onDragStart, editing])

  const finishEditing = useCallback(() => {
    if (editUrl.trim() && editUrl !== node.url && onUrlChange) {
      onUrlChange(editUrl.trim())
    }
    onEditEnd?.()
  }, [editUrl, node.url, onUrlChange, onEditEnd])

  const handleEditKeyDown = useCallback((e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      e.preventDefault()
      finishEditing()
    }
    if (e.key === 'Escape') {
      e.stopPropagation()
      setEditUrl(node.url)
      onEditEnd?.()
    }
  }, [finishEditing, node.url, onEditEnd])

  /** Check if the URL is valid for iframe embedding. */
  const isValidUrl = (() => {
    try {
      const url = new URL(node.url)
      return url.protocol === 'https:' || url.protocol === 'http:'
    } catch {
      return false
    }
  })()

  // ÔöÇÔöÇÔöÇ Edit Mode ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  if (editing) {
    return (
      <div
        className={`canvas-node canvas-node--link ${colorClass} ${selected ? 'canvas-node--selected' : ''}`}
        style={{ left: node.x, top: node.y, width: node.width, height: node.height }}
        data-node-id={node.id}
      >
        <div className="canvas-node__content canvas-node__link-edit">
          <label className="canvas-node__edit-label">URL:</label>
          <input
            ref={inputRef}
            type="url"
            className="canvas-node__edit-input"
            value={editUrl}
            onChange={(e) => setEditUrl(e.target.value)}
            onBlur={finishEditing}
            onKeyDown={handleEditKeyDown}
            placeholder="https://example.com"
            aria-label="URL bearbeiten"
          />
        </div>
      </div>
    )
  }

  // ÔöÇÔöÇÔöÇ Content Preview ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  // Show iframe preview for nodes larger than a threshold
  const showIframe = isValidUrl && node.width >= 200 && node.height >= 150

  return (
    <div
      className={`canvas-node canvas-node--link ${colorClass} ${selected ? 'canvas-node--selected' : ''}`}
      style={{ left: node.x, top: node.y, width: node.width, height: node.height }}
      data-node-id={node.id}
      onMouseDown={handleMouseDown}
      onDoubleClick={() => {
        window.open(node.url, '_blank', 'noopener,noreferrer')
      }}
      role="button"
      tabIndex={0}
      aria-label={`Link: ${node.url}`}
    >
      {showIframe ? (
        <div className="canvas-node__link-preview">
          <div className="canvas-node__link-preview-header" onMouseDown={handleMouseDown}>
            <Globe size={12} />
            <span className="canvas-node__link-preview-url" title={node.url}>{displayUrl}</span>
            <ExternalLink size={12} className="canvas-node__link-preview-external" />
          </div>
          <iframe
            src={node.url}
            className="canvas-node__link-iframe"
            sandbox="allow-scripts allow-same-origin allow-forms allow-popups"
            title={`Vorschau: ${displayUrl}`}
            loading="lazy"
          />
        </div>
      ) : (
        <div className="canvas-node__content canvas-node__link-content">
          <ExternalLink size={14} className="canvas-node__link-icon" />
          <span className="canvas-node__link-url" title={node.url}>{displayUrl}</span>
        </div>
      )}
      <ResizeHandles visible={selected && !readOnly && !editing} onResizeStart={onResizeStart} />
      <NodeAnchors nodeId={node.id} width={node.width} height={node.height} visible={selected && !readOnly && !editing} />
    </div>
  )
})

/**
 * NodeAnchors ÔÇö Renders draggable anchor points on node borders for edge creation.
 * When a user drags from an anchor, a preview line appears until they drop on another node's anchor.
 */

import { memo, useCallback, useRef } from 'react'
import type { EdgeSide } from '../../canvas/types'
import { useCanvasContext } from '../../state/canvasContext'
import { generateCanvasId } from './canvas-utils'

interface NodeAnchorsProps {
  nodeId: string
  width: number
  height: number
  visible: boolean
}

/** Anchor positions relative to node. */
const ANCHORS: Array<{ side: EdgeSide; style: React.CSSProperties }> = [
  { side: 'top', style: { top: -5, left: '50%', marginLeft: -5 } },
  { side: 'right', style: { top: '50%', right: -5, marginTop: -5 } },
  { side: 'bottom', style: { bottom: -5, left: '50%', marginLeft: -5 } },
  { side: 'left', style: { top: '50%', left: -5, marginTop: -5 } },
]

export const NodeAnchors = memo(function NodeAnchors({ nodeId, visible }: NodeAnchorsProps) {
  const { state, dispatch } = useCanvasContext()
  const dragStateRef = useRef<{ fromSide: EdgeSide } | null>(null)

  const handleAnchorMouseDown = useCallback((e: React.MouseEvent, side: EdgeSide) => {
    e.stopPropagation()
    e.preventDefault()
    dragStateRef.current = { fromSide: side }

    const handleMouseUp = (ev: MouseEvent) => {
      window.removeEventListener('mouseup', handleMouseUp)
      if (!dragStateRef.current) return

      // Find if we dropped on another node
      const target = ev.target as HTMLElement
      const targetNode = target.closest('[data-node-id]') as HTMLElement | null
      if (targetNode && targetNode.dataset['nodeId'] !== nodeId) {
        const toNodeId = targetNode.dataset['nodeId']!
        // Determine the target side based on relative position
        const rect = targetNode.getBoundingClientRect()
        const relX = ev.clientX - rect.left
        const relY = ev.clientY - rect.top
        const toSide = getClosestSide(relX, relY, rect.width, rect.height)

        dispatch({
          type: 'ADD_EDGE',
          payload: {
            edge: {
              id: generateCanvasId(),
              fromNode: nodeId,
              fromSide: dragStateRef.current.fromSide,
              toNode: toNodeId,
              toSide,
              toEnd: 'arrow',
            },
          },
        })
      }
      dragStateRef.current = null
    }

    window.addEventListener('mouseup', handleMouseUp)
  }, [nodeId, state, dispatch]) // eslint-disable-line react-hooks/exhaustive-deps

  if (!visible) return null

  return (
    <>
      {ANCHORS.map(({ side, style }) => (
        <div
          key={side}
          className="canvas-node__anchor"
          style={{ ...style, position: 'absolute' }}
          onMouseDown={(e) => handleAnchorMouseDown(e, side)}
          title={`Verbindung von ${side}`}
          role="button"
          aria-label={`Verbindungsanker ${side}`}
        />
      ))}
    </>
  )
})

/** Determine closest side based on position within a rectangle. */
function getClosestSide(x: number, y: number, width: number, height: number): EdgeSide {
  const distances = {
    top: y,
    bottom: height - y,
    left: x,
    right: width - x,
  }
  let min: EdgeSide = 'top'
  let minDist = Infinity
  for (const [side, dist] of Object.entries(distances)) {
    if (dist < minDist) {
      minDist = dist
      min = side as EdgeSide
    }
  }
  return min
}

/**
 * ResizeHandles ÔÇö Renders 8 resize handles around a selected node.
 */

import { memo } from 'react'
import type { ResizeHandle } from './useNodeResize'

interface ResizeHandlesProps {
  visible: boolean
  onResizeStart: (e: React.MouseEvent, handle: ResizeHandle) => void
}

const HANDLES: Array<{ handle: ResizeHandle; style: React.CSSProperties; cursor: string }> = [
  { handle: 'nw', style: { top: -4, left: -4 }, cursor: 'nw-resize' },
  { handle: 'n', style: { top: -4, left: '50%', marginLeft: -4 }, cursor: 'n-resize' },
  { handle: 'ne', style: { top: -4, right: -4 }, cursor: 'ne-resize' },
  { handle: 'e', style: { top: '50%', right: -4, marginTop: -4 }, cursor: 'e-resize' },
  { handle: 'se', style: { bottom: -4, right: -4 }, cursor: 'se-resize' },
  { handle: 's', style: { bottom: -4, left: '50%', marginLeft: -4 }, cursor: 's-resize' },
  { handle: 'sw', style: { bottom: -4, left: -4 }, cursor: 'sw-resize' },
  { handle: 'w', style: { top: '50%', left: -4, marginTop: -4 }, cursor: 'w-resize' },
]

export const ResizeHandles = memo(function ResizeHandles({ visible, onResizeStart }: ResizeHandlesProps) {
  if (!visible) return null

  return (
    <>
      {HANDLES.map(({ handle, style, cursor }) => (
        <div
          key={handle}
          className="canvas-node__resize-handle"
          style={{ ...style, cursor, position: 'absolute' }}
          onMouseDown={(e) => onResizeStart(e, handle)}
          role="separator"
          aria-label={`Gr├Â├ƒe ├ñndern ${handle}`}
        />
      ))}
    </>
  )
})

import { useState, useRef, useCallback } from 'react'
import { List, Link, Tag, FileText, Search, icons } from 'lucide-react'
import type { LucideIcon } from 'lucide-react'
import { isPluginViewId, getPluginViewType } from '../../state/contextPanelState'
import type { ContextPanelViewId, BuiltinViewId } from '../../state/contextPanelState'
import './ContextPanelTabBar.css'

/** Tab metadata mapping built-in view IDs to icons and labels. */
const TAB_CONFIG: Record<BuiltinViewId, { icon: typeof List; label: string }> = {
  outline: { icon: List, label: 'Gliederung' },
  links: { icon: Link, label: 'Links' },
  tags: { icon: Tag, label: 'Tags' },
  properties: { icon: FileText, label: 'Eigenschaften' },
  search: { icon: Search, label: 'Suche' },
}

/** Known Obsidian icon name ÔåÆ Lucide key mappings. */
const OBSIDIAN_ICON_MAP: Record<string, string> = {
  'calendar-with-checkmark': 'CalendarCheck',
  'calendar': 'Calendar',
  'lucide-calendar': 'Calendar',
  'file-text': 'FileText',
  'folder': 'Folder',
  'search': 'Search',
  'settings': 'Settings',
  'star': 'Star',
  'trash': 'Trash2',
  'link': 'Link',
  'eye': 'Eye',
  'pencil': 'Pencil',
  'clock': 'Clock',
  'check': 'Check',
  'list': 'List',
  'hash': 'Hash',
  'tag': 'Tag',
  'book': 'Book',
  'image': 'Image',
  'code': 'Code',
  'quote': 'Quote',
  'table': 'Table',
}

/** Resolve an Obsidian icon name to a Lucide React component, or null if not found. */
function resolvePluginIcon(iconName: string): LucideIcon | null {
  const mapped = OBSIDIAN_ICON_MAP[iconName]
  if (mapped && mapped in icons) {
    return icons[mapped as keyof typeof icons]
  }
  // Generic: kebab-case ÔåÆ PascalCase
  const pascalCase = iconName.split('-').map(p => p.charAt(0).toUpperCase() + p.slice(1)).join('')
  if (pascalCase in icons) {
    return icons[pascalCase as keyof typeof icons]
  }
  return null
}

/** Plugin view metadata provided externally for label/icon resolution. */
export interface PluginViewMeta {
  viewType: string
  displayText: string
  icon: string
}

export interface ContextPanelTabBarProps {
  tabs: ContextPanelViewId[]
  activeTab: ContextPanelViewId
  sectionId?: string
  onTabClick: (viewId: ContextPanelViewId) => void
  onTabReorder: (newOrder: ContextPanelViewId[]) => void
  onTabSplit: (viewId: ContextPanelViewId) => void
  onTabReceive?: (viewId: ContextPanelViewId, targetSectionId: string) => void
  panelWidth: number
  /** Metadata for plugin views (icon + label lookup). Keyed by viewType. */
  pluginViewMeta?: Map<string, PluginViewMeta>
}

/**
 * Tab bar for the context panel with drag-and-drop reordering and split support.
 * Renders both built-in and plugin tabs from the unified tabs list.
 * Shows only icons with labels as tooltips on hover.
 */
export function ContextPanelTabBar({
  tabs,
  activeTab,
  sectionId,
  onTabClick,
  onTabReorder,
  onTabSplit,
  onTabReceive,
  panelWidth: _panelWidth,  
  pluginViewMeta,
}: ContextPanelTabBarProps) {
  const [draggedTab, setDraggedTab] = useState<ContextPanelViewId | null>(null)
  const [dropIndex, setDropIndex] = useState<number | null>(null)
  const tabBarRef = useRef<HTMLDivElement>(null)

  // Tabs are always draggable in split mode (sectionId provided) or when multiple tabs exist
  const isDraggable = sectionId !== undefined || tabs.length > 1

  const handleDragStart = useCallback((e: React.DragEvent, viewId: ContextPanelViewId) => {
    if (!isDraggable) {
      e.preventDefault()
      return
    }
    setDraggedTab(viewId)
    e.dataTransfer.effectAllowed = 'move'
    e.dataTransfer.setData('text/plain', viewId)
  }, [isDraggable])

  const handleDragOver = useCallback((e: React.DragEvent) => {
    e.preventDefault()
    e.dataTransfer.dropEffect = 'move'

    if (!tabBarRef.current) return

    const tabBarRect = tabBarRef.current.getBoundingClientRect()

    // Detect if dragging below the tab bar (30px threshold for split) ÔÇö only for local drags
    if (draggedTab && e.clientY > tabBarRect.bottom + 30) {
      setDropIndex(null)
      return
    }

    // Detect if outside tab bar boundaries horizontally or above
    if (
      e.clientX < tabBarRect.left ||
      e.clientX > tabBarRect.right ||
      e.clientY < tabBarRect.top ||
      e.clientY > tabBarRect.bottom
    ) {
      setDropIndex(null)
      return
    }

    // Calculate drop index based on pointer position relative to tab elements
    const tabElements = tabBarRef.current.querySelectorAll('[data-tab-id]')
    let newDropIndex = tabs.length

    for (let i = 0; i < tabElements.length; i++) {
      const tabEl = tabElements[i] as HTMLElement
      const rect = tabEl.getBoundingClientRect()
      const midX = rect.left + rect.width / 2

      if (e.clientX < midX) {
        newDropIndex = i
        break
      }
    }

    // Don't show insertion line at the dragged tab's current position or adjacent
    if (draggedTab) {
      const draggedIndex = tabs.indexOf(draggedTab)
      if (newDropIndex === draggedIndex || newDropIndex === draggedIndex + 1) {
        setDropIndex(null)
      } else {
        setDropIndex(newDropIndex)
      }
    } else {
      // Cross-section drag ÔÇö always show insertion indicator
      setDropIndex(newDropIndex)
    }
  }, [draggedTab, tabs])

  const handleDragLeave = useCallback((e: React.DragEvent) => {
    // Only reset if actually leaving the tab bar (not entering a child)
    if (!tabBarRef.current?.contains(e.relatedTarget as Node)) {
      setDropIndex(null)
    }
  }, [])

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault()
    e.stopPropagation()

    const droppedViewId = e.dataTransfer.getData('text/plain') as ContextPanelViewId

    if (!tabBarRef.current) {
      setDraggedTab(null)
      setDropIndex(null)
      return
    }

    const tabBarRect = tabBarRef.current.getBoundingClientRect()

    // Check if dropped 30px below the tab bar ÔåÆ split
    if (draggedTab && e.clientY > tabBarRect.bottom + 30) {
      onTabSplit(draggedTab)
      setDraggedTab(null)
      setDropIndex(null)
      return
    }

    // Check if dropped outside tab bar boundaries ÔåÆ no-op
    if (
      e.clientX < tabBarRect.left ||
      e.clientX > tabBarRect.right ||
      e.clientY < tabBarRect.top ||
      e.clientY > tabBarRect.bottom
    ) {
      setDraggedTab(null)
      setDropIndex(null)
      return
    }

    // If the dropped tab is from another section (not in our tabs), handle cross-section move
    if (droppedViewId && !tabs.includes(droppedViewId) && sectionId && onTabReceive) {
      onTabReceive(droppedViewId, sectionId)
      setDraggedTab(null)
      setDropIndex(null)
      return
    }

    // Same-section reorder
    if (!draggedTab) {
      setDraggedTab(null)
      setDropIndex(null)
      return
    }

    // Calculate final drop index
    const tabElements = tabBarRef.current.querySelectorAll('[data-tab-id]')
    let finalDropIndex = tabs.length

    for (let i = 0; i < tabElements.length; i++) {
      const tabEl = tabElements[i] as HTMLElement
      const rect = tabEl.getBoundingClientRect()
      const midX = rect.left + rect.width / 2

      if (e.clientX < midX) {
        finalDropIndex = i
        break
      }
    }

    // Perform reorder
    const draggedIndex = tabs.indexOf(draggedTab)
    if (draggedIndex !== -1 && finalDropIndex !== draggedIndex && finalDropIndex !== draggedIndex + 1) {
      const newOrder = [...tabs]
      newOrder.splice(draggedIndex, 1)
      // Adjust index after removal
      const insertAt = finalDropIndex > draggedIndex ? finalDropIndex - 1 : finalDropIndex
      newOrder.splice(insertAt, 0, draggedTab)
      onTabReorder(newOrder)
    }

    setDraggedTab(null)
    setDropIndex(null)
  }, [draggedTab, tabs, sectionId, onTabReorder, onTabSplit, onTabReceive])

  const handleDragEnd = useCallback(() => {
    setDraggedTab(null)
    setDropIndex(null)
  }, [])

  /** Render a single tab (built-in or plugin). */
  function renderTab(viewId: ContextPanelViewId, index: number) {
    const isActive = viewId === activeTab
    const isDragging = viewId === draggedTab
    const showInsertBefore = dropIndex === index

    if (isPluginViewId(viewId)) {
      const viewType = getPluginViewType(viewId)
      const meta = pluginViewMeta?.get(viewType)
      const label = meta?.displayText ?? viewType
      const PluginIcon = meta?.icon ? resolvePluginIcon(meta.icon) : null

      return (
        <div key={viewId} className="context-panel-tab-wrapper">
          {showInsertBefore && (
            <div className="context-panel-tab-insert-line" aria-hidden="true" />
          )}
          <button
            type="button"
            role="tab"
            data-tab-id={viewId}
            aria-selected={isActive}
            aria-label={label}
            title={label}
            className={`context-panel-tab${isActive ? ' context-panel-tab--active' : ''}${isDragging ? ' context-panel-tab--dragging' : ''}`}
            onClick={() => onTabClick(viewId)}
            draggable={isDraggable}
            onDragStart={(e) => handleDragStart(e, viewId)}
            onDragEnd={handleDragEnd}
          >
            {PluginIcon ? <PluginIcon size={14} className="context-panel-tab-icon" /> : <span className="context-panel-tab-icon">{viewType}</span>}
          </button>
        </div>
      )
    }

    // Built-in tab
    const config = TAB_CONFIG[viewId as BuiltinViewId]
    if (!config) return null
    const Icon = config.icon

    return (
      <div key={viewId} className="context-panel-tab-wrapper">
        {showInsertBefore && (
          <div className="context-panel-tab-insert-line" aria-hidden="true" />
        )}
        <button
          type="button"
          role="tab"
          data-tab-id={viewId}
          aria-selected={isActive}
          aria-label={config.label}
          title={config.label}
          className={`context-panel-tab${isActive ? ' context-panel-tab--active' : ''}${isDragging ? ' context-panel-tab--dragging' : ''}`}
          onClick={() => onTabClick(viewId)}
          draggable={isDraggable}
          onDragStart={(e) => handleDragStart(e, viewId)}
          onDragEnd={handleDragEnd}
        >
          <Icon size={14} className="context-panel-tab-icon" />
        </button>
      </div>
    )
  }

  return (
    <div
      ref={tabBarRef}
      className="context-panel-tab-bar context-panel-tab-bar--icon-only"
      role="tablist"
      aria-label="Kontext-Panel Ansichten"
      onDragOver={handleDragOver}
      onDragLeave={handleDragLeave}
      onDrop={handleDrop}
    >
      {tabs.map((viewId, index) => renderTab(viewId, index))}
      {dropIndex === tabs.length && (
        <div className="context-panel-tab-wrapper">
          <div className="context-panel-tab-insert-line" aria-hidden="true" />
        </div>
      )}
    </div>
  )
}

/**
 * SplitSectionContainer component for the Context Panel.
 *
 * Renders split sections as vertically stacked areas with resize handles.
 * Each section displays its own TabBar (if it has multiple views) and
 * the active view content via the renderView prop.
 *
 * Supports:
 * - Drag-to-resize between sections (4px handle, 80px minimum height)
 * - Drop indicator when a tab is dragged below the TabBar threshold (30px)
 * - Section merge: removes empty sections when last view is dragged out
 * - Equal height redistribution among remaining sections after removal
 */

import { useRef, useState, useCallback, useEffect } from 'react'
import { ContextPanelTabBar } from './ContextPanelTabBar'
import type { SplitSection, ContextPanelViewId } from '../../state/contextPanelState'
import './SplitSectionContainer.css'

// ÔöÇÔöÇÔöÇ Constants ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

/** Minimum section height in pixels. */
const MIN_SECTION_HEIGHT = 80

// ÔöÇÔöÇÔöÇ Props ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

export interface SplitSectionContainerProps {
  /** Array of split sections to render. */
  sections: SplitSection[]
  /** Panel width in pixels (passed to TabBar for responsive behavior). */
  panelWidth: number
  /** Panel body height in pixels (used to compute minimum height fractions during resize). */
  panelHeight: number
  /** Callback when a tab is clicked within a section. */
  onTabClick: (sectionId: string, viewId: ContextPanelViewId) => void
  /** Callback when tabs are reordered within a section. */
  onTabReorder: (sectionId: string, newOrder: ContextPanelViewId[]) => void
  /** Callback when a tab is split into a new section. */
  onTabSplit: (viewId: ContextPanelViewId) => void
  /** Callback when a tab is moved from one section to another. */
  onTabMove: (viewId: ContextPanelViewId, targetSectionId: string) => void
  /** Callback when section heights change (array of fractions summing to 1). */
  onResize: (heightFractions: number[]) => void
  /** Render function that returns the view component for a given viewId. */
  renderView: (viewId: ContextPanelViewId) => React.ReactNode
  /** Metadata for plugin views (icon + label lookup). Keyed by viewType. */
  pluginViewMeta?: Map<string, { viewType: string; displayText: string; icon: string }>
}

// ÔöÇÔöÇÔöÇ Component ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

/**
 * Renders split sections of the context panel as vertically stacked areas.
 * Each section has its own TabBar (if multiple views) and is separated by
 * a 4px resize handle from adjacent sections.
 */
export function SplitSectionContainer({
  sections,
  panelWidth,
  panelHeight,
  onTabClick,
  onTabReorder,
  onTabSplit,
  onTabMove,
  onResize,
  renderView,
  pluginViewMeta,
}: SplitSectionContainerProps) {
  const containerRef = useRef<HTMLDivElement>(null)
  const [resizingIndex, setResizingIndex] = useState<number | null>(null)
  const [showDropIndicator, setShowDropIndicator] = useState(false)
  const startYRef = useRef(0)
  const startFractionsRef = useRef<number[]>([])

  // ÔöÇÔöÇÔöÇ Resize Logic ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

  /** Handle mousedown on a resize handle between sections. */
  const handleResizeStart = useCallback((e: React.MouseEvent, handleIndex: number) => {
    e.preventDefault()
    setResizingIndex(handleIndex)
    startYRef.current = e.clientY
    startFractionsRef.current = sections.map((s) => s.heightFraction)
  }, [sections])

  /** Handle mouse movement during resize. Enforces 80px minimum height. */
  useEffect(() => {
    if (resizingIndex === null) return

    const handleMouseMove = (e: MouseEvent) => {
      const containerHeight = panelHeight
      if (containerHeight <= 0) return

      const deltaY = e.clientY - startYRef.current
      const deltaFraction = deltaY / containerHeight

      const fractions = [...startFractionsRef.current]
      const topFraction = fractions[resizingIndex]
      const bottomFraction = fractions[resizingIndex + 1]

      if (topFraction === undefined || bottomFraction === undefined) return

      // Calculate new fractions
      let newTop = topFraction + deltaFraction
      let newBottom = bottomFraction - deltaFraction

      // Enforce minimum height constraint (80px)
      const minFraction = MIN_SECTION_HEIGHT / containerHeight

      if (newTop < minFraction) {
        newTop = minFraction
        newBottom = topFraction + bottomFraction - minFraction
      }
      if (newBottom < minFraction) {
        newBottom = minFraction
        newTop = topFraction + bottomFraction - minFraction
      }

      fractions[resizingIndex] = newTop
      fractions[resizingIndex + 1] = newBottom

      onResize(fractions)
    }

    const handleMouseUp = () => {
      setResizingIndex(null)
    }

    document.addEventListener('mousemove', handleMouseMove)
    document.addEventListener('mouseup', handleMouseUp)

    return () => {
      document.removeEventListener('mousemove', handleMouseMove)
      document.removeEventListener('mouseup', handleMouseUp)
    }
  }, [resizingIndex, onResize, panelHeight])

  // ÔöÇÔöÇÔöÇ Drop Indicator Logic ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

  /** Handle dragover on the container body to show drop indicator for tab split. */
  const handleDragOver = useCallback((e: React.DragEvent) => {
    e.preventDefault()
    e.dataTransfer.dropEffect = 'move'

    // Show drop indicator when dragging in the lower portion of the container
    if (containerRef.current) {
      const rect = containerRef.current.getBoundingClientRect()
      const isInDropZone = e.clientY > rect.top + rect.height * 0.7
      setShowDropIndicator(isInDropZone)
    }
  }, [])

  const handleDragLeave = useCallback((e: React.DragEvent) => {
    if (!containerRef.current?.contains(e.relatedTarget as Node)) {
      setShowDropIndicator(false)
    }
  }, [])

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault()
    setShowDropIndicator(false)

    // The tab split is triggered via the dataTransfer payload set by ContextPanelTabBar
    const viewId = e.dataTransfer.getData('text/plain') as ContextPanelViewId
    if (viewId) {
      onTabSplit(viewId)
    }
  }, [onTabSplit])

  // ÔöÇÔöÇÔöÇ Render ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

  return (
    <div
      ref={containerRef}
      className={`split-section-container${resizingIndex !== null ? ' split-section-container--resizing' : ''}`}
      onDragOver={handleDragOver}
      onDragLeave={handleDragLeave}
      onDrop={handleDrop}
    >
      {sections.map((section, index) => {
        const heightPercent = section.heightFraction * 100

        return (
          <div key={section.id} className="split-section-wrapper">
            {/* Resize handle between sections (not before the first one) */}
            {index > 0 && (
              <div
                className={`split-section-resize-handle${resizingIndex === index - 1 ? ' split-section-resize-handle--active' : ''}`}
                onMouseDown={(e) => handleResizeStart(e, index - 1)}
                role="separator"
                aria-orientation="horizontal"
                aria-label="Bereichsgr├Â├ƒe anpassen"
              />
            )}

            <div
              className="split-section"
              style={{ height: `${heightPercent}%` }}
              data-section-id={section.id}
            >
              {/* Section TabBar ÔÇö always shown in split mode, hidden in single-section mode */}
              {sections.length > 1 && (
                <ContextPanelTabBar
                  tabs={section.viewIds}
                  activeTab={section.activeViewId}
                  sectionId={section.id}
                  onTabClick={(viewId) => onTabClick(section.id, viewId)}
                  onTabReorder={(newOrder) => onTabReorder(section.id, newOrder)}
                  onTabSplit={onTabSplit}
                  onTabReceive={onTabMove}
                  panelWidth={panelWidth}
                  pluginViewMeta={pluginViewMeta}
                />
              )}

              {/* Section content ÔÇö renders the active view */}
              <div className="split-section-content">
                {renderView(section.activeViewId)}
              </div>
            </div>
          </div>
        )
      })}

      {/* Drop indicator for creating a new section at the bottom */}
      {showDropIndicator && (
        <div className="split-section-drop-indicator" aria-hidden="true">
          <div className="split-section-drop-indicator-line" />
        </div>
      )}
    </div>
  )
}

import React from 'react'
import { ChevronRight, ChevronDown, Folder, FolderOpen, Star } from 'lucide-react'
import { getFileIcon, getFileIconClass, getDisplayName } from '../../utils/fileIcons'
import { InlineInput } from '../InlineInput'
import { validateFileName, normalizeFileName, getSelectionRange } from '../../utils/fileValidation'
import type { DirectoryTree } from '../../types'
import type { DragState, ExternalDropState, InlineInputState } from './types'

/**
 * Props for the recursive TreeNode component.
 */
export interface TreeNodeProps {
  node: DirectoryTree
  selectedFilePath: string | null
  expandedPaths: Set<string>
  onToggleFolder: (path: string) => void
  onSelectFile: (path: string, name: string) => void
  dragState: DragState
  externalDropState: ExternalDropState
  permission: 'owner' | 'read' | 'write' | undefined
  vaultId: string
  onDragStart: (e: React.DragEvent<HTMLDivElement>, nodePath: string, nodeType: 'file' | 'directory', vaultId: string) => void
  onDragEnd: (e: React.DragEvent<HTMLDivElement>) => void
  onDragOver: (e: React.DragEvent<HTMLDivElement>, nodePath: string, vaultId: string) => void
  onDragLeave: (e: React.DragEvent<HTMLDivElement>, nodePath: string, vaultId: string) => void
  onDrop: (e: React.DragEvent<HTMLDivElement>, targetPath: string, vaultId: string) => void
  onContextMenu: (e: React.MouseEvent, node: DirectoryTree, vaultId: string) => void
  inlineInputState: InlineInputState
  onInlineConfirm: (value: string) => void
  onInlineCancel: () => void
  isFavorite: (path: string) => boolean
  onToggleFavorite: (path: string) => void
}

/**
 * Renders a single node in the directory tree.
 * Directories are rendered as collapsible folders; files as clickable items.
 * Supports drag & drop for moving files/folders.
 * Shows InlineInput when creating a new file or renaming.
 */
export function TreeNode({
  node,
  selectedFilePath,
  expandedPaths,
  onToggleFolder,
  onSelectFile,
  dragState,
  externalDropState,
  permission,
  vaultId,
  onDragStart,
  onDragEnd,
  onDragOver,
  onDragLeave,
  onDrop,
  onContextMenu,
  inlineInputState,
  onInlineConfirm,
  onInlineCancel,
  isFavorite,
  onToggleFavorite,
}: TreeNodeProps) {
  const isDirectory = node.type === 'directory'
  const isExpanded = expandedPaths.has(`${vaultId}::${node.path}`)
  const isSelected = !isDirectory && node.path === selectedFilePath
  const isDragged = dragState.draggedPath === node.path && dragState.draggedVaultId === vaultId
  const canDrag = permission !== 'read' && !dragState.isMoving

  // Check if this node is being renamed
  const isRenaming = inlineInputState.visible
    && inlineInputState.mode === 'rename'
    && inlineInputState.node?.path === node.path
    && inlineInputState.vaultId === vaultId

  if (isDirectory) {
    const isValidTarget = dragState.draggedPath !== null && dragState.draggedVaultId === vaultId && dragState.validTargets.has(node.path)
    const isExternalDropTarget = externalDropState.targetPath === node.path && externalDropState.targetVaultId === vaultId

    // Check if new file/folder/canvas inline input should appear in this directory
    const showNewFileInput = inlineInputState.visible
      && (inlineInputState.mode === 'newFile' || inlineInputState.mode === 'newFolder' || inlineInputState.mode === 'newCanvas')
      && inlineInputState.parentPath === node.path
      && inlineInputState.vaultId === vaultId

    return (
      <li className="tree-node tree-node--directory" data-path={node.path}>
        <div
          className={`tree-node-row${isDragged ? ' tree-node--dragging' : ''}${isValidTarget || isExternalDropTarget ? ' tree-node--drop-target' : ''}`}
          draggable={canDrag}
          onDragStart={(e) => onDragStart(e, node.path, node.type, vaultId)}
          onDragEnd={onDragEnd}
          onDragOver={(e) => onDragOver(e, node.path, vaultId)}
          onDragLeave={(e) => onDragLeave(e, node.path, vaultId)}
          onDrop={(e) => onDrop(e, node.path, vaultId)}
          onContextMenu={(e) => onContextMenu(e, node, vaultId)}
        >
          <button
            type="button"
            className="tree-node-toggle"
            aria-expanded={isExpanded}
            onClick={() => onToggleFolder(`${vaultId}::${node.path}`)}
            title={node.path}
          >
            <span className="tree-node-chevron" aria-hidden="true">
              {isExpanded ? <ChevronDown size={12} /> : <ChevronRight size={12} />}
            </span>
            {isExpanded ? <FolderOpen size={14} style={{ flexShrink: 0, color: 'var(--accent)' }} /> : <Folder size={14} style={{ flexShrink: 0, color: 'var(--sidebar-text)' }} />}
            {isRenaming ? (
              <InlineInput
                initialValue={node.name}
                selectRange={getSelectionRange(node.name, true)}
                onConfirm={onInlineConfirm}
                onCancel={onInlineCancel}
                validate={(value) => validateFileName(value, 255)}
              />
            ) : (
              <span className="tree-node-name">
                {node.name}
                {node.itemCount != null && (
                  <span className="tree-node-count"> ({node.itemCount})</span>
                )}
              </span>
            )}
          </button>
        </div>
        {isExpanded && node.children && node.children.length > 0 && (
          <ul className="tree-node-children" role="group">
            {node.children.map((child) => (
              <TreeNode
                key={child.path}
                node={child}
                selectedFilePath={selectedFilePath}
                expandedPaths={expandedPaths}
                onToggleFolder={onToggleFolder}
                onSelectFile={onSelectFile}
                dragState={dragState}
                externalDropState={externalDropState}
                permission={permission}
                vaultId={vaultId}
                onDragStart={onDragStart}
                onDragEnd={onDragEnd}
                onDragOver={onDragOver}
                onDragLeave={onDragLeave}
                onDrop={onDrop}
                onContextMenu={onContextMenu}
                inlineInputState={inlineInputState}
                onInlineConfirm={onInlineConfirm}
                onInlineCancel={onInlineCancel}
                isFavorite={isFavorite}
                onToggleFavorite={onToggleFavorite}
              />
            ))}
          </ul>
        )}
        {showNewFileInput && (
          <ul className="tree-node-children" role="group">
            <li className="tree-node tree-node--file">
              <div className="tree-node-row">
                <InlineInput
                  initialValue=""
                  onConfirm={onInlineConfirm}
                  onCancel={onInlineCancel}
                  validate={(value) => {
                    if (inlineInputState.mode === 'newCanvas') {
                      const name = value.trim().endsWith('.canvas') ? value.trim() : `${value.trim()}.canvas`
                      return validateFileName(name)
                    }
                    const normalized = normalizeFileName(value)
                    return validateFileName(normalized)
                  }}
                />
              </div>
            </li>
          </ul>
        )}
      </li>
    )
  }

  const FileIconComponent = getFileIcon(node.name)
  const fileIconClass = getFileIconClass(node.name)
  const favorited = isFavorite(node.path)

  return (
    <li className="tree-node tree-node--file" data-path={node.path}>
      <div
        className={`tree-node-row${isDragged ? ' tree-node--dragging' : ''}`}
        draggable={canDrag}
        onDragStart={(e) => onDragStart(e, node.path, node.type, vaultId)}
        onDragEnd={onDragEnd}
        onContextMenu={(e) => onContextMenu(e, node, vaultId)}
      >
        {isRenaming ? (
          <div style={{ display: 'flex', alignItems: 'center', gap: 5, flex: 1 }}>
            {React.createElement(FileIconComponent, { size: 13, className: fileIconClass, style: { flexShrink: 0 } })}
            <InlineInput
              initialValue={node.name}
              selectRange={getSelectionRange(node.name, false)}
              onConfirm={onInlineConfirm}
              onCancel={onInlineCancel}
              validate={(value) => validateFileName(value, 255)}
            />
          </div>
        ) : (
          <button
            type="button"
            className={`tree-node-file${isSelected ? ' tree-node-file--selected' : ''}`}
            aria-current={isSelected ? 'true' : undefined}
            onClick={() => onSelectFile(node.path, node.name)}
            title={node.path}
            style={{ display: 'flex', alignItems: 'center', gap: 5 }}
          >
            {React.createElement(FileIconComponent, { size: 13, className: fileIconClass, style: { flexShrink: 0 } })}
            <span className="tree-node-file-name">{getDisplayName(node.name)}</span>
            <span
              className={`tree-node-star${favorited ? ' tree-node-star--active' : ''}`}
              onClick={(e) => { e.stopPropagation(); onToggleFavorite(node.path) }}
              role="button"
              aria-label={favorited ? 'Favorit entfernen' : 'Als Favorit markieren'}
              tabIndex={-1}
            >
              <Star size={12} />
            </span>
          </button>
        )}
      </div>
    </li>
  )
}

/**
 * PluginDetailPanel ÔÇö Modal overlay showing plugin details and README.md.
 *
 * Fetches the plugin's README from GitHub via the backend proxy,
 * renders it as HTML using a simple markdown-to-HTML conversion,
 * and provides install/update actions.
 */
import { useState, useEffect, useCallback } from 'react'
import { createPortal } from 'react-dom'
import { X, Loader2, ExternalLink } from 'lucide-react'
import type { IApiClient } from '../../api'
import { useTranslation } from '../../i18n'
import { extractErrorMessage } from '../../utils/error'
import type { PluginStoreDisplayEntry } from './types'

/** Props for the PluginDetailPanel component. */
export interface PluginDetailPanelProps {
  /** Plugin data to display. */
  plugin: PluginStoreDisplayEntry
  /** API client for fetching README and performing actions. */
  apiClient: IApiClient
  /** Called when user clicks install. */
  onInstall: (pluginId: string, repo: string) => void
  /** Called when user clicks update. */
  onUpdate: (pluginId: string) => void
  /** Called when user closes the panel. */
  onClose: () => void
}

/**
 * Modal panel that shows full plugin details including the README.md
 * fetched from GitHub.
 */
export function PluginDetailPanel({
  plugin,
  apiClient,
  onInstall,
  onUpdate,
  onClose,
}: PluginDetailPanelProps) {
  const { t } = useTranslation()
  const [readme, setReadme] = useState<string | null>(null)
  const [readmeLoading, setReadmeLoading] = useState(true)
  const [readmeError, setReadmeError] = useState<string | null>(null)

  // Fetch README on mount
  useEffect(() => {
    let cancelled = false

    async function loadReadme() {
      setReadmeLoading(true)
      setReadmeError(null)
      try {
        const content = await apiClient.getPluginReadme(plugin.repo)
        if (!cancelled) {
          setReadme(content)
        }
      } catch (err: unknown) {
        if (!cancelled) {
          setReadmeError(extractErrorMessage(err, t('pluginStore.detailReadmeError')))
        }
      } finally {
        if (!cancelled) {
          setReadmeLoading(false)
        }
      }
    }

    void loadReadme()
    return () => { cancelled = true }
  }, [apiClient, plugin.repo, t])

  // Close on Escape key
  useEffect(() => {
    function handleKeyDown(e: KeyboardEvent) {
      if (e.key === 'Escape') {
        onClose()
      }
    }
    document.addEventListener('keydown', handleKeyDown)
    return () => document.removeEventListener('keydown', handleKeyDown)
  }, [onClose])

  // Close on overlay click (not panel itself)
  const handleOverlayClick = useCallback((e: React.MouseEvent) => {
    if (e.target === e.currentTarget) {
      onClose()
    }
  }, [onClose])

  const isBusy = plugin.status === 'installing' || plugin.status === 'updating'
  const isDesktopOnly = plugin.status === 'desktop-only'

  return createPortal(
    <div className="plugin-detail-overlay" onClick={handleOverlayClick} role="dialog" aria-modal="true">
      <div className="plugin-detail-panel">
        {/* Header */}
        <div className="plugin-detail-panel__header">
          <div className="plugin-detail-panel__header-info">
            <span className="plugin-detail-panel__title">{plugin.name}</span>
            <span className="plugin-detail-panel__subtitle">
              {t('pluginStore.detailBy')} {plugin.author}
              {plugin.installedVersion && ` ┬À ${t('pluginStore.detailVersion')} ${plugin.installedVersion}`}
            </span>
          </div>
          <button
            className="plugin-detail-panel__close"
            onClick={onClose}
            aria-label={t('pluginStore.detailClose')}
          >
            <X size={18} />
          </button>
        </div>

        {/* Actions bar */}
        <div className="plugin-detail-panel__actions">
          {plugin.hasUpdate && (
            <button
              className="plugin-store-card__button plugin-store-card__button--update"
              disabled={isBusy}
              onClick={() => onUpdate(plugin.id)}
            >
              {isBusy && <Loader2 size={14} className="spin" aria-hidden="true" />}
              {t('pluginStore.update')}
            </button>
          )}
          {!plugin.isInstalled && !isDesktopOnly && (
            <button
              className="plugin-store-card__button plugin-store-card__button--install"
              disabled={isBusy}
              onClick={() => onInstall(plugin.id, plugin.repo)}
            >
              {isBusy && <Loader2 size={14} className="spin" aria-hidden="true" />}
              {t('pluginStore.install')}
            </button>
          )}
          {plugin.isInstalled && !plugin.hasUpdate && (
            <span className="plugin-store-card__badge plugin-store-card__badge--installed">
              {t('pluginStore.installed')}
            </span>
          )}
          <a
            className="plugin-store-card__release-link"
            href={`https://github.com/${plugin.repo}`}
            target="_blank"
            rel="noopener noreferrer"
          >
            <ExternalLink size={12} aria-hidden="true" />
            {t('pluginStore.detailRepo')}
          </a>
        </div>

        {/* README content */}
        <div className="plugin-detail-panel__content">
          {readmeLoading && (
            <div className="plugin-detail-panel__loading">
              <Loader2 size={18} className="spin" aria-hidden="true" />
              <span>{t('pluginStore.detailLoadingReadme')}</span>
            </div>
          )}
          {readmeError && (
            <div className="plugin-detail-panel__error">
              {readmeError}
            </div>
          )}
          {!readmeLoading && !readmeError && readme !== null && (
            <div
              className="plugin-detail-panel__readme"
              dangerouslySetInnerHTML={{ __html: markdownToHtml(readme, plugin.repo) }}
            />
          )}
          {!readmeLoading && !readmeError && readme === null && (
            <div className="plugin-detail-panel__error">
              {t('pluginStore.detailNoReadme')}
            </div>
          )}
        </div>
      </div>
    </div>,
    document.body,
  )
}

/**
 * Simple Markdown ÔåÆ HTML conversion for README display.
 * Handles headings, bold, italic, code blocks, inline code, links, images,
 * lists, blockquotes, and horizontal rules.
 * Relative image URLs are resolved against the GitHub raw content URL.
 *
 * README content comes from arbitrary, untrusted GitHub repos, so link/image
 * URLs and alt text are sanitized before interpolation ÔÇö see sanitizeUrl()
 * and escapeAttributeQuotes() below.
 */
function markdownToHtml(markdown: string, repo: string): string {
  const rawBase = `https://raw.githubusercontent.com/${repo}/HEAD/`

  let html = markdown
    // Escape HTML entities first
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')

  // Code blocks (fenced)
  html = html.replace(/```[\s\S]*?```/g, (match) => {
    const content = match.replace(/```\w*\n?/, '').replace(/\n?```$/, '')
    return `<pre><code>${content}</code></pre>`
  })

  // Headings
  html = html.replace(/^######\s+(.+)$/gm, '<h6>$1</h6>')
  html = html.replace(/^#####\s+(.+)$/gm, '<h5>$1</h5>')
  html = html.replace(/^####\s+(.+)$/gm, '<h4>$1</h4>')
  html = html.replace(/^###\s+(.+)$/gm, '<h3>$1</h3>')
  html = html.replace(/^##\s+(.+)$/gm, '<h2>$1</h2>')
  html = html.replace(/^#\s+(.+)$/gm, '<h1>$1</h1>')

  // Horizontal rule
  html = html.replace(/^---+$/gm, '<hr>')

  // Images (before links since ![...] includes [...)
  html = html.replace(/!\[([^\]]*)\]\(([^)]+)\)/g, (_match, alt, src) => {
    const resolvedSrc = resolveUrl(src as string, rawBase)
    const safeSrc = escapeAttributeQuotes(sanitizeUrl(resolvedSrc))
    const safeAlt = escapeAttributeQuotes(alt as string)
    return `<img src="${safeSrc}" alt="${safeAlt}" />`
  })

  // Links
  html = html.replace(/\[([^\]]+)\]\(([^)]+)\)/g, (_match, text, href) => {
    const safeHref = escapeAttributeQuotes(sanitizeUrl(href as string))
    return `<a href="${safeHref}" target="_blank" rel="noopener noreferrer">${text as string}</a>`
  })

  // Bold
  html = html.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
  html = html.replace(/__(.+?)__/g, '<strong>$1</strong>')

  // Italic
  html = html.replace(/\*(.+?)\*/g, '<em>$1</em>')
  html = html.replace(/_(.+?)_/g, '<em>$1</em>')

  // Inline code
  html = html.replace(/`([^`]+)`/g, '<code>$1</code>')

  // Blockquotes
  html = html.replace(/^&gt;\s+(.+)$/gm, '<blockquote>$1</blockquote>')

  // Unordered lists
  html = html.replace(/^[-*]\s+(.+)$/gm, '<li>$1</li>')
  html = html.replace(/(<li>.*<\/li>\n?)+/g, '<ul>$&</ul>')

  // Paragraphs (lines not already wrapped in a block element)
  html = html.replace(/^(?!<[a-z]|$)(.+)$/gm, '<p>$1</p>')

  // Clean up empty paragraphs
  html = html.replace(/<p>\s*<\/p>/g, '')

  return html
}

/**
 * Resolves a potentially relative URL against a base URL.
 */
function resolveUrl(src: string, base: string): string {
  if (src.startsWith('http://') || src.startsWith('https://') || src.startsWith('//')) {
    return src
  }
  return base + src.replace(/^\.\//, '')
}

/** URL schemes allowed in href/src attributes rendered from an untrusted README. */
const SAFE_URL_SCHEME = /^(?:https?|mailto):/i

/**
 * Sanitizes a URL for use in an href/src attribute rendered from untrusted
 * README content (arbitrary GitHub repos). Only http(s)/mailto and
 * scheme-less (relative) URLs are allowed; anything else ÔÇö javascript:,
 * data:, vbscript:, etc. ÔÇö is replaced with a harmless fallback ('#').
 */
function sanitizeUrl(url: string): string {
  // Strip ASCII whitespace/control characters (code points 0-32) one by one.
  // Browsers ignore them when resolving a URL scheme (the classic
  // "java<TAB>script:" filter-bypass trick) ÔÇö without this, such a payload
  // would fail the scheme check below and be waved through as "relative".
  let stripped = ''
  for (const ch of url) {
    if (ch.charCodeAt(0) > 32) stripped += ch
  }
  const hasScheme = /^[a-z][a-z0-9+.-]*:/i.test(stripped)
  if (hasScheme && !SAFE_URL_SCHEME.test(stripped)) {
    return '#'
  }
  return stripped
}

/**
 * Escapes quote characters for safe interpolation inside a double-quoted
 * HTML attribute. `&`/`<`/`>` are already escaped by the entity pass at the
 * top of markdownToHtml, so only quotes need handling here.
 */
function escapeAttributeQuotes(value: string): string {
  return value.replace(/"/g, '&quot;').replace(/'/g, '&#39;')
}

/**
 * SettingsNavList ÔÇö Category and section navigation list for the settings sidebar.
 *
 * Renders sections grouped under category headings. Supports search filtering
 * (case-insensitive label matching), vault-section disabling when no vault is selected,
 * admin-section hiding for non-admin users, and keyboard navigation.
 *
 * @module components/settings/SettingsNavList
 */

import { useCallback, useRef } from 'react'
import type { SettingsAction, SettingsCategory, SettingsSection } from '../../state/settingsState'
import type { SettingsNavState } from '../../state/settingsState'
import type { ISettingsRegistry, ISettingsSectionDef } from '../../state/settingsRegistry'
import './SettingsNavList.css'

/**
 * German labels for settings sections used in search matching.
 * Maps section ID to its display label.
 */
const SECTION_LABELS: Record<SettingsSection, string> = {
  'profile': 'Profil',
  'password': 'Passwort ├ñndern',
  'sessions': 'Sitzungen',
  'mcp-tokens': 'MCP-Tokens',
  'keybindings': 'Tastaturk├╝rzel',
  'appearance': 'Darstellung',
  'my-vaults': 'Meine Vaults',
  'delete-account': 'Konto l├Âschen',
  'plugins': 'Plugins',
  'vault-config': 'Vault-Konfiguration',
  'server-config': 'Serverkonfiguration',
  'user-management': 'Benutzerverwaltung',
  'vault-management': 'Vault-Verwaltung',
  'feature-toggles': 'Feature-Toggles',
  'server-restart': 'Neustart',
}

/**
 * German labels for category headings.
 */
const CATEGORY_LABELS: Record<SettingsCategory, string> = {
  'account': 'Konto',
  'vault': 'Vault',
  'administration': 'Administration',
}

/** Props for the SettingsNavList component. */
export interface SettingsNavListProps {
  /** Current settings navigation state. */
  state: SettingsNavState
  /** Whether the current user has admin role. */
  isAdmin: boolean
  /** Section registry instance for querying available sections. */
  registry: ISettingsRegistry
  /** Dispatch function for settings actions. */
  dispatch: React.Dispatch<SettingsAction>
  /** Callback after navigation (for mobile close). */
  onNavSelect?: () => void
  /** The app's currently active vault ID (used to enable/disable vault sections). */
  activeVaultId?: string | null
}

/** A filtered section with its resolved label. */
interface ResolvedSection {
  def: ISettingsSectionDef
  label: string
}

/**
 * SettingsNavList ÔÇö Renders a grouped navigation list of settings sections.
 *
 * - Gets all visible categories via `registry.getCategories(isAdmin)`
 * - For each category, gets sections via `registry.getSections(category, isAdmin)`
 * - Filters sections by case-insensitive label match when searchQuery is non-empty
 * - Groups filtered results under category headings
 * - Shows "Keine Ergebnisse" message when no sections match
 * - Vault sections (requiresVault: true) are disabled when selectedVaultId is null
 * - Active section has aria-current="page"
 * - Keyboard: Arrow Up/Down to move focus, Enter to activate
 */
export function SettingsNavList({ state, isAdmin, registry, dispatch, onNavSelect, activeVaultId }: SettingsNavListProps) {
  const listRef = useRef<HTMLUListElement>(null)

  const handleSectionClick = useCallback((category: SettingsCategory, section: SettingsSection) => {
    dispatch({ type: 'NAVIGATE', payload: { category, section } })
    onNavSelect?.()
  }, [dispatch, onNavSelect])

  const handleKeyDown = useCallback((e: React.KeyboardEvent<HTMLUListElement>) => {
    if (e.key !== 'ArrowDown' && e.key !== 'ArrowUp') return

    e.preventDefault()
    const list = listRef.current
    if (list === null) return

    const buttons = Array.from(list.querySelectorAll<HTMLButtonElement>(
      'button.settings-nav-list__section-btn:not(:disabled)'
    ))
    if (buttons.length === 0) return

    const currentIndex = buttons.indexOf(document.activeElement as HTMLButtonElement)

    let nextIndex: number
    if (e.key === 'ArrowDown') {
      nextIndex = currentIndex < buttons.length - 1 ? currentIndex + 1 : 0
    } else {
      nextIndex = currentIndex > 0 ? currentIndex - 1 : buttons.length - 1
    }

    const nextBtn = buttons[nextIndex]
    if (nextBtn !== undefined) {
      nextBtn.focus()
    }
  }, [])

  // Build filtered sections grouped by category
  const categories = registry.getCategories(isAdmin)
  const query = state.searchQuery.trim().toLowerCase()

  const groupedSections: Array<{ category: SettingsCategory; sections: ResolvedSection[] }> = []

  for (const category of categories) {
    const sections = registry.getSections(category, isAdmin)
    const resolved: ResolvedSection[] = []

    for (const def of sections) {
      const label = SECTION_LABELS[def.id]
      if (query === '' || label.toLowerCase().includes(query)) {
        resolved.push({ def, label })
      }
    }

    if (resolved.length > 0) {
      groupedSections.push({ category, sections: resolved })
    }
  }

  // No results message
  if (groupedSections.length === 0) {
    return (
      <p className="settings-nav-list__no-results">
        Keine Ergebnisse
      </p>
    )
  }

  return (
    <ul
      ref={listRef}
      className="settings-nav-list"
      role="list"
      onKeyDown={handleKeyDown}
    >
      {groupedSections.map(({ category, sections }) => (
        <li key={category} role="presentation">
          <p className="settings-nav-list__category-heading">
            {CATEGORY_LABELS[category]}
          </p>
          <ul role="list" style={{ listStyle: 'none', margin: 0, padding: 0 }}>
            {sections.map(({ def, label }) => {
              const isActive = state.category === def.category && state.section === def.id
              const vaultId = activeVaultId !== undefined ? activeVaultId : state.selectedVaultId
              const isDisabled = def.requiresVault && vaultId === null

              return (
                <li key={def.id} role="presentation">
                  <button
                    type="button"
                    className="settings-nav-list__section-btn"
                    aria-current={isActive ? 'page' : undefined}
                    disabled={isDisabled}
                    onClick={() => { handleSectionClick(def.category, def.id) }}
                  >
                    {label}
                  </button>
                </li>
              )
            })}
          </ul>
        </li>
      ))}
    </ul>
  )
}

/**
 * SettingsPanel ÔÇö Main container component for the unified settings panel.
 * Renders a full-viewport overlay with sidebar navigation and content area.
 * Uses CSS Container Queries for responsive layout (700px threshold).
 *
 * @module components/settings/SettingsPanel
 */

import { useEffect, useCallback, useRef } from 'react'
import React from 'react'
import { useAuthContext } from '../../state/authContext'
import { matchesShortcut } from '../../state/keybindingsStore'
import { useAppContext } from '../../state'
import { SettingsProvider } from '../../state/settingsContext'
import { SettingsSidebar } from './SettingsSidebar'
import { SettingsContent } from './SettingsContent'
import type { SettingsCategory, SettingsSection } from '../../state/settingsState'
import './SettingsPanel.css'

/**
 * Props for the SettingsPanel component.
 */
export interface SettingsPanelProps {
  /** Whether the panel is visible. */
  open: boolean
  /** Callback to close the panel. */
  onClose: () => void
  /** Optional initial navigation for deep-links. */
  initialNav?: { category: SettingsCategory; section: SettingsSection }
}

/**
 * Unified settings panel that provides a categorized sidebar navigation
 * with an embedded content area. Wraps children in a SettingsProvider
 * for navigation state management.
 *
 * Features:
 * - Container-query-based responsive layout (sidebar left vs. stacked mobile)
 * - Ctrl+, keyboard shortcut registration
 * - Escape key / overlay click to close
 * - ARIA landmark roles for accessibility
 *
 * @param props - Component props
 */
export function SettingsPanel({ open, onClose, initialNav }: SettingsPanelProps) {
  const { authState } = useAuthContext()
  const { state: appState } = useAppContext()
  const panelRef = useRef<HTMLDivElement>(null)
  const previousFocusRef = useRef<HTMLElement | null>(null)

  const isAdmin = authState.user?.role === 'admin'

  const vaults = appState.vaults
    .filter(v => v.permission === 'owner')
    .map(v => ({ id: v.id, name: v.name }))

  // Store the previously focused element when opening
  useEffect(() => {
    if (open) {
      previousFocusRef.current = document.activeElement as HTMLElement | null
    }
  }, [open])

  // Focus the panel when it opens
  useEffect(() => {
    if (open && panelRef.current) {
      panelRef.current.focus()
    }
  }, [open])

  // Restore focus when closing
  useEffect(() => {
    if (!open && previousFocusRef.current) {
      previousFocusRef.current.focus()
      previousFocusRef.current = null
    }
  }, [open])

  // Handle Escape key to close
  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      if (e.key === 'Escape') {
        e.preventDefault()
        onClose()
      }
    },
    [onClose],
  )

  // Handle overlay click to close
  const handleOverlayClick = useCallback(
    (e: React.MouseEvent) => {
      if (e.target === e.currentTarget) {
        onClose()
      }
    },
    [onClose],
  )

  // Global Ctrl+, shortcut registration
  useEffect(() => {
    function handleGlobalKeyDown(e: KeyboardEvent) {
      if (matchesShortcut('slatebase:open-settings', e)) {
        e.preventDefault()
        if (!open) {
          // The parent component is responsible for opening the panel.
          // This effect handles the case where the panel is already open ÔÇö focus it.
          return
        }
        // Panel is already open ÔÇö focus it
        panelRef.current?.focus()
      }
    }

    document.addEventListener('keydown', handleGlobalKeyDown)
    return () => {
      document.removeEventListener('keydown', handleGlobalKeyDown)
    }
  }, [open])

  if (!open) {
    return null
  }

  return (
    <div
      className="settings-panel-overlay"
      onClick={handleOverlayClick}
      role="dialog"
      aria-modal="true"
      aria-label="Einstellungen"
    >
      <div
        className="settings-panel"
        ref={panelRef}
        tabIndex={-1}
        onKeyDown={handleKeyDown}
      >
        <header className="settings-panel-header">
          <h1 className="settings-panel-title">Einstellungen</h1>
          <button
            className="settings-panel-close-btn"
            onClick={onClose}
            aria-label="Einstellungen schlie├ƒen"
            type="button"
          >
            <svg
              width="18"
              height="18"
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
              aria-hidden="true"
            >
              <line x1="18" y1="6" x2="6" y2="18" />
              <line x1="6" y1="6" x2="18" y2="18" />
            </svg>
          </button>
        </header>

        <SettingsProvider isAdmin={isAdmin} vaults={vaults}>
          <SettingsPanelLayout initialNav={initialNav} />
        </SettingsProvider>
      </div>
    </div>
  )
}

/**
 * Props for the internal layout component.
 */
interface SettingsPanelLayoutProps {
  /** Optional initial navigation for deep-links. */
  initialNav?: { category: SettingsCategory; section: SettingsSection }
}

/**
 * Internal layout component that renders the sidebar and content
 * within the SettingsProvider context.
 * Separated so it can access SettingsContext via hooks.
 */
function SettingsPanelLayout({ initialNav }: SettingsPanelLayoutProps) {
  const [mobileNavOpen, setMobileNavOpen] = React.useState(false)

  const handleMobileToggle = useCallback(() => {
    setMobileNavOpen((prev) => !prev)
  }, [])

  const handleNavSelect = useCallback(() => {
    setMobileNavOpen(false)
  }, [])

  return (
    <div className="settings-panel-layout">
      <button
        className="settings-panel-mobile-toggle"
        onClick={handleMobileToggle}
        aria-expanded={mobileNavOpen}
        aria-controls="settings-sidebar"
        type="button"
      >
        <svg
          width="16"
          height="16"
          viewBox="0 0 24 24"
          fill="none"
          stroke="currentColor"
          strokeWidth="2"
          strokeLinecap="round"
          strokeLinejoin="round"
          aria-hidden="true"
        >
          <line x1="3" y1="6" x2="21" y2="6" />
          <line x1="3" y1="12" x2="21" y2="12" />
          <line x1="3" y1="18" x2="21" y2="18" />
        </svg>
        Navigation
      </button>

      <aside
        id="settings-sidebar"
        className="settings-panel-sidebar"
        role="navigation"
        aria-label="Einstellungen-Navigation"
        data-mobile-open={String(mobileNavOpen)}
      >
        <SettingsSidebar onNavSelect={handleNavSelect} initialNav={initialNav} />
      </aside>

      <section
        className="settings-panel-content"
        role="main"
        aria-label="Einstellungen-Inhalt"
      >
        <SettingsContent />
      </section>
    </div>
  )
}

/**
