  if (entries.length === 0) {
    return (
      <div className="recent-files-view recent-files-view--empty" role="region" aria-label="Zuletzt ge├Âffnet">
        <Clock size={24} className="recent-files-view__empty-icon" />
        <span className="recent-files-view__empty-text">Keine zuletzt ge├Âffneten Dateien</span>
      </div>
    )
  }

  return (
    <div className="recent-files-view" role="region" aria-label="Zuletzt ge├Âffnet">
      <ul className="recent-files-view__list" role="list">
        {entries.map((entry) => {
          const fileName = getFileName(entry.path)
          const IconComponent = getFileIcon(fileName)
          const iconClass = getFileIconClass(fileName)

          return (
            <li key={`${entry.vaultId}::${entry.path}`} className="recent-files-view__item">
              <button
                className="recent-files-view__entry"
                onClick={() => handleEntryClick(entry)}
                title={entry.path}
                type="button"
              >
                <span className={`recent-files-view__file-icon ${iconClass}`}>
                  <IconComponent size={14} />
                </span>
                <span className="recent-files-view__file-name">
                  {getDisplayName(fileName)}
                </span>
                <span className="recent-files-view__timestamp">
                  {formatRelativeTime(entry.timestamp)}
                </span>
              </button>
            </li>
          )
        })}
      </ul>
    </div>
  )
}

import { useState, useRef, useCallback } from 'react'
import { FolderOpen, Star, Clock } from 'lucide-react'
import type { SidebarViewId } from '../../state/sidebarPanelState'
import './SidebarPanelTabBar.css'

/** Tab metadata mapping view IDs to icons and labels. */
const TAB_CONFIG: Record<SidebarViewId, { icon: typeof FolderOpen; label: string }> = {
  explorer: { icon: FolderOpen, label: 'Dateien' },
  favorites: { icon: Star, label: 'Favoriten' },
  recent: { icon: Clock, label: 'Zuletzt ge├Âffnet' },
}

export interface SidebarPanelTabBarProps {
  tabs: SidebarViewId[]
  activeTab: SidebarViewId
  sectionId?: string
  onTabClick: (viewId: SidebarViewId) => void
  onTabReorder: (newOrder: SidebarViewId[]) => void
  onTabSplit: (viewId: SidebarViewId) => void
  onTabReceive?: (viewId: SidebarViewId, targetSectionId: string) => void
  panelWidth: number
}

/**
 * Tab bar for the sidebar panel with drag-and-drop reordering and split support.
 * Shows only icons with labels as tooltips on hover.
 * Supports HTML5 Drag API for reordering tabs and splitting into new sections.
 */
export function SidebarPanelTabBar({
  tabs,
  activeTab,
  sectionId,
  onTabClick,
  onTabReorder,
  onTabSplit,
  onTabReceive,
  panelWidth: _panelWidth,  
}: SidebarPanelTabBarProps) {
  const [draggedTab, setDraggedTab] = useState<SidebarViewId | null>(null)
  const [dropIndex, setDropIndex] = useState<number | null>(null)
  const tabBarRef = useRef<HTMLDivElement>(null)

  const isDraggable = sectionId !== undefined || tabs.length > 1

  const handleDragStart = useCallback((e: React.DragEvent, viewId: SidebarViewId) => {
    if (!isDraggable) {
      e.preventDefault()
      return
    }
    setDraggedTab(viewId)
    e.dataTransfer.effectAllowed = 'move'
    e.dataTransfer.setData('text/plain', viewId)
  }, [isDraggable])

  const handleDragOver = useCallback((e: React.DragEvent) => {
    e.preventDefault()
    e.dataTransfer.dropEffect = 'move'

    if (!tabBarRef.current) return

    const tabBarRect = tabBarRef.current.getBoundingClientRect()

    // Detect if dragging below the tab bar (30px threshold for split)
    if (draggedTab && e.clientY > tabBarRect.bottom + 30) {
      setDropIndex(null)
      return
    }

    if (
      e.clientX < tabBarRect.left ||
      e.clientX > tabBarRect.right ||
      e.clientY < tabBarRect.top ||
      e.clientY > tabBarRect.bottom
    ) {
      setDropIndex(null)
      return
    }

    const tabElements = tabBarRef.current.querySelectorAll('[data-tab-id]')
    let newDropIndex = tabs.length

    for (let i = 0; i < tabElements.length; i++) {
      const tabEl = tabElements[i] as HTMLElement
      const rect = tabEl.getBoundingClientRect()
      const midX = rect.left + rect.width / 2

      if (e.clientX < midX) {
        newDropIndex = i
        break
      }
    }

    if (draggedTab) {
      const draggedIndex = tabs.indexOf(draggedTab)
      if (newDropIndex === draggedIndex || newDropIndex === draggedIndex + 1) {
        setDropIndex(null)
      } else {
        setDropIndex(newDropIndex)
      }
    } else {
      setDropIndex(newDropIndex)
    }
  }, [draggedTab, tabs])

  const handleDragLeave = useCallback((e: React.DragEvent) => {
    if (!tabBarRef.current?.contains(e.relatedTarget as Node)) {
      setDropIndex(null)
    }
  }, [])

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault()
    e.stopPropagation()

    const droppedViewId = e.dataTransfer.getData('text/plain') as SidebarViewId

    if (!tabBarRef.current) {
      setDraggedTab(null)
      setDropIndex(null)
      return
    }

    const tabBarRect = tabBarRef.current.getBoundingClientRect()

    // Check if dropped 30px below the tab bar ÔåÆ split
    if (draggedTab && e.clientY > tabBarRect.bottom + 30) {
      onTabSplit(draggedTab)
      setDraggedTab(null)
      setDropIndex(null)
      return
    }

    if (
      e.clientX < tabBarRect.left ||
      e.clientX > tabBarRect.right ||
      e.clientY < tabBarRect.top ||
      e.clientY > tabBarRect.bottom
    ) {
      setDraggedTab(null)
      setDropIndex(null)
      return
    }

    // Cross-section move
    if (droppedViewId && !tabs.includes(droppedViewId) && sectionId && onTabReceive) {
      onTabReceive(droppedViewId, sectionId)
      setDraggedTab(null)
      setDropIndex(null)
      return
    }

    // Same-section reorder
    if (!draggedTab) {
      setDraggedTab(null)
      setDropIndex(null)
      return
    }

    const tabElements = tabBarRef.current.querySelectorAll('[data-tab-id]')
    let finalDropIndex = tabs.length

    for (let i = 0; i < tabElements.length; i++) {
      const tabEl = tabElements[i] as HTMLElement
      const rect = tabEl.getBoundingClientRect()
      const midX = rect.left + rect.width / 2

      if (e.clientX < midX) {
        finalDropIndex = i
        break
      }
    }

    const draggedIndex = tabs.indexOf(draggedTab)
    if (draggedIndex !== -1 && finalDropIndex !== draggedIndex && finalDropIndex !== draggedIndex + 1) {
      const newOrder = [...tabs]
      newOrder.splice(draggedIndex, 1)
      const insertAt = finalDropIndex > draggedIndex ? finalDropIndex - 1 : finalDropIndex
      newOrder.splice(insertAt, 0, draggedTab)
      onTabReorder(newOrder)
    }

    setDraggedTab(null)
    setDropIndex(null)
  }, [draggedTab, tabs, sectionId, onTabReorder, onTabSplit, onTabReceive])

  const handleDragEnd = useCallback(() => {
    setDraggedTab(null)
    setDropIndex(null)
  }, [])

  return (
    <div
      ref={tabBarRef}
      className="sidebar-panel-tab-bar sidebar-panel-tab-bar--icon-only"
      role="tablist"
      aria-label="Sidebar-Panel Ansichten"
      onDragOver={handleDragOver}
      onDragLeave={handleDragLeave}
      onDrop={handleDrop}
    >
      {tabs.map((viewId, index) => {
        const config = TAB_CONFIG[viewId]
        const Icon = config.icon
        const isActive = viewId === activeTab
        const isDragging = viewId === draggedTab
        const showInsertBefore = dropIndex === index

        return (
          <div key={viewId} className="sidebar-panel-tab-wrapper">
            {showInsertBefore && (
              <div className="sidebar-panel-tab-insert-line" aria-hidden="true" />
            )}
            <button
              type="button"
              role="tab"
              data-tab-id={viewId}
              aria-selected={isActive}
              aria-label={config.label}
              title={config.label}
              className={`sidebar-panel-tab${isActive ? ' sidebar-panel-tab--active' : ''}${isDragging ? ' sidebar-panel-tab--dragging' : ''}`}
              onClick={() => onTabClick(viewId)}
              draggable={isDraggable}
              onDragStart={(e) => handleDragStart(e, viewId)}
              onDragEnd={handleDragEnd}
            >
              <Icon size={14} className="sidebar-panel-tab-icon" />
            </button>
          </div>
        )
      })}
      {dropIndex === tabs.length && (
        <div className="sidebar-panel-tab-wrapper">
          <div className="sidebar-panel-tab-insert-line" aria-hidden="true" />
        </div>
      )}
    </div>
  )
}

/**
 * SidebarSplitContainer component.
 *
 * Renders split sections as vertically stacked areas with resize handles.
 * Each section displays its own TabBar (if multiple views) and
 * the active view content via the renderView prop.
 *
 * Identical behavior to the right-side SplitSectionContainer but typed
 * for SidebarViewId and SidebarSplitSection.
 */

import { useRef, useState, useCallback, useEffect } from 'react'
import { SidebarPanelTabBar } from './SidebarPanelTabBar'
import type { SidebarSplitSection, SidebarViewId } from '../../state/sidebarPanelState'
import './SidebarSplitContainer.css'

// ÔöÇÔöÇÔöÇ Constants ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

/** Minimum section height in pixels. */
const MIN_SECTION_HEIGHT = 80

// ÔöÇÔöÇÔöÇ Props ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

export interface SidebarSplitContainerProps {
  /** Array of split sections to render. */
  sections: SidebarSplitSection[]
  /** Panel width in pixels (passed to TabBar for responsive behavior). */
  panelWidth: number
  /** Panel body height in pixels (used to compute minimum height fractions during resize). */
  panelHeight: number
  /** Callback when a tab is clicked within a section. */
  onTabClick: (sectionId: string, viewId: SidebarViewId) => void
  /** Callback when tabs are reordered within a section. */
  onTabReorder: (sectionId: string, newOrder: SidebarViewId[]) => void
  /** Callback when a tab is split into a new section. */
  onTabSplit: (viewId: SidebarViewId) => void
  /** Callback when a tab is moved from one section to another. */
  onTabMove: (viewId: SidebarViewId, targetSectionId: string) => void
  /** Callback when section heights change (array of fractions summing to 1). */
  onResize: (heightFractions: number[]) => void
  /** Render function that returns the view component for a given viewId. */
  renderView: (viewId: SidebarViewId) => React.ReactNode
}

// ÔöÇÔöÇÔöÇ Component ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

/**
 * Renders split sections of the sidebar panel as vertically stacked areas.
 * Each section has its own TabBar (if multiple views) and is separated by
 * a 4px resize handle from adjacent sections.
 */
export function SidebarSplitContainer({
  sections,
  panelWidth,
  panelHeight,
  onTabClick,
  onTabReorder,
  onTabSplit,
  onTabMove,
  onResize,
  renderView,
}: SidebarSplitContainerProps) {
  const containerRef = useRef<HTMLDivElement>(null)
  const [resizingIndex, setResizingIndex] = useState<number | null>(null)
  const [showDropIndicator, setShowDropIndicator] = useState(false)
  const startYRef = useRef(0)
  const startFractionsRef = useRef<number[]>([])

  // ÔöÇÔöÇÔöÇ Resize Logic ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

  const handleResizeStart = useCallback((e: React.MouseEvent, handleIndex: number) => {
    e.preventDefault()
    setResizingIndex(handleIndex)
    startYRef.current = e.clientY
    startFractionsRef.current = sections.map((s) => s.heightFraction)
  }, [sections])

  useEffect(() => {
    if (resizingIndex === null) return

    const handleMouseMove = (e: MouseEvent) => {
      const containerHeight = panelHeight
      if (containerHeight <= 0) return

      const deltaY = e.clientY - startYRef.current
      const deltaFraction = deltaY / containerHeight

      const fractions = [...startFractionsRef.current]
      const topFraction = fractions[resizingIndex]
      const bottomFraction = fractions[resizingIndex + 1]

      if (topFraction === undefined || bottomFraction === undefined) return

      let newTop = topFraction + deltaFraction
      let newBottom = bottomFraction - deltaFraction

      const minFraction = MIN_SECTION_HEIGHT / containerHeight

      if (newTop < minFraction) {
        newTop = minFraction
        newBottom = topFraction + bottomFraction - minFraction
      }
      if (newBottom < minFraction) {
        newBottom = minFraction
        newTop = topFraction + bottomFraction - minFraction
      }

      fractions[resizingIndex] = newTop
      fractions[resizingIndex + 1] = newBottom

      onResize(fractions)
    }

    const handleMouseUp = () => {
      setResizingIndex(null)
    }

    document.addEventListener('mousemove', handleMouseMove)
    document.addEventListener('mouseup', handleMouseUp)

    return () => {
      document.removeEventListener('mousemove', handleMouseMove)
      document.removeEventListener('mouseup', handleMouseUp)
    }
  }, [resizingIndex, onResize, panelHeight])

  // ÔöÇÔöÇÔöÇ Drop Indicator Logic ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

  const handleDragOver = useCallback((e: React.DragEvent) => {
    e.preventDefault()
    e.dataTransfer.dropEffect = 'move'

    if (containerRef.current) {
      const rect = containerRef.current.getBoundingClientRect()
      const isInDropZone = e.clientY > rect.top + rect.height * 0.7
      setShowDropIndicator(isInDropZone)
    }
  }, [])

  const handleDragLeave = useCallback((e: React.DragEvent) => {
    if (!containerRef.current?.contains(e.relatedTarget as Node)) {
      setShowDropIndicator(false)
    }
  }, [])

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault()
    setShowDropIndicator(false)

    const viewId = e.dataTransfer.getData('text/plain') as SidebarViewId
    if (viewId) {
      onTabSplit(viewId)
    }
  }, [onTabSplit])

  // ÔöÇÔöÇÔöÇ Render ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

  return (
    <div
      ref={containerRef}
      className={`sidebar-split-container${resizingIndex !== null ? ' sidebar-split-container--resizing' : ''}`}
      onDragOver={handleDragOver}
      onDragLeave={handleDragLeave}
      onDrop={handleDrop}
    >
      {sections.map((section, index) => {
        const heightPercent = section.heightFraction * 100

        return (
          <div key={section.id} className="sidebar-split-wrapper">
            {index > 0 && (
              <div
                className={`sidebar-split-resize-handle${resizingIndex === index - 1 ? ' sidebar-split-resize-handle--active' : ''}`}
                onMouseDown={(e) => handleResizeStart(e, index - 1)}
                role="separator"
                aria-orientation="horizontal"
                aria-label="Bereichsgr├Â├ƒe anpassen"
              />
            )}

            <div
              className="sidebar-split-section"
              style={{ height: `${heightPercent}%` }}
              data-section-id={section.id}
            >
              {sections.length > 1 && (
                <SidebarPanelTabBar
                  tabs={section.viewIds}
                  activeTab={section.activeViewId}
                  sectionId={section.id}
                  onTabClick={(viewId) => onTabClick(section.id, viewId)}
                  onTabReorder={(newOrder) => onTabReorder(section.id, newOrder)}
                  onTabSplit={onTabSplit}
                  onTabReceive={onTabMove}
                  panelWidth={panelWidth}
                />
              )}

              <div className="sidebar-split-content">
                {renderView(section.activeViewId)}
              </div>
            </div>
          </div>
        )
      })}

      {showDropIndicator && (
        <div className="sidebar-split-drop-indicator" aria-hidden="true">
          <div className="sidebar-split-drop-indicator-line" />
        </div>
      )}
    </div>
  )
}
